// backfillSQLiteChatPollNullableColumns repairs legacy rows whose optional
// scalar projection is still NULL even though the versioned full pass has
// completed. The query is intentionally bounded and the update clears every
// nullable field for an invalid row so one opaque row cannot trigger the same
// scan forever.
func backfillSQLiteChatPollNullableColumnsLegacy(db *sql.DB) error {
	scheduleValid := sqliteChatPollScheduleValidJSONSQL("json", "chat_id")
	rows, err := db.Query(`SELECT chat_id, `+sqliteStoredInt64SQL("next_poll_at")+`, `+sqliteStoredInt64SQL("blocked_until")+`, poll_state, `+
		sqliteStoredInt64SQL("last_activity_at")+`, `+sqliteStoredInt64SQL("park_notice_sent_at")+`, `+
		sqliteStoredInt64SQL("parked_skip_eligible")+`, `+sqliteStoredInt64SQL("frontier_active")+`, `+
		sqliteStoredInt64SQL("admission_valid")+`, `+sqliteStoredInt64SQL("poll_failure_count")+`, `+
		sqliteStoredInt64SQL("pending_page_active")+`, `+sqliteStoredInt64SQL("attempt_active")+`, `+sqliteStoredInt64SQL("updated_at")+`, CASE WHEN `+scheduleValid+` THEN 1 ELSE 0 END, json
FROM chat_polls
WHERE next_poll_at IS NULL OR blocked_until IS NULL OR poll_state IS NULL OR last_activity_at IS NULL OR
      park_notice_sent_at IS NULL OR parked_skip_eligible IS NULL OR frontier_active IS NULL OR
      admission_valid IS NULL OR updated_at IS NULL
ORDER BY chat_id LIMIT ?`, sqliteProjectionBackfillBatchSize)
	if err != nil {
		return err
	}
	type updateRow struct {
		chatID, pollState                                                                            string
		next, blocked, activity, notice, parked, frontier, valid, failure, pending, attempt, updated int64
		trusted                                                                                      bool
		raw                                                                                          []byte
	}
	updates := make([]updateRow, 0, sqliteProjectionBackfillBatchSize)
	for rows.Next() {
		var chatID string
		var next, blocked, activity, notice, parked, frontier, valid, failure, pending, attempt, updated sql.NullInt64
		var pollState sql.NullString
		var scheduleValidValue int64
		var raw []byte
		if err := rows.Scan(&chatID, &next, &blocked, &pollState, &activity, &notice, &parked, &frontier, &valid, &failure, &pending, &attempt, &updated, &scheduleValidValue, &raw); err != nil {
			_ = rows.Close()
			return err
		}
		chatID = strings.TrimSpace(chatID)
		if chatID == "" {
			continue
		}
		row := updateRow{
			chatID:    chatID,
			pollState: nullableStringValue(pollState),
			next:      nullableInt64Value(next), blocked: nullableInt64Value(blocked),
			activity: nullableInt64Value(activity), notice: nullableInt64Value(notice),
			parked: nullableInt64Value(parked), frontier: nullableInt64Value(frontier),
			valid: nullableInt64Value(valid), failure: nullableInt64Value(failure),
			pending: nullableInt64Value(pending), attempt: nullableInt64Value(attempt), updated: nullableInt64Value(updated),
			raw: append([]byte(nil), raw...),
		}
		var object map[string]json.RawMessage
		var poll ChatPollState
		admissionOK := scheduleValidValue != 0 && jsonValueHasNoDuplicateKeys(raw) && json.Unmarshal(raw, &object) == nil && object != nil &&
			json.Unmarshal(raw, &poll) == nil && strings.TrimSpace(poll.ChatID) == chatID && chatPollAdmissionValid(poll)
		if !admissionOK {
			// Keep the existing liveness sidecars. The canonical row is not
			// executable, but its retry/recovery/frontier evidence must not be
			// erased by this repair pass. Revoke admission below and leave the
			// row untrusted until a canonical repair succeeds.
			row.valid = 0
			row.trusted = false
		} else {
			if sqliteJSONFieldPresent(raw, "next_poll_at") {
				row.next = sqliteTime(poll.NextPollAt)
			}
			if sqliteJSONFieldPresent(raw, "blocked_until") {
				row.blocked = sqliteTime(poll.BlockedUntil)
			}
			if sqliteJSONFieldPresent(raw, "state") {
				row.pollState = poll.PollState
			}
			if sqliteJSONFieldPresent(raw, "last_activity_at") {
				row.activity = sqliteTime(poll.LastActivityAt)
			}
			if sqliteJSONFieldPresent(raw, "park_notice_sent_at") {
				row.notice = sqliteTime(poll.ParkNoticeSentAt)
			}
			if sqliteJSONFieldPresent(raw, "updated_at") {
				row.updated = sqliteTime(poll.UpdatedAt)
			}
			row.parked = sqliteBool(chatPollParkedSkipEligible(poll))
			row.frontier = sqliteBool(chatPollHasOperationalFrontier(poll))
			row.failure = int64(chatPollFailureCount(poll))
			row.pending = sqliteBool(chatPollHasPendingPage(poll))
			row.attempt = sqliteBool(poll.Attempt != nil)
			row.valid = 1
			row.trusted = true
		}
		updates = append(updates, row)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}
	if len(updates) == 0 {
		return nil
	}
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()
	stmt, err := tx.Prepare(`UPDATE chat_polls SET next_poll_at = ?, blocked_until = ?, poll_state = ?, last_activity_at = ?, park_notice_sent_at = ?, parked_skip_eligible = ?, frontier_active = ?, admission_valid = ?, poll_failure_count = ?, pending_page_active = ?, attempt_active = ?, updated_at = ?, canonical_revision = COALESCE(canonical_revision, 0) + 1, projection_revision = CASE WHEN ? != 0 THEN COALESCE(canonical_revision, 0) + 1 ELSE 0 END, projection_trusted = ? WHERE chat_id = ? AND json = ?`)
	if err != nil {
		return err
	}
	for _, row := range updates {
		trusted := 0
		if row.trusted {
			trusted = 1
		}
		if _, err := stmt.Exec(row.next, row.blocked, row.pollState, row.activity, row.notice, row.parked, row.frontier, row.valid, row.failure, row.pending, row.attempt, row.updated, trusted, trusted, row.chatID, row.raw); err != nil {
			_ = stmt.Close()
			return err
		}
	}
	if err := stmt.Close(); err != nil {
		return err
	}
	return tx.Commit()
}

func backfillSQLiteInboundDerivedColumnsLegacy(db *sql.DB) error {
	version, err := sqliteReadMetaValue(db, sqliteInboundProjectionVersionKey)
	if err != nil {
		return err
	}
	cursorKey := sqliteBackfillCursorKey(sqliteInboundProjectionVersionKey)
	cursorValue, err := sqliteReadMetaValue(db, cursorKey)
	if err != nil {
		return err
	}
	cursor, cursorPresent := sqliteBackfillCursorID(cursorValue, sqliteInboundProjectionVersion)
	if strings.TrimSpace(version) == sqliteInboundProjectionVersion && !cursorPresent {
		return nil
	}
	rows, err := db.Query(`SELECT id, `+sqliteStoredInt64SQL("received_at")+`, json FROM inbound_events WHERE id > ? ORDER BY id LIMIT ?`, cursor, sqliteProjectionBackfillBatchSize)
	if err != nil {
		return err
	}
	type inboundProjectionUpdate struct {
		id             string
		currentReceive sql.NullInt64
		canonical      string
		receivedAt     int64
		valid          bool
		raw            []byte
	}
	updates := make([]inboundProjectionUpdate, 0, sqliteProjectionBackfillBatchSize)
	lastID := cursor
	rowCount := 0
	for rows.Next() {
		var id string
		var currentReceived sql.NullInt64
		var raw []byte
		if err := rows.Scan(&id, &currentReceived, &raw); err != nil {
			_ = rows.Close()
			return err
		}
		rowCount++
		lastID = id
		canonicalStatus, receivedAt, valid := sqliteInboundStatusProjectionFromJSON(id, raw)
		updates = append(updates, inboundProjectionUpdate{
			id:             id,
			currentReceive: currentReceived,
			canonical:      canonicalStatus,
			receivedAt:     receivedAt,
			valid:          valid,
			raw:            append([]byte(nil), raw...),
		})
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}
	complete := rowCount < sqliteProjectionBackfillBatchSize
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()
	stmt, err := tx.Prepare(`UPDATE inbound_events
SET status = CASE WHEN ? != 0 THEN ? ELSE status END,
    received_at = CASE WHEN received_at IS NULL THEN ? ELSE received_at END,
    canonical_revision = CASE WHEN COALESCE(canonical_revision, 0) > 0 THEN COALESCE(canonical_revision, 0) + 1 ELSE 1 END,
    projection_revision = CASE WHEN ? != 0 THEN CASE WHEN COALESCE(canonical_revision, 0) > 0 THEN COALESCE(canonical_revision, 0) + 1 ELSE 1 END ELSE 0 END,
    projection_trusted = ?
WHERE id = ? AND json = ?`)
	if err != nil {
		return err
	}
	for _, update := range updates {
		trusted := 0
		if update.valid {
			trusted = 1
		}
		receivedAt := update.receivedAt
		if update.currentReceive.Valid {
			receivedAt = update.currentReceive.Int64
		}
		result, err := stmt.Exec(update.valid, update.canonical, receivedAt, update.valid, trusted, update.id, update.raw)
		if err != nil {
			_ = stmt.Close()
			return err
		}
		applied, err := result.RowsAffected()
		if err != nil {
			_ = stmt.Close()
			return err
		}
		if applied != 1 {
			// The canonical row changed between the read and this repair
			// transaction. Keep the cursor at the last row that was actually
			// repaired (or at its original value when this was the first row); a
			// later schema pass must inspect the replacement before publishing
			// completion, without needlessly replaying earlier successful rows.
			complete = false
			break
		}
		lastID = update.id
	}
	if err := stmt.Close(); err != nil {
		return err
	}
	if complete {
		if err := sqliteWriteMetaValue(tx, sqliteInboundProjectionVersionKey, sqliteInboundProjectionVersion); err != nil {
			return err
		}
		if err := sqliteDeleteMetaValue(tx, sqliteBackfillCursorKey(sqliteInboundProjectionVersionKey)); err != nil {
			return err
		}
	} else if err := sqliteWriteMetaValue(tx, sqliteBackfillCursorKey(sqliteInboundProjectionVersionKey), sqliteBackfillCursorValue(sqliteInboundProjectionVersion, lastID)); err != nil {
		return err
	}
	return tx.Commit()
}

// sqliteInboundStatusProjectionFromJSON extracts only the identity/status
// proof needed by the indexed inbound backlog lane. Missing or non-string
// fields deliberately make the row untrusted; the canonical JSON oracle then
// remains responsible for deciding whether the event is actionable.
func sqliteInboundStatusProjectionFromJSON(id string, raw []byte) (status string, receivedAt int64, valid bool) {
	var object map[string]json.RawMessage
	if strings.TrimSpace(id) == "" || !jsonValueHasNoDuplicateKeys(raw) || json.Unmarshal(raw, &object) != nil || object == nil {
		return "", 0, false
	}
	var event InboundEvent
	if json.Unmarshal(raw, &event) != nil || strings.TrimSpace(event.ID) != strings.TrimSpace(id) {
		return "", 0, false
	}
	statusRaw, ok := object["status"]
	if !ok || json.Unmarshal(statusRaw, &status) != nil {
		return "", 0, false
	}
	if !event.ReceivedAt.IsZero() {
		receivedAt = sqliteTime(event.ReceivedAt)
	}
	return status, receivedAt, true
}

// ensureSQLiteRuntimeProjectionMarker distinguishes a genuinely legacy
// SQLite store (no runtime rows yet) from a store whose runtime projection was
// started by an older helper but is now partial. The latter must not silently
// fall back to state_json, because that cold snapshot may predate a newer
// owner/lease write. A genuinely legacy store is materialized once from its
// cold snapshot so the hot path does not repeat a full decode on every poll.
func ensureSQLiteRuntimeProjectionMarker(db *sql.DB) error {
	var marker []byte
	err := db.QueryRow(`SELECT value FROM state_meta WHERE key = ?`, sqliteRuntimeProjectionMaterializedKey).Scan(&marker)
	markerPresent := err == nil
	if err != nil && !errors.Is(err, sql.ErrNoRows) {
		return err
	}
	// The marker is a capability bit, not a substitute for the required rows.
	// Structural repair can recreate an empty runtime_state table while leaving
	// the old materialization marker in state_meta.  Publishing the structural
	// ready marker in that state would let lease/liveness callers open a database
	// whose ownership projection is empty.  A partially populated projection is
	// also unsafe to reconstruct from state_json: its existing rows may contain a
	// newer lease, so explicit repair must fail closed instead of overwriting it.
	requiredRows, err := sqliteRuntimeRequiredRowCount(db)
	if err != nil {
		return err
	}
	if requiredRows == len(sqliteRuntimeRequiredKeys) {
		if !markerPresent {
			_, err = db.Exec(`INSERT INTO state_meta(key, value) VALUES (?, ?)
ON CONFLICT(key) DO NOTHING`, sqliteRuntimeProjectionMaterializedKey, sqliteRuntimeProjectionMaterializedValue)
		}
		return err
	}
	if requiredRows != 0 {
		return sqliteRuntimeProjectionIncompleteError("required runtime rows are incomplete")
	}
	var one int
	err = db.QueryRow(`SELECT 1 FROM runtime_state LIMIT 1`).Scan(&one)
	if err == nil {
		return sqliteRuntimeProjectionIncompleteError("runtime projection contains no complete required row set")
	}
	if !errors.Is(err, sql.ErrNoRows) {
		return err
	}

	// This is the only compatibility path that decodes state_json for runtime
	// projection bootstrap. It runs while the database is first opened and the
	// successful transaction below installs the marker, so subsequent hot reads
	// never return to the cold document. If the legacy cold snapshot is corrupt,
	// fail closed rather than inventing an owner/lease binding.
	var raw []byte
	err = db.QueryRow(`SELECT value FROM state_meta WHERE key = 'state_json'`).Scan(&raw)
	if errors.Is(err, sql.ErrNoRows) {
		return nil
	}
	if err != nil {
		return err
	}
	if len(bytes.TrimSpace(raw)) == 0 {
		return errors.New("sqlite teams store has empty state metadata")
	}
	state, err := loadStateData(raw)
	if err != nil {
		return fmt.Errorf("bootstrap sqlite runtime projection: %w", err)
	}
	state.ensure(time.Time{})

	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()
	// Recheck after acquiring the write transaction. This keeps the bootstrap
	// idempotent if two open paths race before sharing the database handle.
	if err := tx.QueryRow(`SELECT value FROM state_meta WHERE key = ?`, sqliteRuntimeProjectionMaterializedKey).Scan(&marker); err == nil {
		requiredRows, countErr := sqliteRuntimeRequiredRowCount(tx)
		if countErr != nil {
			return countErr
		}
		if requiredRows == len(sqliteRuntimeRequiredKeys) {
			return tx.Commit()
		}
		if requiredRows != 0 {
			return sqliteRuntimeProjectionIncompleteError("required runtime rows are incomplete")
		}
	} else if !errors.Is(err, sql.ErrNoRows) {
		return err
	}
	if requiredRows, countErr := sqliteRuntimeRequiredRowCount(tx); countErr != nil {
		return countErr
	} else if requiredRows != 0 {
		return sqliteRuntimeProjectionIncompleteError("required runtime rows are incomplete")
	}
	if err := tx.QueryRow(`SELECT 1 FROM runtime_state LIMIT 1`).Scan(&one); err == nil {
		return sqliteRuntimeProjectionIncompleteError("runtime projection contains no complete required row set")
	} else if !errors.Is(err, sql.ErrNoRows) {
		return err
	}
	if err := saveSQLiteRuntimeStateTx(context.Background(), tx, state); err != nil {
		return err
	}
	return tx.Commit()
}

func sqliteRuntimeRequiredRowCount(q interface {
	QueryRow(string, ...any) *sql.Row
}) (int, error) {
	var count int
	err := q.QueryRow(`SELECT COUNT(*) FROM runtime_state WHERE key IN (?, ?, ?, ?, ?, ?)`,
		sqliteRuntimeRequiredKeys[0], sqliteRuntimeRequiredKeys[1], sqliteRuntimeRequiredKeys[2],
		sqliteRuntimeRequiredKeys[3], sqliteRuntimeRequiredKeys[4], sqliteRuntimeRequiredKeys[5]).Scan(&count)
	return count, err
}

func sqliteRuntimeRequiredRowCountContext(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}) (int, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	var count int
	err := q.QueryRowContext(ctx, `SELECT COUNT(*) FROM runtime_state WHERE key IN (?, ?, ?, ?, ?, ?)`,
		sqliteRuntimeRequiredKeys[0], sqliteRuntimeRequiredKeys[1], sqliteRuntimeRequiredKeys[2],
		sqliteRuntimeRequiredKeys[3], sqliteRuntimeRequiredKeys[4], sqliteRuntimeRequiredKeys[5]).Scan(&count)
	return count, err
}

func backfillSQLiteChatSequencesLegacy(db *sql.DB) error {
	return backfillSQLiteChatSequencesLegacyContext(context.Background(), db)
}

func backfillSQLiteChatSequencesLegacyContext(ctx context.Context, db *sql.DB) error {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	version, err := sqliteReadMetaValueContext(ctx, db, sqliteChatSequenceProjectionVersionKey)
	if err != nil {
		return err
	}
	cursorKey := sqliteBackfillCursorKey(sqliteChatSequenceProjectionVersionKey)
	cursorValue, err := sqliteReadMetaValueContext(ctx, db, cursorKey)
	if err != nil {
		return err
	}
	_, cursorPresent := sqliteBackfillCursorID(cursorValue, sqliteChatSequenceProjectionVersion)
	var existing int
	existingErr := db.QueryRowContext(ctx, `SELECT 1 FROM chat_sequences LIMIT 1`).Scan(&existing)
	if existingErr != nil && !errors.Is(existingErr, sql.ErrNoRows) {
		return existingErr
	}
	if strings.TrimSpace(version) == sqliteChatSequenceProjectionVersion && !cursorPresent {
		if existingErr == nil {
			return nil
		}
		// A completed marker beside an empty projection is only safe when the
		// cold document has no sequence entries.  A full-state rewrite or an
		// interrupted legacy migration can otherwise leave the marker current
		// while the table is empty; probe just the sequence object before
		// deciding that there is nothing to repair.
		var one int
		err := db.QueryRowContext(ctx, `SELECT 1 FROM state_meta AS meta,
     json_each(CASE WHEN json_valid(meta.value)
                    THEN COALESCE(json_extract(meta.value, '$.chat_sequences'), '{}')
                    ELSE '{}' END)
WHERE meta.key = 'state_json' LIMIT 1`).Scan(&one)
		if errors.Is(err, sql.ErrNoRows) {
			return nil
		}
		if err != nil {
			return err
		}
	}
	sourceRevision, err := sqliteStateJSONRevision(ctx, db)
	if err != nil {
		return err
	}
	cursor, _ := sqliteBackfillCursorID(cursorValue, sqliteChatSequenceProjectionVersion)
	// json_each walks only the chat_sequences object in the cold document. It
	// avoids decoding the entire State in Go and, unlike the old implementation,
	// persists a keyset cursor after every bounded page.
	rows, err := db.QueryContext(ctx, `SELECT entries.key, entries.value
FROM state_meta AS meta,
     json_each(CASE WHEN json_valid(meta.value)
                    THEN COALESCE(json_extract(meta.value, '$.chat_sequences'), '{}')
                    ELSE '{}' END) AS entries
WHERE meta.key = 'state_json' AND entries.key > ?
ORDER BY entries.key LIMIT ?`, cursor, sqliteProjectionBackfillBatchSize)
	if err != nil {
		return err
	}
	type sequenceProjectionUpdate struct {
		chatID string
		seq    ChatSequenceState
		raw    []byte
	}
	updates := make([]sequenceProjectionUpdate, 0, sqliteProjectionBackfillBatchSize)
	lastID := cursor
	rowCount := 0
	for rows.Next() {
		if err := ctx.Err(); err != nil {
			_ = rows.Close()
			return err
		}
		var chatID string
		var raw []byte
		if err := rows.Scan(&chatID, &raw); err != nil {
			_ = rows.Close()
			return err
		}
		rowCount++
		lastID = chatID
		var seq ChatSequenceState
		if json.Unmarshal(raw, &seq) != nil {
			continue
		}
		seq.ChatID = strings.TrimSpace(seq.ChatID)
		if seq.ChatID == "" {
			seq.ChatID = strings.TrimSpace(chatID)
		}
		if seq.ChatID == "" || seq.ChatID != strings.TrimSpace(chatID) {
			continue
		}
		updates = append(updates, sequenceProjectionUpdate{chatID: seq.ChatID, seq: seq, raw: raw})
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}
	if sqliteChatSequenceBackfillTestHook != nil {
		if err := sqliteChatSequenceBackfillTestHook(db); err != nil {
			return err
		}
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	complete := rowCount < sqliteProjectionBackfillBatchSize
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	currentRevision, err := sqliteStateJSONRevision(ctx, tx)
	if err != nil {
		return err
	}
	if currentRevision != sourceRevision {
		return errSQLiteBackfillSourceChanged
	}
	// INSERT OR IGNORE is intentional. A table that already contains rows may
	// be newer than the cold state snapshot (for example after an outbox write),
	// so migration may fill missing keys but must never overwrite an existing
	// durable sequence with an older JSON value.
	stmt, err := tx.PrepareContext(ctx, `INSERT OR IGNORE INTO chat_sequences(chat_id, next_sequence, updated_at, json) VALUES (?, ?, ?, ?)`)
	if err != nil {
		return err
	}
	for _, update := range updates {
		if err := ctx.Err(); err != nil {
			_ = stmt.Close()
			return err
		}
		if _, err := stmt.ExecContext(ctx, update.chatID, update.seq.Next, sqliteTime(update.seq.UpdatedAt), update.raw); err != nil {
			_ = stmt.Close()
			return err
		}
	}
	if err := stmt.Close(); err != nil {
		return err
	}
	if complete {
		if err := sqliteWriteMetaValueContext(ctx, tx, sqliteChatSequenceProjectionVersionKey, sqliteChatSequenceProjectionVersion); err != nil {
			return err
		}
		if err := sqliteDeleteMetaValueContext(ctx, tx, cursorKey); err != nil {
			return err
		}
	} else if err := sqliteWriteMetaValueContext(ctx, tx, cursorKey, sqliteBackfillCursorValue(sqliteChatSequenceProjectionVersion, lastID)); err != nil {
		return err
	}
	finalRevision, err := sqliteStateJSONRevision(ctx, tx)
	if err != nil {
		return err
	}
	if finalRevision != sourceRevision {
		return errSQLiteBackfillSourceChanged
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	return tx.Commit()
}

func loadSQLiteState(ctx context.Context, db *sql.DB) (State, error) {
	return loadSQLiteStateRows(ctx, db)
}

func loadSQLiteStateRows(ctx context.Context, db interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (State, error) {
	if sqliteStateLoadTestHook != nil {
		sqliteStateLoadTestHook()
	}
	state, err := loadSQLiteColdState(ctx, db)
	if err != nil {
		return State{}, err
	}
	if err := overlaySQLiteRuntimeState(ctx, db, &state); err != nil {
		return State{}, err
	}
	if err := loadSQLiteSessionMap(ctx, db, `SELECT id, teams_chat_id, status, updated_at, json FROM sessions`, state.Sessions); err != nil {
		return State{}, err
	}
	if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM inbound_events`, state.InboundEvents, func(v InboundEvent) string { return v.ID }); err != nil {
		return State{}, err
	}
	if err := loadSQLiteTurnMap(ctx, db, `SELECT id, session_id, status, json FROM turns`, state.Turns, true); err != nil {
		return State{}, err
	}
	if err := loadSQLiteOutboxMap(ctx, db, `SELECT `+sqliteOutboxProjectionSelect("o")+` FROM outbox_messages o WHERE `+sqliteOutboxProjectionValidSQL("o"), state.OutboxMessages, func(v OutboxMessage) string { return v.ID }); err != nil {
		return State{}, err
	}
	if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM message_provenance`, state.MessageProvenance, func(v MessageProvenanceRecord) string { return v.ID }); err != nil {
		return State{}, err
	}
	if err := loadSQLiteChatPollMap(ctx, db, `SELECT chat_id, json FROM chat_polls`, state.ChatPolls); err != nil {
		return State{}, err
	}
	if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM chat_rate_limits`, state.ChatRateLimits, func(v ChatRateLimitState) string { return v.ChatID }); err != nil {
		return State{}, err
	}
	if err := loadSQLiteCheckpointMapWithCanonicalSessions(ctx, db, `SELECT id, session_id, status, updated_at, json FROM import_checkpoints`, state.ImportCheckpoints, sqliteKnownSessionIDs(state.Sessions)); err != nil {
		return State{}, err
	}
	if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM transcript_ledger`, state.TranscriptLedger, func(v TranscriptLedgerRecord) string { return v.ID }); err != nil {
		return State{}, err
	}
	if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM transcript_deliveries`, state.TranscriptDeliveries, func(v TranscriptDeliveryRecord) string { return v.ID }); err != nil {
		return State{}, err
	}
	if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM helper_deliveries`, state.HelperDeliveries, func(v HelperDeliveryRecord) string { return v.ID }); err != nil {
		return State{}, err
	}
	if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM artifact_records`, state.ArtifactRecords, func(v ArtifactRecord) string { return v.ID }); err != nil {
		return State{}, err
	}
	if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM notifications`, state.Notifications, func(v NotificationRecord) string { return v.ID }); err != nil {
		return State{}, err
	}
	if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM fork_operations`, state.ForkOperations, func(v ForkOperation) string { return v.ID }); err != nil {
		return State{}, err
	}
	if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM fork_history_items`, state.ForkHistoryItems, func(v ForkHistoryItem) string { return v.ID }); err != nil {
		return State{}, err
	}
	normalizeLoadedState(&state)
	return state, nil
}

func loadSQLiteSelectedState(ctx context.Context, db *sql.DB, wanted map[string]struct{}) (State, error) {
	return loadSQLiteSelectedStateWithChatPollQuery(ctx, db, wanted, `SELECT chat_id, json FROM chat_polls`)
}

func loadSQLiteSelectedStateWithChatPollQuery(ctx context.Context, db *sql.DB, wanted map[string]struct{}, chatPollQuery string, chatPollArgs ...any) (State, error) {
	return loadSQLiteSelectedStateWithChatPollQueryMode(ctx, db, wanted, chatPollQuery, false, chatPollArgs...)
}

func loadSQLiteHotPollSelectedStateWithChatPollQuery(ctx context.Context, db *sql.DB, wanted map[string]struct{}, chatPollQuery string, chatPollArgs ...any) (State, error) {
	return loadSQLiteSelectedStateWithChatPollQueryMode(ctx, db, wanted, chatPollQuery, true, chatPollArgs...)
}

func loadSQLiteSelectedStateWithChatPollQueryMode(ctx context.Context, db *sql.DB, wanted map[string]struct{}, chatPollQuery string, hotBase bool, chatPollArgs ...any) (State, error) {
	// Chat sequences are needed by message publication, not by poll admission.
	// Loading the full sequence map here made every listener tick decode one row
	// per chat before it had selected a single due candidate.
	var state State
	var err error
	if hotBase {
		state, err = loadSQLiteHotPollBaseState(ctx, db)
		if err != nil {
			return State{}, err
		}
		if state.SchemaVersion == 0 {
			state, err = loadSQLiteColdStateWithoutChatSequences(ctx, db)
			if err != nil {
				return State{}, err
			}
			if err := overlaySQLiteRuntimeStateBestEffort(ctx, db, &state); err != nil {
				return State{}, err
			}
		}
	} else {
		runtimeOverlayLoaded := false
		if hasNonNativeSelectedFields(wanted) {
			// Runtime rows are only an authoritative replacement for the cold
			// document after the same fenced schema-preparation boundary.  A
			// legacy/partially prepared store may have some runtime rows while
			// its native materialization is still incomplete; retain the strict
			// cold path in that interval.
			schemaReady, schemaErr := sqliteSchemaPreparationReadyContext(ctx, db)
			if schemaErr != nil {
				return State{}, schemaErr
			}
			if schemaReady {
				runtimeState, seen, runtimeErr := loadSQLiteRuntimeState(ctx, db)
				if runtimeErr != nil {
					return State{}, runtimeErr
				}
				workflow, workflowFound := WorkflowNotificationConfig{}, false
				if _, wantsWorkflow := wanted["workflow"]; wantsWorkflow {
					workflow, workflowFound, runtimeErr = loadSQLiteWorkflowProjection(ctx, db)
					if runtimeErr != nil {
						return State{}, runtimeErr
					}
				}
				if sqliteSelectedFieldsCoveredByRuntime(wanted, seen) ||
					sqliteSelectedFieldsCoveredByRuntimeOrWorkflowProjection(wanted, seen, workflowFound) {
					state = State{SchemaVersion: SchemaVersion}
					overlaySQLiteRuntimeStateValues(&state, runtimeState, seen)
					if workflowFound {
						state.Workflow = workflow
					}
					state.ensure(time.Time{})
					runtimeOverlayLoaded = true
				}
			}
		}
		if !runtimeOverlayLoaded {
			state, err = loadSQLiteSelectedColdStateWithoutRowMaps(ctx, db, wanted)
			if err != nil {
				return State{}, err
			}
			if err := overlaySQLiteRuntimeState(ctx, db, &state); err != nil {
				return State{}, err
			}
		}
	}
	if _, ok := wanted["sessions"]; ok {
		if err := loadSQLiteSessionMap(ctx, db, `SELECT id, teams_chat_id, status, updated_at, json FROM sessions`, state.Sessions); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["inbound_events"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM inbound_events`, state.InboundEvents, func(v InboundEvent) string { return v.ID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["turns"]; ok {
		if err := loadSQLiteTurnMap(ctx, db, `SELECT id, session_id, status, json FROM turns`, state.Turns, true); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["outbox_messages"]; ok {
		if err := loadSQLiteOutboxMap(ctx, db, `SELECT `+sqliteOutboxProjectionSelect("o")+` FROM outbox_messages o WHERE `+sqliteOutboxProjectionValidSQL("o"), state.OutboxMessages, func(v OutboxMessage) string { return v.ID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["message_provenance"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM message_provenance`, state.MessageProvenance, func(v MessageProvenanceRecord) string { return v.ID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["chat_polls"]; ok {
		if strings.TrimSpace(chatPollQuery) == "" {
			chatPollQuery = `SELECT chat_id, json FROM chat_polls`
		}
		if err := loadSQLiteChatPollMapBestEffort(ctx, db, chatPollQuery, state.ChatPolls, chatPollArgs...); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["chat_rate_limits"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM chat_rate_limits`, state.ChatRateLimits, func(v ChatRateLimitState) string { return v.ChatID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["chat_sequences"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM chat_sequences`, state.ChatSequences, func(v ChatSequenceState) string { return v.ChatID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["import_checkpoints"]; ok {
		var canonicalSessionIDs map[string]struct{}
		if _, sessionsLoaded := wanted["sessions"]; sessionsLoaded {
			canonicalSessionIDs = sqliteKnownSessionIDs(state.Sessions)
		}
		if err := loadSQLiteCheckpointMapWithCanonicalSessions(ctx, db, `SELECT id, session_id, status, updated_at, json FROM import_checkpoints`, state.ImportCheckpoints, canonicalSessionIDs); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["transcript_ledger"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM transcript_ledger`, state.TranscriptLedger, func(v TranscriptLedgerRecord) string { return v.ID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["transcript_deliveries"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM transcript_deliveries`, state.TranscriptDeliveries, func(v TranscriptDeliveryRecord) string { return v.ID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["helper_deliveries"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM helper_deliveries`, state.HelperDeliveries, func(v HelperDeliveryRecord) string { return v.ID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["artifact_records"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM artifact_records`, state.ArtifactRecords, func(v ArtifactRecord) string { return v.ID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["notifications"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM notifications`, state.Notifications, func(v NotificationRecord) string { return v.ID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["fork_operations"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM fork_operations`, state.ForkOperations, func(v ForkOperation) string { return v.ID }); err != nil {
			return State{}, err
		}
	}
	if _, ok := wanted["fork_history_items"]; ok {
		if err := loadSQLiteJSONMap(ctx, db, `SELECT json FROM fork_history_items`, state.ForkHistoryItems, func(v ForkHistoryItem) string { return v.ID }); err != nil {
			return State{}, err
		}
	}
	normalizeLoadedState(&state)
	return state, nil
}

func hasNonNativeSelectedFields(wanted map[string]struct{}) bool {
	for field := range wanted {
		if !sqliteStateRowMapField(field) {
			return true
		}
	}
	return false
}

func sqliteRuntimeKeyForStateField(field string) string {
	switch field {
	case "scope":
		return sqliteRuntimeKeyScope
	case "machine_identity":
		return sqliteRuntimeKeyMachineIdentity
	case "machines":
		return sqliteRuntimeKeyMachines
	case "service_owner":
		return sqliteRuntimeKeyServiceOwner
	case "lock_owner":
		return sqliteRuntimeKeyLockOwner
	case "service_control":
		return sqliteRuntimeKeyServiceControl
	case "upgrade":
		return sqliteRuntimeKeyUpgrade
	case "auto_update":
		return sqliteRuntimeKeyAutoUpdate
	case "control_chat":
		return sqliteRuntimeKeyControlChat
	default:
		return ""
	}
}

func sqliteSelectedFieldsCoveredByRuntime(wanted map[string]struct{}, seen map[string]bool) bool {
	if !sqliteRuntimeStateUsable(seen) {
		return false
	}
	for field := range wanted {
		if sqliteStateRowMapField(field) {
			continue
		}
		key := sqliteRuntimeKeyForStateField(field)
		if key == "" || !seen[key] {
			return false
		}
	}
	return true
}

func sqliteSelectedFieldsCoveredByRuntimeOrWorkflowProjection(wanted map[string]struct{}, seen map[string]bool, workflowFound bool) bool {
	if !sqliteRuntimeStateUsable(seen) {
		return false
	}
	for field := range wanted {
		if sqliteStateRowMapField(field) {
			continue
		}
		if field == "workflow" {
			if !workflowFound {
				return false
			}
			continue
		}
		key := sqliteRuntimeKeyForStateField(field)
		if key == "" || !seen[key] {
			return false
		}
	}
	return true
}

// sqliteStateRowMapField is stored in a native table after SQLite migration.
// The state_json copy remains for compatibility and migration, but decoding
// these maps before immediately replacing them with the table projection is
// pure read amplification on every selected-state call.
func sqliteStateRowMapField(field string) bool {
	switch field {
	case "sessions", "inbound_events", "turns", "outbox_messages",
		"message_provenance", "chat_polls", "chat_rate_limits",
		"import_checkpoints", "transcript_ledger", "transcript_deliveries",
		"helper_deliveries", "artifact_records", "notifications",
		"fork_operations", "fork_history_items", "chat_sequences":
		return true
	default:
		return false
	}
}

// loadSQLiteSelectedColdStateWithoutRowMaps reads only the non-row-map fields
// from the compatibility state_json document. The JSON scanner still walks the
// document to find selected top-level values, but it does not unmarshal large
// sessions/inbound/turn/outbox maps that the caller will load from native
// SQLite tables immediately afterwards. A malformed or old state document
// deliberately falls back to the strict legacy cold loader; this keeps schema
// compatibility fail-closed instead of returning a partial state as valid.
func loadSQLiteSelectedColdStateWithoutRowMaps(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, wanted map[string]struct{}) (State, error) {
	return loadSQLiteSelectedColdStateWithoutRowMapsAttempt(ctx, q, wanted, 1)
}

func loadSQLiteSelectedColdStateWithoutRowMapsAttempt(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, wanted map[string]struct{}, retries int) (State, error) {
	jsonWanted := make(map[string]struct{}, len(wanted))
	workflowProjectionFound := false
	for field := range wanted {
		if !sqliteStateRowMapField(field) {
			jsonWanted[field] = struct{}{}
		}
	}
	if _, wantsWorkflow := wanted["workflow"]; wantsWorkflow {
		if _, found, err := loadSQLiteWorkflowProjection(ctx, q); err != nil {
			return State{}, err
		} else if found {
			// The caller may still need another non-native field (for example a
			// legacy runtime value), but workflow itself is now supplied by the
			// revision-fenced projection and must not force a cold JSON scan.
			workflowProjectionFound = true
			delete(jsonWanted, "workflow")
		}
	}
	// Every requested field is supplied by a trusted native SQLite table or a
	// separate projection.  Reading state_json here would only scan the large
	// compatibility document so the caller can immediately discard it before
	// hydrating those native rows.  More importantly, keeping that scan inside
	// Store.s.mu turns every selected durable read into an O(size-of-history)
	// critical section.  The native callers retain their own row/projection
	// trust and CAS checks; the cold document remains the fallback whenever even
	// one requested field still needs it.
	if len(jsonWanted) == 0 {
		if workflowProjectionFound {
			state := State{SchemaVersion: SchemaVersion}
			if projected, found, err := loadSQLiteWorkflowProjection(ctx, q); err != nil {
				return State{}, err
			} else if found {
				state.Workflow = projected
			}
			state.ensure(time.Time{})
			return state, nil
		}
		// A native-only selected read may skip the compatibility document only
		// after the fenced schema-preparation marker proves that this SQLite
		// pointer has crossed the current publication boundary.  Old or
		// partially prepared stores must retain the strict cold JSON validation;
		// otherwise a missing native row could be mistaken for an empty queue.
		ready, err := sqliteSchemaPreparationReadyContext(ctx, q)
		if err != nil {
			return State{}, err
		}
		if ready {
			state := State{SchemaVersion: SchemaVersion}
			state.ensure(time.Time{})
			return state, nil
		}
	}
	var raw []byte
	var stateJSONRevision int64
	if err := q.QueryRowContext(ctx, `
SELECT value,
       COALESCE((SELECT CAST(value AS INTEGER) FROM state_meta WHERE key = ?), 0)
FROM state_meta WHERE key = 'state_json'`, sqliteStateJSONRevisionKey).Scan(&raw, &stateJSONRevision); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return State{}, errors.New("sqlite teams store is missing state metadata")
		}
		return State{}, err
	}
	if len(raw) == 0 {
		return State{}, errors.New("sqlite teams store has empty state metadata")
	}
	state, ok, err := loadSelectedStateFieldsData(raw, jsonWanted)
	if err != nil {
		return State{}, err
	}
	if !ok {
		return loadSQLiteColdStateWithoutChatSequences(ctx, q)
	}
	state.ensure(time.Time{})
	if workflowProjectionFound {
		// This branch is reached only when another selected cold field still
		// requires JSON.  The projection will be overlaid by the caller's
		// runtime/projection path; do not let this compatibility decode replace
		// a valid projected workflow with an older cold value.
		if projected, found, err := loadSQLiteWorkflowProjection(ctx, q); err != nil {
			return State{}, err
		} else if found {
			state.Workflow = projected
		}
	}
	if _, wantsWorkflow := wanted["workflow"]; wantsWorkflow && !workflowProjectionFound && stateJSONRevision > 0 {
		if exec, ok := q.(interface {
			ExecContext(context.Context, string, ...any) (sql.Result, error)
		}); ok {
			rawProjection, err := json.Marshal(sqliteWorkflowProjection{
				Workflow:          state.Workflow,
				StateJSONRevision: stateJSONRevision,
			})
			if err != nil {
				return State{}, err
			}
			// Publish only if the exact state_json revision read above is still
			// current.  An older/mixed-version writer may change the canonical
			// document outside this Store lock; in that case this cache write is a
			// harmless no-op and the next read falls back again.
			result, err := exec.ExecContext(ctx, `
INSERT INTO state_meta(key, value) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET value = excluded.value
WHERE COALESCE((SELECT CAST(value AS INTEGER) FROM state_meta WHERE key = ?), 0) = ?`,
				sqliteWorkflowProjectionKey, rawProjection, sqliteStateJSONRevisionKey, stateJSONRevision)
			if err != nil {
				return State{}, err
			}
			rowsAffected, err := result.RowsAffected()
			if err != nil {
				return State{}, err
			}
			if rowsAffected == 0 {
				if retries > 0 {
					return loadSQLiteSelectedColdStateWithoutRowMapsAttempt(ctx, q, wanted, retries-1)
				}
				return State{}, fmt.Errorf("SQLite workflow projection changed during selected read")
			}
		}
	}
	if _, wantsHistory := wanted["history_watch"]; wantsHistory {
		if err := overlaySQLiteHistoryWatchProjection(ctx, q, &state); err != nil {
			return State{}, err
		}
	}
	return state, nil
}

// loadSQLiteSelectedSessionsForIDs hydrates only the session rows that were
// already admitted by the hot candidate query.  The base hot snapshot
// intentionally omits the full session map; reloading every session just to
// refresh a handful of control-selected chats would recreate the O(number of
// sessions) JSON cost this API is designed to avoid.
func loadSQLiteSelectedSessionsForIDs(ctx context.Context, db *sql.DB, state State, ids []string) (map[string]struct{}, error) {
	ids = sqliteCleanSelectionIDs(ids)
	loaded := make(map[string]struct{}, len(ids))
	if len(ids) == 0 {
		return loaded, nil
	}
	clause, args := sqliteSelectionInClause("id", ids)
	rows, err := db.QueryContext(ctx, `SELECT id, teams_chat_id, status, updated_at, json FROM sessions WHERE `+clause, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var sqlID string
		var chatID, status sql.NullString
		var ignoredUpdatedAt any
		var raw []byte
		if err := rows.Scan(&sqlID, &chatID, &status, &ignoredUpdatedAt, &raw); err != nil {
			return nil, err
		}
		var session SessionContext
		if strings.TrimSpace(sqlID) == "" || !jsonValueHasNoDuplicateKeys(raw) || json.Unmarshal(raw, &session) != nil ||
			strings.TrimSpace(session.ID) != strings.TrimSpace(sqlID) {
			continue
		}
		if chatID.Valid && strings.TrimSpace(chatID.String) != "" &&
			strings.TrimSpace(session.TeamsChatID) != "" &&
			strings.TrimSpace(session.TeamsChatID) != strings.TrimSpace(chatID.String) {
			continue
		}
		annotateUnknownLoadedSession(&session)
		state.Sessions[session.ID] = session
		loaded[session.ID] = struct{}{}
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return loaded, nil
}

// loadSQLiteSelectedSessionsForChats supplies the session identity needed to
// reconcile shared-chat turns/checkpoints. The final selected refresh already
// has a bounded chat set; loading all session rows for those chats is what lets
// the bridge remove a stale active turn belonging to a second session after
// that turn becomes terminal. A malformed row is represented by a closed,
// non-runnable placeholder using only its SQL identity. It is never promoted
// to an executable session, but it remains enough evidence for the merge fence.
func loadSQLiteSelectedSessionsForChats(ctx context.Context, db *sql.DB, state State, chatIDs []string) error {
	return loadSQLiteSelectedSessionsForChatsExcluding(ctx, db, state, chatIDs, nil)
}

func loadSQLiteSelectedSessionsForChatsExcluding(ctx context.Context, db *sql.DB, state State, chatIDs []string, excludedIDs map[string]struct{}) error {
	chatIDs = sqliteCleanSelectionIDs(chatIDs)
	if len(chatIDs) == 0 {
		return nil
	}
	chatSet := make(map[string]struct{}, len(chatIDs))
	for _, chatID := range chatIDs {
		chatSet[chatID] = struct{}{}
	}
	excluded := make(map[string]struct{}, len(excludedIDs))
	if len(excludedIDs) != 0 {
		for id := range excludedIDs {
			if id = strings.TrimSpace(id); id != "" {
				excluded[id] = struct{}{}
			}
		}
	}
	trustedLoadedIDs := make(map[string]struct{})
	appendSession := func(sqlID string, scalarChatID sql.NullString, raw []byte, canonicalOnly bool) (trustedViolation bool) {
		sqlID = strings.TrimSpace(sqlID)
		if sqlID == "" {
			return false
		}
		if _, skip := excluded[sqlID]; skip {
			return false
		}
		var session SessionContext
		if jsonValueHasNoDuplicateKeys(raw) && json.Unmarshal(raw, &session) == nil &&
			strings.TrimSpace(session.ID) == sqlID && strings.TrimSpace(session.TeamsChatID) != "" {
			if _, selected := chatSet[strings.TrimSpace(session.TeamsChatID)]; !selected {
				// A trusted scalar row whose canonical chat disagrees is a
				// projection violation. Do not install either value; ask the
				// caller to rerun the exact canonical oracle for this selection.
				return !canonicalOnly
			}
			annotateUnknownLoadedSession(&session)
			state.Sessions[sqlID] = session
			if !canonicalOnly {
				trustedLoadedIDs[sqlID] = struct{}{}
			}
			return false
		}
		if canonicalOnly {
			// The row matched because its canonical chat projection (or, for
			// malformed JSON, the compatibility scalar) was selected. Keep
			// only a non-runnable witness so stale shared-chat turns can still
			// be removed without inventing Codex metadata.
			chatID := strings.TrimSpace(nullableStringValue(scalarChatID))
			if _, selected := chatSet[chatID]; !selected {
				return false
			}
			state.Sessions[sqlID] = SessionContext{
				ID: sqlID, Status: SessionStatusClosed, TeamsChatID: chatID,
			}
			return false
		}
		return true
	}

	// Current writers publish the session identity projection and its
	// row-local generation atomically. Use the chat index for the common case,
	// then decode each selected row once as the final identity check. This is
	// only a candidate lane: a contradictory trusted row never authorizes a
	// result and forces the exact canonical query below.
	trustedChat, trustedArgs := sqliteSelectionInClause("s.teams_chat_id", chatIDs)
	trustedWhere := sqliteProjectionTrustedSQL("s") + ` AND ` + trustedChat
	if len(excluded) != 0 {
		ids := make([]string, 0, len(excluded))
		for id := range excluded {
			ids = append(ids, id)
		}
		ids = sqliteCleanSelectionIDs(ids)
		if len(ids) != 0 {
			excludeClause, excludeArgs := sqliteSelectionInClause("s.id", ids)
			trustedWhere += ` AND NOT (` + excludeClause + `)`
			trustedArgs = append(trustedArgs, excludeArgs...)
		}
	}
	rows, err := db.QueryContext(ctx, `SELECT s.id, s.teams_chat_id, s.status, s.updated_at, s.json
FROM sessions s WHERE `+trustedWhere, trustedArgs...)
	if err != nil {
		return err
	}
	trustedViolation := false
	for rows.Next() {
		var sqlID string
		var scalarChatID, scalarStatus sql.NullString
		var ignoredUpdatedAt any
		var raw []byte
		if err := rows.Scan(&sqlID, &scalarChatID, &scalarStatus, &ignoredUpdatedAt, &raw); err != nil {
			_ = rows.Close()
			return err
		}
		if appendSession(sqlID, scalarChatID, raw, false) {
			trustedViolation = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}
	if trustedViolation {
		// This is a defensive path for an old/manual writer that left the trust
		// bit live while changing the canonical chat. Re-run the old complete
		// oracle so no partial scalar result can escape.
		for id := range trustedLoadedIDs {
			delete(state.Sessions, id)
		}
		canonicalChat := sqliteCanonicalTextProjectionSQL("s.json", "$.teams_chat_id", "s.teams_chat_id")
		clause, args := sqliteSelectionInClause(canonicalChat, chatIDs)
		if len(excluded) != 0 {
			ids := make([]string, 0, len(excluded))
			for id := range excluded {
				ids = append(ids, id)
			}
			ids = sqliteCleanSelectionIDs(ids)
			if len(ids) != 0 {
				excludeClause, excludeArgs := sqliteSelectionInClause("s.id", ids)
				clause += ` AND NOT (` + excludeClause + `)`
				args = append(args, excludeArgs...)
			}
		}
		rows, err := db.QueryContext(ctx, `SELECT s.id, s.teams_chat_id, s.status, s.updated_at, s.json
FROM sessions s WHERE `+clause, args...)
		if err != nil {
			return err
		}
		for rows.Next() {
			var sqlID string
			var scalarChatID, scalarStatus sql.NullString
			var ignoredUpdatedAt any
			var raw []byte
			if err := rows.Scan(&sqlID, &scalarChatID, &scalarStatus, &ignoredUpdatedAt, &raw); err != nil {
				_ = rows.Close()
				return err
			}
			appendSession(sqlID, scalarChatID, raw, true)
		}
		if err := rows.Err(); err != nil {
			_ = rows.Close()
			return err
		}
		return rows.Close()
	}

	// The residual lane is the only path that evaluates the canonical chat
	// expression across the table. Its partial index excludes healthy rows, so
	// a normal selected refresh is proportional to legacy/stale projections,
	// not to the total number of sessions.
	canonicalChat := sqliteCanonicalTextProjectionSQL("s.json", "$.teams_chat_id", "s.teams_chat_id")
	clause, args := sqliteSelectionInClause(canonicalChat, chatIDs)
	clause = `(` + sqliteProjectionUntrustedSQL("s") + `) AND ` + clause
	if len(excluded) != 0 {
		ids := make([]string, 0, len(excluded))
		for id := range excluded {
			ids = append(ids, id)
		}
		ids = sqliteCleanSelectionIDs(ids)
		if len(ids) != 0 {
			excludeClause, excludeArgs := sqliteSelectionInClause("s.id", ids)
			clause += ` AND NOT (` + excludeClause + `)`
			args = append(args, excludeArgs...)
		}
	}
	rows, err = db.QueryContext(ctx, `SELECT s.id, s.teams_chat_id, s.status, s.updated_at, s.json
FROM sessions s WHERE `+clause, args...)
	if err != nil {
		return err
	}
	for rows.Next() {
		var sqlID string
		var scalarChatID, scalarStatus sql.NullString
		var ignoredUpdatedAt any
		var raw []byte
		if err := rows.Scan(&sqlID, &scalarChatID, &scalarStatus, &ignoredUpdatedAt, &raw); err != nil {
			_ = rows.Close()
			return err
		}
		appendSession(sqlID, scalarChatID, raw, true)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	return rows.Close()
}

// loadSQLiteHotPollBaseState reads only the small runtime projection needed to
// construct a bounded poll-admission snapshot. New stores persist ControlChat
// there as well as in state_json, so a large/corrupt cold document cannot put
// the listener back on an O(size-of-history) decode path. Once a runtime
// projection has any rows, an incomplete projection is deliberately treated as
// authoritative-but-partial: falling back to state_json at that point could
// resurrect a stale owner/control binding. A completely empty runtime table is
// the only compatibility case that returns a zero SchemaVersion for older
// SQLite stores that predate this projection.
func loadSQLiteHotPollBaseState(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (State, error) {
	runtimeState, seen, err := loadSQLiteRuntimeStateBestEffort(ctx, q)
	if err != nil {
		return State{}, err
	}
	materialized, err := sqliteRuntimeProjectionMaterialized(ctx, q)
	if err != nil {
		return State{}, err
	}
	projectionStarted := len(seen) > 0
	if !projectionStarted {
		projectionStarted = materialized
	}
	if !projectionStarted {
		rows, queryErr := q.QueryContext(ctx, `SELECT 1 FROM runtime_state LIMIT 1`)
		if queryErr != nil {
			return State{}, queryErr
		}
		projectionStarted = rows.Next()
		if rowsErr := rows.Err(); rowsErr != nil {
			_ = rows.Close()
			return State{}, rowsErr
		}
		if closeErr := rows.Close(); closeErr != nil {
			return State{}, closeErr
		}
	}
	if !projectionStarted {
		return State{}, nil
	}
	state := State{
		SchemaVersion: runtimeState.SchemaVersion,
	}
	if seen[sqliteRuntimeKeyControlChat] {
		state.ControlChat = runtimeState.ControlChat
	}
	if seen[sqliteRuntimeKeyServiceOwner] {
		state.ServiceOwner = runtimeState.ServiceOwner
	}
	state.ensure(time.Time{})
	return state, nil
}

func hotPollSelectedChatIDs(state State) []string {
	seen := make(map[string]struct{}, len(state.ChatPolls)+1)
	for chatID := range state.ChatPolls {
		chatID = strings.TrimSpace(chatID)
		if chatID != "" {
			seen[chatID] = struct{}{}
		}
	}
	if chatID := strings.TrimSpace(state.ControlChat.TeamsChatID); chatID != "" {
		seen[chatID] = struct{}{}
	}
	ids := make([]string, 0, len(seen))
	for chatID := range seen {
		ids = append(ids, chatID)
	}
	sort.Strings(ids)
	return ids
}

func sqliteCleanSelectionIDs(ids []string) []string {
	cleaned := make([]string, 0, len(ids))
	seen := make(map[string]struct{}, len(ids))
	for _, id := range ids {
		id = strings.TrimSpace(id)
		if id == "" {
			continue
		}
		if _, ok := seen[id]; ok {
			continue
		}
		seen[id] = struct{}{}
		cleaned = append(cleaned, id)
	}
	sort.Strings(cleaned)
	return cleaned
}

func sqliteSelectionInClause(column string, ids []string) (string, []any) {
	if len(ids) == 0 {
		return "0", nil
	}
	placeholders := strings.TrimRight(strings.Repeat("?,", len(ids)), ",")
	args := make([]any, len(ids))
	for i, id := range ids {
		args[i] = id
	}
	return column + " IN (" + placeholders + ")", args
}

// loadSQLiteSelectedSessionIDsForChats resolves the bounded chat selection to
// session IDs without hydrating every session JSON object. Trusted scalar
// bindings use the session chat index; only untrusted rows enter the
// canonical-identity residual lane. The returned IDs are subsequently used by
// the indexed turn/checkpoint loaders, so a selected refresh does not scan all
// active turns or import checkpoints merely to find rows for a few chats.
func loadSQLiteSelectedSessionIDsForChats(ctx context.Context, db *sql.DB, chatIDs, sessionIDs []string) ([]string, error) {
	chatIDs = sqliteCleanSelectionIDs(chatIDs)
	selected := make(map[string]struct{}, len(sessionIDs))
	for _, sessionID := range sessionIDs {
		sessionID = strings.TrimSpace(sessionID)
		if sessionID != "" {
			selected[sessionID] = struct{}{}
		}
	}
	if len(chatIDs) == 0 {
		ids := make([]string, 0, len(selected))
		for id := range selected {
			ids = append(ids, id)
		}
		return sqliteCleanSelectionIDs(ids), nil
	}
	scalarChatClause, scalarChatArgs := sqliteSelectionInClause("s.teams_chat_id", chatIDs)
	canonicalChat := sqliteCanonicalTextProjectionSQL("s.json", "$.teams_chat_id", "s.teams_chat_id")
	canonicalChatClause, canonicalChatArgs := sqliteSelectionInClause(canonicalChat, chatIDs)
	where := `((` + sqliteProjectionTrustedSQL("s") + `) AND (` + scalarChatClause + `)) OR
  ((` + sqliteProjectionUntrustedSQL("s") + `) AND (` + canonicalChatClause + `))`
	args := append([]any{}, scalarChatArgs...)
	args = append(args, canonicalChatArgs...)
	chatSet := make(map[string]struct{}, len(chatIDs))
	for _, chatID := range chatIDs {
		chatSet[chatID] = struct{}{}
	}
	rows, err := db.QueryContext(ctx, `SELECT s.id, s.teams_chat_id, s.projection_trusted, s.json
FROM sessions s WHERE `+where, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		var scalarChatID sql.NullString
		var projectionTrusted sql.NullInt64
		var raw []byte
		if err := rows.Scan(&id, &scalarChatID, &projectionTrusted, &raw); err != nil {
			return nil, err
		}
		id = strings.TrimSpace(id)
		if id == "" {
			continue
		}
		if !jsonValueHasNoDuplicateKeys(raw) {
			continue
		}
		if canonicalChatID, ok := sqliteSessionCanonicalChatID(raw); ok {
			if _, matched := chatSet[canonicalChatID]; matched {
				selected[id] = struct{}{}
			}
			continue
		}
		// A trusted row is already covered by its projection contract. An
		// untrusted row without a canonical identity is not safe to route.
		if nullableInt64Value(projectionTrusted) == 1 {
			if _, matched := chatSet[strings.TrimSpace(scalarChatID.String)]; matched {
				selected[id] = struct{}{}
			}
		}
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	ids := make([]string, 0, len(selected))
	for id := range selected {
		ids = append(ids, id)
	}
	return sqliteCleanSelectionIDs(ids), nil
}

// loadSQLiteHotPollActiveTurns and loadSQLiteHotPollImportingCheckpoints keep
// the hot schedule's auxiliary rows aligned with the bounded poll admission.
// Loading all queued/running turns or importing checkpoints defeats the point
// of limiting chat_polls because those maps are decoded before the scheduler
// has selected a work quantum.
func loadSQLiteHotPollActiveTurns(ctx context.Context, db *sql.DB, state State, readyOnly bool) error {
	canonicalStatus := sqliteTurnSafetyStatusSQL("json", "status")
	if !readyOnly {
		args := sqliteTurnActiveStatusArgs()
		return loadSQLiteTurnMap(ctx, db, `SELECT id, session_id, `+canonicalStatus+`, json FROM turns WHERE `+sqliteTurnActiveStatusSQL(canonicalStatus), state.Turns, true, args...)
	}
	chatIDs := hotPollSelectedChatIDs(state)
	if len(chatIDs) == 0 {
		return nil
	}
	placeholders := strings.TrimRight(strings.Repeat("?,", len(chatIDs)), ",")
	args := make([]any, 0, len(chatIDs)+5)
	args = append(args, sqliteTurnActiveStatusArgs()...)
	for _, chatID := range chatIDs {
		args = append(args, chatID)
	}
	canonicalSessionChat := sqliteCanonicalTextProjectionSQL("s.json", "$.teams_chat_id", "s.teams_chat_id")
	return loadSQLiteTurnMap(ctx, db,
		`SELECT t.id, t.session_id, `+sqliteTurnSafetyStatusSQL("t.json", "t.status")+`, t.json
	FROM turns t
	JOIN sessions s ON s.id = t.session_id
	WHERE `+sqliteTurnActiveSafetyStatusSQL("t.json", "t.status")+`
	  AND `+canonicalSessionChat+` IN (`+placeholders+`)`,
		state.Turns, true, args...)
}

func loadSQLiteHotPollActiveTurnsForIDs(ctx context.Context, db *sql.DB, state State, chatIDs, sessionIDs []string) error {
	selectedSessionIDs := sqliteSelectedSessionIDsForChats(state, chatIDs, sessionIDs)
	if len(selectedSessionIDs) == 0 {
		return nil
	}

	// The selected session refresh has already established the complete set of
	// session identities for the admitted chats. Current writers publish the
	// turn identity/status projection with a matching row-local generation, so
	// use the (session_id, status) index for the common case and decode only the
	// selected rows. The JSON payload remains the final identity check.
	sessionClause, sessionArgs := sqliteSelectionInClause("t.session_id", selectedSessionIDs)
	trustedArgs := []any{string(TurnStatusQueued), string(TurnStatusRunning)}
	trustedArgs = append(trustedArgs, sessionArgs...)
	trustedWhere := sqliteProjectionTrustedSQL("t") + ` AND t.status IN (?, ?) AND ` + sessionClause
	rows, err := db.QueryContext(ctx, `SELECT t.id, t.session_id, t.status, t.json
FROM turns t WHERE `+trustedWhere, trustedArgs...)
	if err != nil {
		return err
	}
	loadedTrusted := make(map[string]Turn)
	trustedViolation := false
	for rows.Next() {
		var sqlID, sqlSessionID, sqlStatus string
		var raw []byte
		if err := rows.Scan(&sqlID, &sqlSessionID, &sqlStatus, &raw); err != nil {
			_ = rows.Close()
			return err
		}
		var turn Turn
		if err := json.Unmarshal(raw, &turn); err != nil ||
			strings.TrimSpace(turn.ID) != strings.TrimSpace(sqlID) ||
			strings.TrimSpace(turn.SessionID) != strings.TrimSpace(sqlSessionID) ||
			strings.TrimSpace(string(turn.Status)) != strings.TrimSpace(sqlStatus) {
			trustedViolation = true
			continue
		}
		normalizeLoadedTurnStatusWithIndexedFallback(&turn, TurnStatus(sqlStatus))
		loadedTrusted[turn.ID] = turn
		state.Turns[turn.ID] = turn
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}
	if trustedViolation {
		// A legacy/manual writer may have left a trust bit live while changing
		// the payload. Remove only rows installed by this candidate lane, then
		// use the old canonical query for the whole selected set. No partial
		// scalar result is allowed to escape this recovery branch.
		for id := range loadedTrusted {
			delete(state.Turns, id)
		}
		return loadSQLiteHotPollActiveTurnsForIDsCanonical(ctx, db, state, chatIDs, sessionIDs)
	}

	// Untrusted/stale rows are a residual compatibility lane. It still uses
	// canonical JSON for the session/status filter, but the partial generation
	// index prevents healthy rows from being scanned again on every selected
	// refresh. A malformed active row remains a safety witness through the
	// existing loadSQLiteTurnMap behavior.
	canonicalStatus := sqliteTurnSafetyStatusSQL("t.json", "t.status")
	canonicalSessionID := sqliteCanonicalTextProjectionSQL("t.json", "$.session_id", "t.session_id")
	residualCanonicalSessionClause, residualCanonicalSessionArgs := sqliteSelectionInClause(canonicalSessionID, selectedSessionIDs)
	residualScalarSessionClause, residualScalarSessionArgs := sqliteSelectionInClause("t.session_id", selectedSessionIDs)
	residualWhere := `(` + sqliteProjectionUntrustedSQL("t") + `) AND ` +
		sqliteTurnActiveSafetyStatusSQL("t.json", "t.status") + ` AND (` + residualCanonicalSessionClause + ` OR ` + residualScalarSessionClause + `)`
	residualArgs := append(sqliteTurnActiveStatusArgs(), residualCanonicalSessionArgs...)
	residualArgs = append(residualArgs, residualScalarSessionArgs...)
	return loadSQLiteTurnMap(ctx, db,
		`SELECT t.id, t.session_id, `+canonicalStatus+`, t.json
FROM turns t WHERE `+residualWhere,
		state.Turns, true, residualArgs...)
}

func sqliteSelectedSessionIDsForChats(state State, chatIDs, sessionIDs []string) []string {
	chatIDs = sqliteCleanSelectionIDs(chatIDs)
	chatSet := make(map[string]struct{}, len(chatIDs))
	for _, chatID := range chatIDs {
		chatSet[chatID] = struct{}{}
	}
	seen := make(map[string]struct{}, len(sessionIDs)+len(state.Sessions))
	for _, sessionID := range sessionIDs {
		if sessionID = strings.TrimSpace(sessionID); sessionID != "" {
			seen[sessionID] = struct{}{}
		}
	}
	for sessionID, session := range state.Sessions {
		if _, selected := chatSet[strings.TrimSpace(session.TeamsChatID)]; !selected {
			continue
		}
		if sessionID = strings.TrimSpace(sessionID); sessionID != "" {
			seen[sessionID] = struct{}{}
		}
	}
	ids := make([]string, 0, len(seen))
	for sessionID := range seen {
		ids = append(ids, sessionID)
	}
	return sqliteCleanSelectionIDs(ids)
}

func loadSQLiteHotPollActiveTurnsForIDsCanonical(ctx context.Context, db *sql.DB, state State, chatIDs, sessionIDs []string) error {
	if len(chatIDs) == 0 && len(sessionIDs) == 0 {
		return nil
	}
	canonicalStatus := sqliteTurnSafetyStatusSQL("t.json", "t.status")
	active := sqliteTurnActiveSafetyStatusSQL("t.json", "t.status")
	canonicalSessionChat := sqliteCanonicalTextProjectionSQL("s.json", "$.teams_chat_id", "s.teams_chat_id")
	sessionClause, sessionArgs := sqliteSelectionInClause("t.session_id", sessionIDs)
	chatClause, chatArgs := sqliteSelectionInClause(canonicalSessionChat, chatIDs)
	args := append(sqliteTurnActiveStatusArgs(), sessionArgs...)
	args = append(args, chatArgs...)
	return loadSQLiteTurnMap(ctx, db,
		`SELECT t.id, t.session_id, `+canonicalStatus+`, t.json
FROM turns t
LEFT JOIN sessions s ON s.id = t.session_id
WHERE `+active+` AND (`+sessionClause+` OR `+chatClause+`)`,
		state.Turns, true, args...)
}

func loadSQLiteHotPollImportingCheckpoints(ctx context.Context, db *sql.DB, state State, readyOnly bool) error {
	checkpointStatus := sqliteCanonicalTextProjectionSQL("json", "$.status", "status")
	checkpointSessionID := sqliteCanonicalTextProjectionSQL("json", "$.session_id", "session_id")
	if !readyOnly {
		return loadSQLiteCheckpointMap(ctx, db, `SELECT id, `+checkpointSessionID+`, `+checkpointStatus+`, updated_at, json FROM import_checkpoints WHERE `+checkpointStatus+` = ?`, state.ImportCheckpoints, sqliteImportCheckpointImporting)
	}
	chatIDs := hotPollSelectedChatIDs(state)
	if len(chatIDs) == 0 {
		return nil
	}
	placeholders := strings.TrimRight(strings.Repeat("?,", len(chatIDs)), ",")
	args := make([]any, 0, len(chatIDs)+1)
	args = append(args, sqliteImportCheckpointImporting)
	for _, chatID := range chatIDs {
		args = append(args, chatID)
	}
	checkpointStatus = sqliteCanonicalTextProjectionSQL("i.json", "$.status", "i.status")
	checkpointSessionID = sqliteCanonicalTextProjectionSQL("i.json", "$.session_id", "i.session_id")
	canonicalSessionChat := sqliteCanonicalTextProjectionSQL("s.json", "$.teams_chat_id", "s.teams_chat_id")
	return loadSQLiteCheckpointMap(ctx, db,
		`SELECT i.id, `+checkpointSessionID+`, `+checkpointStatus+`, i.updated_at, i.json
FROM import_checkpoints i
JOIN sessions s ON s.id = `+checkpointSessionID+`
WHERE `+checkpointStatus+` = ?
  AND `+canonicalSessionChat+` IN (`+placeholders+`)`,
		state.ImportCheckpoints, args...)
}

func loadSQLiteHotPollImportingCheckpointsForIDs(ctx context.Context, db *sql.DB, state State, chatIDs, sessionIDs []string) error {
	selectedSessionIDs := sqliteSelectedSessionIDsForChats(state, chatIDs, sessionIDs)
	if len(selectedSessionIDs) == 0 {
		return nil
	}
	// The selected session set is already established by the bounded session
	// hydration. Use the durable scalar identity index for the common case and
	// include the deterministic canonical transcript key as a second indexed
	// route. The latter preserves the old behavior when a canonical checkpoint's
	// SQL session_id projection is stale, without reopening a table-wide JSON
	// session/chat join. Status is filtered after the canonical row decoder: a
	// stale scalar status must not hide a JSON row that is still importing, while
	// a malformed row with scalar importing status remains an opaque fence.
	sessionClause, sessionArgs := sqliteSelectionInClause("i.session_id", selectedSessionIDs)
	canonicalIDs := make([]string, 0, len(selectedSessionIDs))
	canonicalSessionIDs := make(map[string]struct{}, len(selectedSessionIDs))
	for _, sessionID := range selectedSessionIDs {
		canonicalIDs = append(canonicalIDs, transcriptCheckpointIDForSession(sessionID))
		canonicalSessionIDs[sessionID] = struct{}{}
	}
	idClause, idArgs := sqliteSelectionInClause("i.id", canonicalIDs)
	args := append([]any{}, sessionArgs...)
	args = append(args, idArgs...)
	loaded := make(map[string]ImportCheckpoint)
	if err := loadSQLiteCheckpointMapWithCanonicalSessions(ctx, db,
		`SELECT i.id, i.session_id, i.status, i.updated_at, i.json
FROM import_checkpoints i
WHERE (`+sessionClause+` OR `+idClause+`)`, loaded, canonicalSessionIDs, args...); err != nil {
		return err
	}
	for id, checkpoint := range loaded {
		if checkpoint.Status == importCheckpointStatusImporting {
			state.ImportCheckpoints[id] = checkpoint
		}
	}
	return nil
}

func loadSQLiteParkedNoticeChatIDs(ctx context.Context, db *sql.DB) (map[string]bool, error) {
	parkedSkipEligible := sqliteCanonicalParkedSkipProjectionSQL("json", "parked_skip_eligible", "poll_state")
	rows, err := db.QueryContext(ctx, `SELECT chat_id FROM chat_polls WHERE `+parkedSkipEligible+` != 0`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]bool{}
	for rows.Next() {
		var chatID string
		if err := rows.Scan(&chatID); err != nil {
			return nil, err
		}
		chatID = strings.TrimSpace(chatID)
		if chatID != "" {
			out[chatID] = true
		}
	}
	return out, rows.Err()
}

func loadSQLiteHasSessions(ctx context.Context, db *sql.DB) (bool, error) {
	var one int
	if err := db.QueryRowContext(ctx, `SELECT 1 FROM sessions LIMIT 1`).Scan(&one); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return false, nil
		}
		return false, err
	}
	return true, nil
}

func loadSQLiteHasValidSessions(ctx context.Context, db *sql.DB) (bool, error) {
	var one int
	validSession := sqliteSessionCanonicalValidJSONSQL("json", "id")
	if err := db.QueryRowContext(ctx, `SELECT 1 FROM sessions WHERE `+validSession+` LIMIT 1`).Scan(&one); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return false, nil
		}
		return false, err
	}
	return true, nil
}

// loadSQLiteHotPollCorruptWorkSessions is a deliberately cold, bounded
// diagnostic lane. It is called only when the normal scalar admission found
// no runnable candidate while some projection is already untrusted. The
// scalar chat binding and schedule deadline locate the row without trusting
// any session JSON field; the returned evidence is later converted into a
// chat-local recovery disposition with a poll-revision CAS.
func sqliteHotPollCorruptWorkSessionsQueryWithCursor(cursor bool) string {
	validSession := sqliteSessionValidJSONSQL("s.json", "s.id", "s.teams_chat_id")
	// A trusted session projection is already covered by the marker/revision
	// contract and its write triggers. Restrict this cold JSON validator to the
	// indexed residual lane; otherwise one untrusted poll row would make every
	// healthy session pay the duplicate-key/type validation cost.
	untrustedSession := sqliteProjectionUntrustedSQL("s")
	// Do not use any session/poll scalar as a WHERE filter here. This is the
	// recovery witness for precisely the rows whose projection is untrusted;
	// stale status/chat/deadline/pending-page values are not evidence that a
	// malformed canonical session is inactive. The caller decodes the bounded
	// session rows and performs the control-chat check from the best available
	// canonical identity, then looks up the matching poll by that identity.
	cursorPredicate := ""
	if cursor {
		cursorPredicate = "\n  AND s.id > ?"
	}
	return `SELECT s.id, trim(COALESCE(s.teams_chat_id, '')), s.json
FROM sessions s
WHERE trim(s.id) != ''
  AND (` + untrustedSession + `)
  AND NOT (` + validSession + `)` + cursorPredicate + `
ORDER BY s.id
LIMIT ?`
}

func sqliteHotPollCorruptWorkSessionsQuery() string {
	return sqliteHotPollCorruptWorkSessionsQueryWithCursor(false)
}

func sqliteHotPollCorruptWorkSessionsCursorQuery() string {
	return sqliteHotPollCorruptWorkSessionsQueryWithCursor(true)
}

func loadSQLiteHotPollCorruptWorkSessions(ctx context.Context, db *sql.DB, controlChatID string, now time.Time, limit int) ([]HotPollCorruptSession, error) {
	if limit <= 0 {
		return nil, nil
	}
	if ctx == nil {
		ctx = context.Background()
	}
	parentCtx := ctx
	operationCtx, cancel := context.WithTimeout(ctx, sqliteHotPollLegacyMaxDuration)
	defer cancel()
	if now.IsZero() {
		now = time.Now()
	}
	_ = now
	controlChatID = strings.TrimSpace(controlChatID)
	type corruptSessionRow struct {
		sessionID string
		chatID    string
		raw       []byte
	}
	out := make([]HotPollCorruptSession, 0, limit)
	afterID := ""
	scannedRows := int64(0)
	scannedJSONBytes := int64(0)
	chargeJSON := func(raw []byte) error {
		rowBytes := int64(len(raw))
		if rowBytes > sqliteHotPollLegacyMaxJSONRowBytes {
			return fmt.Errorf("%w: corrupt-session probe encountered %d-byte JSON row", errSQLiteHotPollAdmissionIndeterminate, rowBytes)
		}
		if rowBytes > sqliteHotPollLegacyMaxJSONBytes-scannedJSONBytes {
			return fmt.Errorf("%w: corrupt-session probe exceeded %d JSON bytes", errSQLiteHotPollAdmissionIndeterminate, sqliteHotPollLegacyMaxJSONBytes)
		}
		scannedJSONBytes += rowBytes
		return nil
	}
	for len(out) < limit {
		if err := operationCtx.Err(); err != nil {
			if parentCtx.Err() != nil {
				return nil, parentCtx.Err()
			}
			return nil, fmt.Errorf("%w: corrupt-session probe exceeded %s after %d rows: %v", errSQLiteHotPollAdmissionIndeterminate, sqliteHotPollLegacyMaxDuration, scannedRows, err)
		}
		remaining := int64(sqliteHotPollCorruptSessionProbeMaxRows) - scannedRows
		if remaining <= 0 {
			return nil, fmt.Errorf("%w: corrupt-session probe exceeded %d rows", errSQLiteHotPollAdmissionIndeterminate, sqliteHotPollCorruptSessionProbeMaxRows)
		}
		pageSize := int64(sqliteHotPollCorruptSessionProbePageSize)
		if remaining+1 < pageSize {
			pageSize = remaining + 1
		}
		rows, err := db.QueryContext(operationCtx, sqliteHotPollCorruptWorkSessionsCursorQuery(), afterID, pageSize)
		if err != nil {
			return nil, err
		}
		page := make([]corruptSessionRow, 0, pageSize)
		for rows.Next() {
			var row corruptSessionRow
			if err := rows.Scan(&row.sessionID, &row.chatID, &row.raw); err != nil {
				_ = rows.Close()
				return nil, err
			}
			row.raw = append([]byte(nil), row.raw...)
			page = append(page, row)
		}
		rowsErr := rows.Err()
		closeErr := rows.Close()
		if rowsErr != nil {
			return nil, rowsErr
		}
		if closeErr != nil {
			return nil, closeErr
		}
		if len(page) == 0 {
			break
		}
		if int64(len(page)) > remaining {
			return nil, fmt.Errorf("%w: corrupt-session probe exceeded %d rows", errSQLiteHotPollAdmissionIndeterminate, sqliteHotPollCorruptSessionProbeMaxRows)
		}
		scannedRows += int64(len(page))
		for _, row := range page {
			afterID = strings.TrimSpace(row.sessionID)
			sessionID, scalarChatID, sessionRaw := row.sessionID, strings.TrimSpace(row.chatID), row.raw
			if err := chargeJSON(sessionRaw); err != nil {
				return nil, err
			}
			if err := sqliteHotPollChargeCanonicalFallbackBudget(ctx, 1, int64(len(sessionRaw))); err != nil {
				return nil, err
			}
			canonicalChatID, canonicalChatOK := sqliteSessionCanonicalChatID(sessionRaw)
			chatID := scalarChatID
			var poll ChatPollState
			var pollValid, pollExists bool
			var pollJSONHash string
			var pollRecoveryFenced bool
			readPoll := func(chatID string) (ChatPollState, bool, bool, string, bool, error) {
				chatID = strings.TrimSpace(chatID)
				if chatID == "" {
					return ChatPollState{}, false, false, "", false, nil
				}
				var pollRaw []byte
				var recoveryRequired sql.NullInt64
				err := db.QueryRowContext(operationCtx, `SELECT json, recovery_required FROM chat_polls WHERE chat_id = ? LIMIT 1`, chatID).Scan(&pollRaw, &recoveryRequired)
				if errors.Is(err, sql.ErrNoRows) {
					return ChatPollState{}, false, false, "", false, nil
				}
				if err != nil {
					return ChatPollState{}, false, false, "", false, err
				}
				if err := chargeJSON(pollRaw); err != nil {
					return ChatPollState{}, false, false, "", false, err
				}
				if err := sqliteHotPollChargeCanonicalFallbackBudget(ctx, 0, int64(len(pollRaw))); err != nil {
					return ChatPollState{}, false, false, "", false, err
				}
				poll, decoded := decodeChatPollState(chatID, pollRaw)
				// decodeChatPollState deliberately returns a typed recovery
				// placeholder for syntax/shape-corrupt bytes.  That placeholder is
				// useful evidence, but it is not an executable/typed poll and must
				// not set HasPoll or bypass the raw poll fence below.
				pollValid := decoded && !chatPollHasOpaqueRecoveryEvidence(poll) && chatPollAdmissionValid(poll)
				return poll, pollValid, true, sha256Bytes(pollRaw), nullableInt64Value(recoveryRequired) != 0, nil
			}
			if canonicalChatOK {
				// The canonical session JSON owns the session-to-chat identity. A
				// stale scalar binding must not even be queried when the canonical
				// identity is available.
				chatID = canonicalChatID
				if controlChatID != "" && chatID == controlChatID {
					continue
				}
				var err error
				poll, pollValid, pollExists, pollJSONHash, pollRecoveryFenced, err = readPoll(chatID)
				if err != nil {
					return nil, err
				}
			} else {
				if controlChatID != "" && chatID == controlChatID {
					continue
				}
				var err error
				poll, pollValid, pollExists, pollJSONHash, pollRecoveryFenced, err = readPoll(chatID)
				if err != nil {
					return nil, err
				}
			}
			chatID = strings.TrimSpace(chatID)
			if chatID == "" {
				continue
			}
			sessionSourceHash := sha256Bytes(sessionRaw)
			// A prior bridge cycle may already have recorded this exact source
			// hash in the chat-local poll. Do not let that durable fence consume
			// the probe result slot forever.
			// A semantic/syntax-invalid poll cannot be rewritten by this recovery
			// lane, so its raw bytes remain the durable forensic witness.  In that
			// case the poll hash, rather than the malformed session hash, is the
			// only witness that can survive the opaque projection update.  Treat
			// that exact poll-local marker as an already-fenced pair as well; without
			// this branch a malformed session plus an opaque poll would emit the same
			// recovery work on every cycle and consume the bounded corruption lane.
			if pollExists && chatPollRecoveryAlreadyFenced(poll, pollJSONHash, sessionSourceHash, pollRecoveryFenced) {
				continue
			}
			evidence := HotPollCorruptSession{
				SessionID:        strings.TrimSpace(sessionID),
				TeamsChatID:      chatID,
				Reason:           "malformed persisted session projection",
				SourceHash:       sessionSourceHash,
				PollJSONHash:     pollJSONHash,
				HasPollJSON:      pollExists,
				PollJSONObserved: true,
			}
			if pollValid && strings.TrimSpace(poll.ChatID) == evidence.TeamsChatID {
				evidence.HasPoll = true
				evidence.PollRevision = poll.PollRevision
			}
			out = append(out, evidence)
		}
		if len(page) < int(pageSize) {
			break
		}
	}
	return out, nil
}

// sqliteSessionCanonicalChatID extracts only the identity field needed to
// route a cold corruption disposition. A typed/duplicate/malformed object is
// not trusted as a whole, but a unique JSON object with a string chat ID still
// gives us a safer routing key than a stale scalar projection.
func sqliteSessionCanonicalChatID(raw []byte) (string, bool) {
	if !jsonValueHasNoDuplicateKeys(raw) {
		return "", false
	}
	var object map[string]json.RawMessage
	if err := json.Unmarshal(raw, &object); err != nil || object == nil {
		return "", false
	}
	value, ok := object["teams_chat_id"]
	if !ok {
		return "", false
	}
	var chatID string
	if err := json.Unmarshal(value, &chatID); err != nil {
		return "", false
	}
	chatID = strings.TrimSpace(chatID)
	return chatID, chatID != ""
}

// loadSQLiteHotPollWorkCandidates uses the scalar projection for healthy
// session/poll rows and falls back to the existing JSON admission query when
// the trusted lane cannot fill the quantum. The fallback remains the oracle
// for legacy, opaque, and mixed-version rows; selected JSON is decoded only
// after the scalar predicates have reduced the healthy set.
func loadSQLiteHotPollWorkCandidates(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit int) ([]SessionContext, error) {
	if limit <= 0 {
		limit = sqliteHotPollReadyLimit
	}
	versionsCurrent, err := sqliteHotPollAdmissionVersionsCurrent(ctx, db, true)
	if err != nil {
		return nil, err
	}
	candidates, _, err := loadSQLiteHotPollWorkCandidatesWithAdmission(ctx, db, controlChatID, idleBefore, now, limit, versionsCurrent, false)
	return candidates, err
}

// loadSQLiteHotPollWorkCandidatesWithAdmission is the shared scalar/JSON
// admission path for callers that already took the marker snapshot. It
// returns the final row-local fallback decision as well as candidates so a
// combined schedule+work admission can collect corrupt-session evidence
// without issuing a second marker/probe pair.
func loadSQLiteHotPollWorkCandidatesWithAdmission(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit int, versionsCurrent bool, graphReadBlocked bool) ([]SessionContext, bool, error) {
	trusted, needsFallback, err := loadSQLiteHotPollWorkCandidatesTrustedAdmission(ctx, db, controlChatID, idleBefore, now, limit, versionsCurrent, graphReadBlocked)
	if err != nil || !needsFallback {
		return trusted, false, err
	}
	// Once any row is untrusted, use one canonical bounded query rather than
	// merging independently limited trusted/untrusted prefixes. The merge can
	// violate the canonical cross-chat order and starve a healthy tail. The
	// canonical predicate remains the final safety oracle, and the account-gate
	// local-replay restriction stays inside that one query.
	legacyPredicate := "1=1"
	if graphReadBlocked {
		legacyPredicate += " AND " + sqliteChatPollLocalOnlyPendingPageSQL("p.json")
	}
	legacy, err := loadSQLiteHotPollWorkCandidatesProjectedWithAdmission(ctx, db, controlChatID, idleBefore, now, limit, legacyPredicate)
	if err != nil {
		return nil, true, err
	}
	return legacy, true, nil
}

// loadSQLiteHotPollWorkCandidatesTrustedAdmission performs only the bounded
// scalar/marker lane. Keeping the fallback decision separate lets the listener
// release Store.mu before the exceptional canonical JSON scan; callers that do
// not have a lock-free snapshot boundary can continue to use the wrapper above.
func loadSQLiteHotPollWorkCandidatesTrustedAdmission(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit int, versionsCurrent bool, graphReadBlocked bool) ([]SessionContext, bool, error) {
	if limit <= 0 {
		return nil, !versionsCurrent, nil
	}
	if !versionsCurrent {
		predicate := "1=1"
		if graphReadBlocked {
			predicate += " AND " + sqliteChatPollLocalOnlyPendingPageSQL("p.json")
		}
		candidates, err := loadSQLiteHotPollWorkCandidatesProjectedWithAdmission(ctx, db, controlChatID, idleBefore, now, limit, predicate)
		return candidates, true, err
	}
	trusted, err := loadSQLiteHotPollWorkCandidatesTrustedWithReadGate(ctx, db, controlChatID, idleBefore, now, limit, graphReadBlocked)
	if err != nil {
		return nil, false, err
	}
	// Probe after the trusted read. This is both the common-path de-duplication
	// and the fail-closed race check: an untrusted row that was present before
	// or during the scalar query is sent to the bounded canonical lane below.
	needsFallback, err := sqliteHotPollAdmissionNeedsFallbackWithVersions(ctx, db, true, versionsCurrent)
	if err != nil {
		return nil, false, err
	}
	if !needsFallback {
		if len(trusted) > limit {
			trusted = trusted[:limit]
		}
		return trusted, false, nil
	}
	return nil, true, nil
}

// loadSQLiteHotPollWorkCandidatesTrusted is the scalar-projection candidate
// lane. It returns only the identity and ordering fields needed to make the
// bounded admission decision, using integer scalar schedule fields in the
// trusted lane; canonical session JSON is hydrated only after the bridge has
// selected its smaller work quantum. The durable execution path still
// performs the canonical identity/status check on that selected hydration,
// while untrusted rows remain in the compatibility lane.
func loadSQLiteHotPollWorkCandidatesTrusted(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit int) ([]SessionContext, error) {
	return loadSQLiteHotPollWorkCandidatesTrustedWithReadGate(ctx, db, controlChatID, idleBefore, now, limit, false)
}

func loadSQLiteHotPollWorkCandidatesTrustedWithReadGate(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit int, graphReadBlocked bool) ([]SessionContext, error) {
	controlChatID = strings.TrimSpace(controlChatID)
	if limit <= 0 {
		return nil, nil
	}
	if now.IsZero() {
		now = time.Now()
	}
	operationalLimit, ordinaryLimit := sqliteHotPollLaneLimits(limit)
	retryLimit := sqliteHotPollRetryLimit(limit)
	nowText := now.UTC().Format(time.RFC3339Nano)
	idleBeforeText := ""
	if !idleBefore.IsZero() {
		idleBeforeText = idleBefore.UTC().Format(time.RFC3339Nano)
	}
	nextPollDue := sqliteCanonicalTimeDueSQL("p.json", "$.next_poll_at", "p.next_poll_at")
	blockedUntilDue := sqliteCanonicalTimeDueSQL("p.json", "$.blocked_until", "p.blocked_until")
	pendingPage := sqliteChatPollPendingPageSQL("p.json")
	pendingPageGraphReplay := sqliteChatPollPendingPageGraphReplaySQL("p.json")
	lastActivityDue := sqliteCanonicalTimeDueSQL("p.json", "$.last_activity_at", "p.last_activity_at")
	sessionUpdatedDue := sqliteCanonicalTimeDueSQL("s.json", "$.updated_at", "s.updated_at")
	sessionScalarTimes := `typeof(s.updated_at) = 'integer'`
	pollScalarTimes := `(typeof(p.updated_at) = 'integer'
  AND typeof(p.next_poll_at) = 'integer'
  AND typeof(p.last_activity_at) = 'integer'
  AND typeof(p.blocked_until) = 'integer')`
	result := make([]SessionContext, 0, limit)
	seenSessions := make(map[string]struct{}, limit)
	seenChats := make(map[string]struct{}, limit)

	type cursor struct {
		updated, next, activity, sessionUpdated int64
		id                                      string
		set                                     bool
	}
	queryLane := func(operational, retry bool, after cursor, pageSize int) ([]SessionContext, cursor, int, error) {
		where := sqliteProjectionTrustedSQL("s") + `
  AND trim(COALESCE(s.teams_chat_id, '')) != ''
  AND (s.status IS NULL OR trim(s.status) = '' OR trim(s.status) = ?)
  AND (? = '' OR trim(s.teams_chat_id) != ?)`
		args := []any{string(SessionStatusActive), controlChatID, controlChatID}
		if graphReadBlocked {
			// When an explicit account/global read gate is active, only a durable
			// receipt whose metadata proves local replay may be admitted. This
			// predicate is intentionally inside the keyset query: Graph-bound rows
			// cannot consume the page limit and starve a local tail regardless of
			// how many throttled chats precede it.
			where += `
  AND p.chat_id IS NOT NULL
  AND p.pending_page_active = 1
			AND ` + sqliteChatPollPendingPageGraphReplayWithScalarActiveSQL("p.json", "p.pending_page_active") + ` = 0`
		}
		if operational {
			where += `
  AND p.chat_id IS NOT NULL
  AND ` + sqliteChatPollAdmissionTrustedSQL("p") + `
  AND ` + sessionScalarTimes + `
  AND ` + pollScalarTimes + `
	  AND p.frontier_active = 1
	  AND ((` + pendingPage + ` = 1 AND ` + pendingPageGraphReplay + ` = 0) OR (` + nextPollDue + ` <= julianday(?) AND ` + blockedUntilDue + ` <= julianday(?)))`
			args = append(args, nowText, nowText)
		} else if retry {
			where += `
  AND p.chat_id IS NOT NULL
  AND ` + sqliteChatPollAdmissionTrustedSQL("p") + `
  AND ` + sessionScalarTimes + `
  AND ` + pollScalarTimes + `
  AND p.frontier_active = 0
  AND p.poll_failure_count > 0
	  AND ` + nextPollDue + ` <= julianday(?) AND ` + blockedUntilDue + ` <= julianday(?)
  AND (p.parked_skip_eligible = 0
       OR (p.poll_state = ? AND ` + nextPollDue + ` <= julianday(?)))`
			args = append(args, nowText, nowText, chatPollStateParked, nowText)
		} else {
			where += `
  AND (p.chat_id IS NULL OR (
    ` + sqliteChatPollAdmissionTrustedSQL("p") + `
    AND ` + sessionScalarTimes + `
    AND ` + pollScalarTimes + `
    AND p.frontier_active = 0
    AND p.poll_failure_count = 0
	    AND ` + nextPollDue + ` <= julianday(?) AND ` + blockedUntilDue + ` <= julianday(?)
    AND (p.parked_skip_eligible = 0
	         OR (p.poll_state = ? AND ` + nextPollDue + ` <= julianday(?)))))`
			args = append(args, nowText, nowText, chatPollStateParked, nowText)
		}
		if !idleBefore.IsZero() {
			where += `
  AND (p.chat_id IS NULL OR NOT (
    ` + pollScalarTimes + `
			AND ` + lastActivityDue + ` > 2440587.5 AND ` + lastActivityDue + ` <= julianday(?)
			AND ` + sessionUpdatedDue + ` <= julianday(?)
    AND p.parked_skip_eligible = 0
    AND p.poll_state = ?
    AND p.poll_failure_count = 0
    AND p.frontier_active = 0
    AND p.attempt_active = 0
    AND NOT EXISTS (
      SELECT 1 FROM turns t
      WHERE t.session_id = s.id
				AND (` + sqliteProjectionUntrustedSQL("t") + `
             OR t.status IN (?, ?)
             OR (t.status <> '' AND t.status NOT IN (?, ?, ?)))
    )
  ))`
			args = append(args, idleBeforeText, idleBeforeText, chatPollStateCold,
				string(TurnStatusQueued), string(TurnStatusRunning),
				string(TurnStatusCompleted), string(TurnStatusFailed), string(TurnStatusInterrupted))
		}
		if after.set {
			where += `
  AND (COALESCE(p.updated_at, 0) > ?
       OR (COALESCE(p.updated_at, 0) = ? AND COALESCE(p.next_poll_at, 0) > ?)
       OR (COALESCE(p.updated_at, 0) = ? AND COALESCE(p.next_poll_at, 0) = ? AND COALESCE(p.last_activity_at, 0) > ?)
       OR (COALESCE(p.updated_at, 0) = ? AND COALESCE(p.next_poll_at, 0) = ? AND COALESCE(p.last_activity_at, 0) = ? AND COALESCE(s.updated_at, 0) > ?)
       OR (COALESCE(p.updated_at, 0) = ? AND COALESCE(p.next_poll_at, 0) = ? AND COALESCE(p.last_activity_at, 0) = ? AND COALESCE(s.updated_at, 0) = ? AND s.id > ?))`
			args = append(args,
				after.updated, after.updated, after.next,
				after.updated, after.next, after.activity,
				after.updated, after.next, after.activity, after.sessionUpdated,
				after.updated, after.next, after.activity, after.sessionUpdated, after.id)
		}
		args = append(args, pageSize)
		query := `SELECT s.id, s.teams_chat_id, s.status,
		       ` + sqliteStoredInt64SQL("s.updated_at") + `,
       COALESCE(p.updated_at, 0), COALESCE(p.next_poll_at, 0),
       COALESCE(p.last_activity_at, 0), COALESCE(s.updated_at, 0)
FROM sessions s
LEFT JOIN chat_polls p ON p.chat_id = trim(s.teams_chat_id)
WHERE ` + where + `
ORDER BY COALESCE(p.updated_at, 0), COALESCE(p.next_poll_at, 0),
         COALESCE(p.last_activity_at, 0), COALESCE(s.updated_at, 0), s.id
LIMIT ?`
		rows, err := db.QueryContext(ctx, query, args...)
		if err != nil {
			return nil, after, 0, err
		}
		out := make([]SessionContext, 0, pageSize)
		last := after
		scanned := 0
		for rows.Next() {
			var id string
			var scalarChatID, scalarStatus sql.NullString
			var scalarUpdated sql.NullInt64
			var updated, next, activity, sessionUpdated int64
			if err := rows.Scan(&id, &scalarChatID, &scalarStatus, &scalarUpdated, &updated, &next, &activity, &sessionUpdated); err != nil {
				return nil, last, scanned, err
			}
			scanned++
			last = cursor{updated: updated, next: next, activity: activity, sessionUpdated: sessionUpdated, id: id, set: true}
			status := strings.TrimSpace(nullableStringValue(scalarStatus))
			if status == "" {
				status = string(SessionStatusActive)
			}
			out = append(out, SessionContext{
				ID:          strings.TrimSpace(id),
				Status:      SessionStatus(status),
				TeamsChatID: strings.TrimSpace(nullableStringValue(scalarChatID)),
				UpdatedAt:   sqliteStoredProjectionTime(scalarUpdated),
			})
		}
		if err := rows.Err(); err != nil {
			return nil, last, scanned, err
		}
		if err := rows.Close(); err != nil {
			return nil, last, scanned, err
		}
		return out, last, scanned, nil
	}

	appendLane := func(operational, retry bool, quota int) error {
		if quota <= 0 || len(result) >= limit {
			return nil
		}
		accepted := 0
		after := cursor{}
		const pageSize = 64
		for accepted < quota && len(result) < limit {
			if err := ctx.Err(); err != nil {
				return err
			}
			rows, next, scanned, err := queryLane(operational, retry, after, pageSize)
			if err != nil {
				return err
			}
			if scanned == 0 {
				// No SQL rows remain in this lane. A page can contain only rows
				// that failed the final canonical check, so len(rows) alone is not
				// an exhaustion signal.
				break
			}
			for _, session := range rows {
				id := strings.TrimSpace(session.ID)
				chatID := strings.TrimSpace(session.TeamsChatID)
				if id == "" || chatID == "" {
					continue
				}
				if _, ok := seenSessions[id]; ok {
					continue
				}
				if _, ok := seenChats[chatID]; ok {
					continue
				}
				seenSessions[id] = struct{}{}
				seenChats[chatID] = struct{}{}
				result = append(result, session)
				accepted++
				if accepted >= quota || len(result) >= limit {
					break
				}
			}
			if scanned < pageSize {
				break
			}
			after = next
		}
		return nil
	}
	if err := appendLane(false, true, retryLimit); err != nil {
		return nil, err
	}
	if err := appendLane(false, false, ordinaryLimit); err != nil {
		return nil, err
	}
	if err := appendLane(true, false, operationalLimit); err != nil {
		return nil, err
	}
	return result, nil
}

func loadSQLiteHotPollWorkCandidatesProjected(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit int) ([]SessionContext, error) {
	candidates, _, err := loadSQLiteHotPollWorkCandidatesProjectedWithBudget(ctx, db, controlChatID, idleBefore, now, limit, sqliteHotPollMalformedLimit,
		`(`+sqliteLegacyProjectionUntrustedSQL("s")+` OR (p.chat_id IS NOT NULL AND (`+sqliteLegacyChatPollAdmissionUntrustedSQL("p")+`)))`)
	return candidates, err
}

func loadSQLiteHotPollWorkCandidatesStaleGeneration(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit int) ([]SessionContext, error) {
	candidates, _, err := loadSQLiteHotPollWorkCandidatesStaleGenerationWithBudget(ctx, db, controlChatID, idleBefore, now, limit, sqliteHotPollMalformedLimit)
	return candidates, err
}

func loadSQLiteHotPollWorkCandidatesStaleGenerationWithBudget(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit, malformedLimit int) ([]SessionContext, int, error) {
	if limit <= 0 {
		return nil, 0, nil
	}
	return loadSQLiteHotPollWorkCandidatesProjectedWithBudget(ctx, db, controlChatID, idleBefore, now, limit, malformedLimit,
		`((`+sqliteProjectionStaleGenerationTrustedSQL("s")+`) OR (p.chat_id IS NOT NULL AND (`+sqliteProjectionStaleGenerationTrustedSQL("p")+`)))`)
}

// loadSQLiteHotPollWorkCandidatesProjectedWithAdmission is the bounded JSON
// compatibility reader shared by the normal untrusted lane and the
// stale-generation recovery lane. The caller supplies a fixed, internal SQL
// predicate; neither path accepts user SQL. Keeping the predicate lane
// separate preserves the old partial-index plan for the common fallback while
// the caller controls the bounded admission quantum independently of the
// merge fairness prefix.
func loadSQLiteHotPollWorkCandidatesProjectedWithAdmission(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit int, admissionPredicate string) ([]SessionContext, error) {
	candidates, _, err := loadSQLiteHotPollWorkCandidatesProjectedWithBudget(ctx, db, controlChatID, idleBefore, now, limit, sqliteHotPollMalformedLimit, admissionPredicate)
	return candidates, err
}

func loadSQLiteHotPollWorkCandidatesProjectedWithBudget(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit, malformedLimit int, admissionPredicate string) (outCandidates []SessionContext, outMalformed int, outErr error) {
	if ctx == nil {
		ctx = context.Background()
	}
	parentCtx := ctx
	operationCtx, cancel := context.WithTimeout(ctx, sqliteHotPollLegacyMaxDuration)
	defer cancel()
	ctx = operationCtx
	defer func() {
		if outErr != nil && parentCtx.Err() == nil && errors.Is(operationCtx.Err(), context.DeadlineExceeded) {
			outErr = fmt.Errorf("%w: compatibility work admission exceeded %s: %v", errSQLiteHotPollAdmissionIndeterminate, sqliteHotPollLegacyMaxDuration, outErr)
		}
	}()
	controlChatID = strings.TrimSpace(controlChatID)
	if limit <= 0 {
		return nil, 0, nil
	}
	if malformedLimit < 0 {
		malformedLimit = 0
	}
	operationalLimit, ordinaryLimit := sqliteHotPollLaneLimits(limit)
	retryLimit := sqliteHotPollRetryLimit(limit)
	if now.IsZero() {
		now = time.Now()
	}
	var scannedRows, scannedJSONBytes int64
	chargeRow := func(raws ...[]byte) error {
		scannedRows++
		if scannedRows > sqliteHotPollLegacyMaxRows {
			return fmt.Errorf("%w: compatibility work admission exceeded %d rows", errSQLiteHotPollAdmissionIndeterminate, sqliteHotPollLegacyMaxRows)
		}
		var rowBytesTotal int64
		for _, raw := range raws {
			rowBytes := int64(len(raw))
			if rowBytes > sqliteHotPollLegacyMaxJSONRowBytes {
				return fmt.Errorf("%w: compatibility work admission encountered %d-byte JSON row", errSQLiteHotPollAdmissionIndeterminate, rowBytes)
			}
			if rowBytes > sqliteHotPollLegacyMaxJSONBytes-scannedJSONBytes {
				return fmt.Errorf("%w: compatibility work admission exceeded %d JSON bytes", errSQLiteHotPollAdmissionIndeterminate, sqliteHotPollLegacyMaxJSONBytes)
			}
			scannedJSONBytes += rowBytes
			rowBytesTotal += rowBytes
		}
		return sqliteHotPollChargeCanonicalFallbackBudget(ctx, 1, rowBytesTotal)
	}
	sessionChatID := sqliteCanonicalTextProjectionSQL("s.json", "$.teams_chat_id", "s.teams_chat_id")
	sessionUpdatedAt := sqliteCanonicalTimeProjectionSQL("s.json", "$.updated_at", "s.updated_at")
	sessionUpdatedDue := sqliteCanonicalTimeDueSQL("s.json", "$.updated_at", "s.updated_at")
	pollUpdatedAt := sqliteCanonicalTimeProjectionSQL("p.json", "$.updated_at", "p.updated_at")
	pollNextAt := sqliteCanonicalTimeProjectionSQL("p.json", "$.next_poll_at", "p.next_poll_at")
	pollNextDue := sqliteCanonicalTimeDueSQL("p.json", "$.next_poll_at", "p.next_poll_at")
	pollActivityAt := sqliteCanonicalTimeProjectionSQL("p.json", "$.last_activity_at", "p.last_activity_at")
	pollActivityDue := sqliteCanonicalTimeDueSQL("p.json", "$.last_activity_at", "p.last_activity_at")
	pollBlockedDue := sqliteCanonicalTimeDueSQL("p.json", "$.blocked_until", "p.blocked_until")
	pollState := sqliteCanonicalTextProjectionSQL("p.json", "$.state", "p.poll_state")
	pollFailureCount := sqliteChatPollFailureCountSQL("p.json")
	pollFrontier := sqliteChatPollOperationalFrontierSQL("p.json")
	pollPendingPage := sqliteChatPollPendingPageSQL("p.json")
	pollPendingPageGraphReplay := sqliteChatPollPendingPageGraphReplaySQL("p.json")
	pollParkedSkipEligible := sqliteCanonicalParkedSkipProjectionSQL("p.json", "p.parked_skip_eligible", "p.poll_state")
	canonicalTurnStatus := sqliteTurnSafetyStatusSQL("t.json", "t.status")
	scheduleValidPoll := sqliteChatPollScheduleValidJSONSQL("p.json", "p.chat_id")
	malformedPoll := `(p.chat_id IS NOT NULL AND (json_valid(p.json) = 0 OR NOT (` + scheduleValidPoll + `) OR COALESCE(p.admission_valid, 1) = 0))`
	// A malformed poll is normally a local-repair candidate even when stale
	// schedule metadata says it is blocked: the scheduler cannot safely infer a
	// retry deadline from a row it cannot decode. The one exception is an opaque
	// poll whose error callback durably recorded both recovery_required and the
	// blocked state in the scalar sidecar. That pair is an explicit 429/retry
	// fence; the raw JSON may be too damaged to decode blocked_until, so the
	// scalar/canonical due expression is the conservative gate. Keep this gate
	// narrow so unrelated malformed rows do not disappear from local repair.
	malformedOpaqueRetryGate := `(COALESCE(p.recovery_required, 0) != 1 OR trim(COALESCE(p.poll_state, '')) <> '` + chatPollStateBlocked + `' OR ` + sqliteCanonicalTimeDueSQL("p.json", "$.blocked_until", "p.blocked_until") + ` <= julianday(?))`
	malformedPollReady := malformedPoll + ` AND ` + malformedOpaqueRetryGate

	// The SQL projection supplies only cheap, indexed scheduling predicates.
	// Canonical session/poll JSON is decoded once per admitted page in Go. The
	// old query validated every optional field with JSON1 before applying its
	// LIMIT; on a large but healthy backlog that turned one poll tick into a
	// full JSON parse of every candidate. Keyset pages retain the important
	// safety property: a malformed prefix cannot consume the lane LIMIT and
	// hide healthy rows behind it.
	type cursor struct {
		updated, next, activity, sessionUpdated int64
		id                                      string
		set                                     bool
	}
	type candidateRow struct {
		sessionID, sessionRaw, chatID, pollChatID string
		pollRaw                                   []byte
		updated, next, activity                   int64
		sessionUpdated                            int64
	}

	// A current-version writer marks a poll's admission bit invalid in the
	// same trigger that revokes its projection trust.  Read those chat IDs from
	// the small indexed quarantine lane before opening the JSON compatibility
	// query.  The old fallback put every quarantined row into the ordered JSON
	// page; a long malformed prefix could therefore spend the entire two-second
	// compatibility budget before reaching a healthy scalar row.  Only rows
	// whose session projection is itself trusted are removed from the canonical
	// page: an untrusted session still goes through the slower canonical oracle
	// so a stale scalar binding cannot hide it.
	fastMalformedPollIDs := make([]string, 0, malformedLimit)
	preloadedMalformedPollRows := make([]candidateRow, 0, malformedLimit)
	if malformedLimit > 0 {
		idRows, err := db.QueryContext(ctx, `SELECT p.chat_id
FROM sessions s
JOIN chat_polls p ON p.chat_id = trim(COALESCE(s.teams_chat_id, ''))
WHERE trim(COALESCE(s.teams_chat_id, '')) != ''
  AND (? = '' OR trim(s.teams_chat_id) != ?)
  AND `+sqliteProjectionTrustedSQL("s")+`
  AND p.admission_valid = 0
  AND (`+admissionPredicate+`)
  AND (COALESCE(p.recovery_required, 0) != 1
       OR trim(COALESCE(p.poll_state, '')) != ?
       OR `+sqliteStoredInt64SQL("p.blocked_until")+` <= ?)
ORDER BY `+sqliteStoredInt64SQL("p.updated_at")+`, `+sqliteStoredInt64SQL("p.next_poll_at")+`,
         `+sqliteStoredInt64SQL("p.last_activity_at")+`, p.chat_id
LIMIT ?`, controlChatID, controlChatID, chatPollStateBlocked, sqliteTime(now), malformedLimit)
		if err != nil {
			return nil, 0, err
		}
		for idRows.Next() {
			var chatID string
			if err := idRows.Scan(&chatID); err != nil {
				_ = idRows.Close()
				return nil, 0, err
			}
			chatID = strings.TrimSpace(chatID)
			if chatID == "" {
				continue
			}
			if err := chargeRow(); err != nil {
				_ = idRows.Close()
				return nil, 0, err
			}
			fastMalformedPollIDs = append(fastMalformedPollIDs, chatID)
		}
		if err := idRows.Err(); err != nil {
			_ = idRows.Close()
			return nil, 0, err
		}
		if err := idRows.Close(); err != nil {
			return nil, 0, err
		}
		// Load only the reserved recovery prefix's complete rows.  The remaining
		// quarantined IDs stay excluded from ordinary lanes for this cycle and
		// are rotated by the durable recovery policy on later cycles.
		for _, chatID := range fastMalformedPollIDs[:sqliteHotPollMinInt(len(fastMalformedPollIDs), malformedLimit)] {
			var item candidateRow
			err := db.QueryRowContext(ctx, `SELECT s.id, s.json, `+sessionChatID+`, p.chat_id, p.json,
       `+pollUpdatedAt+`, `+pollNextAt+`, `+pollActivityAt+`, `+sessionUpdatedAt+`
FROM sessions s
JOIN chat_polls p ON p.chat_id = trim(COALESCE(s.teams_chat_id, ''))
WHERE p.chat_id = ?
  AND `+sqliteProjectionTrustedSQL("s")+`
  AND p.admission_valid = 0
  AND (`+admissionPredicate+`)
  AND (COALESCE(p.recovery_required, 0) != 1
       OR trim(COALESCE(p.poll_state, '')) != ?
       OR `+sqliteStoredInt64SQL("p.blocked_until")+` <= ?)`, chatID, chatPollStateBlocked, sqliteTime(now)).Scan(
				&item.sessionID, &item.sessionRaw, &item.chatID, &item.pollChatID, &item.pollRaw,
				&item.updated, &item.next, &item.activity, &item.sessionUpdated)
			if errors.Is(err, sql.ErrNoRows) {
				fastMalformedPollIDs = nil
				preloadedMalformedPollRows = nil
				break
			}
			if err != nil {
				return nil, 0, err
			}
			if err := chargeRow([]byte(item.sessionRaw), item.pollRaw); err != nil {
				return nil, 0, err
			}
			preloadedMalformedPollRows = append(preloadedMalformedPollRows, item)
		}
	}
	queryRows := func(operational bool, retry bool, after cursor, pageSize int) ([]candidateRow, error) {
		where := sessionChatID + ` != ''
	  AND (? = '' OR ` + sessionChatID + ` != ?)
	  AND ` + admissionPredicate + `
	  AND (COALESCE(s.teams_chat_id, '') = '' OR trim(s.teams_chat_id) = trim(` + sessionChatID + `) OR p.chat_id IS NOT NULL OR legacy_p.chat_id IS NULL)`
		args := []any{controlChatID, controlChatID}
		if len(fastMalformedPollIDs) > 0 {
			placeholders := strings.TrimRight(strings.Repeat("?,", len(fastMalformedPollIDs)), ",")
			where += `
  AND (p.chat_id IS NULL OR p.chat_id NOT IN (` + placeholders + `))`
			for _, chatID := range fastMalformedPollIDs {
				args = append(args, chatID)
			}
			// The bounded quarantine query above has already reserved the only
			// malformed poll slots this cycle.  Keep the remaining writer-marked
			// invalid rows out of the ordered compatibility pages: otherwise the
			// malformedPoll JSON1 predicate would parse every quarantined row just
			// to discard it after the lane quota was filled.  NULL is deliberately
			// treated as unknown and remains in the canonical path; only the
			// explicit current-writer invalid bit is safe to skip here.
			where += `
  AND (p.chat_id IS NULL OR COALESCE(p.admission_valid, 1) != 0)`
		}
		if operational {
			where += `
	  AND p.chat_id IS NOT NULL
		  AND (` + malformedPollReady + ` OR (
		    NOT ` + malformedPoll + `
		    AND
		    ` + pollFrontier + ` != 0
		  AND ((` + pollPendingPage + ` = 1 AND ` + pollPendingPageGraphReplay + ` = 0) OR (` + pollNextDue + ` <= julianday(?)
		         AND ` + pollBlockedDue + ` <= julianday(?)))))`
		} else {
			where += `
		  AND (p.chat_id IS NULL OR ` + malformedPollReady + ` OR (
		    NOT ` + malformedPoll + `
		    AND
		    ` + pollFrontier + ` = 0
		    AND ` + pollFailureCount + ` ` + map[bool]string{true: ">", false: "="}[retry] + ` 0
		    AND ` + pollNextDue + ` <= julianday(?)
	    AND ` + pollBlockedDue + ` <= julianday(?)
	    AND (` + pollParkedSkipEligible + ` = 0
	         OR (` + pollState + ` = ? AND ` + pollNextDue + ` <= julianday(?)))
	  ))`
			args = append(args, now.UTC().Format(time.RFC3339Nano), now.UTC().Format(time.RFC3339Nano), now.UTC().Format(time.RFC3339Nano), chatPollStateParked, now.UTC().Format(time.RFC3339Nano))
		}
		if !operational && retry {
			// Retry admission is for a valid, ordinary poll row only. Syntax or
			// shape-corrupt rows stay in the dedicated bounded recovery lane.
			where += `
		  AND p.chat_id IS NOT NULL
		  AND NOT (` + malformedPoll + `)`
		}
		if operational {
			args = append(args, now.UTC().Format(time.RFC3339Nano), now.UTC().Format(time.RFC3339Nano), now.UTC().Format(time.RFC3339Nano))
		}
		if !idleBefore.IsZero() {
			idle := `
	    ` + pollActivityAt + ` > 0
	    AND ` + pollActivityDue + ` <= julianday(?)
	    AND ` + sessionUpdatedDue + ` <= julianday(?)
	    AND ` + pollParkedSkipEligible + ` = 0
	    AND ` + pollState + ` IN (?)
	    AND ` + pollFailureCount + ` = 0
	    AND ` + pollFrontier + ` = 0
    AND CASE WHEN json_valid(p.json) THEN
      CASE WHEN json_type(p.json, '$.attempt') IS NULL THEN 1 ELSE 0 END
      ELSE 0 END = 1
    AND NOT EXISTS (
    SELECT 1 FROM turns t
      WHERE t.session_id = s.id
        AND ` + sqliteTurnActiveStatusSQL(canonicalTurnStatus) + `
    )
  `
			// Syntax- or schedule-corrupt rows are recovery candidates regardless
			// of stale compatibility columns. A malformed row must not be parked
			// by the idle optimization before the listener can isolate it.
			where += `
	  AND (p.chat_id IS NULL OR ` + malformedPoll + ` OR NOT (` + idle + `))`
			idleBeforeText := idleBefore.UTC().Format(time.RFC3339Nano)
			args = append(args, idleBeforeText, idleBeforeText, chatPollStateCold)
			args = append(args, sqliteTurnActiveStatusArgs()...)
		}
		if after.set {
			where += `
	  AND (` + pollUpdatedAt + ` > ?
	       OR (` + pollUpdatedAt + ` = ? AND ` + pollNextAt + ` > ?)
	       OR (` + pollUpdatedAt + ` = ? AND ` + pollNextAt + ` = ? AND ` + pollActivityAt + ` > ?)
	       OR (` + pollUpdatedAt + ` = ? AND ` + pollNextAt + ` = ? AND ` + pollActivityAt + ` = ? AND ` + sessionUpdatedAt + ` > ?)
	       OR (` + pollUpdatedAt + ` = ? AND ` + pollNextAt + ` = ? AND ` + pollActivityAt + ` = ? AND ` + sessionUpdatedAt + ` = ? AND s.id > ?))`
			args = append(args,
				after.updated, after.updated, after.next,
				after.updated, after.next, after.activity,
				after.updated, after.next, after.activity, after.sessionUpdated,
				after.updated, after.next, after.activity, after.sessionUpdated, after.id)
		}
		query := `SELECT s.id, s.json, COALESCE(` + sessionChatID + `, ''), COALESCE(p.chat_id, ''),
       COALESCE(p.json, ''), ` + pollUpdatedAt + `,
       ` + pollNextAt + `, ` + pollActivityAt + `,
       ` + sessionUpdatedAt + `
FROM sessions s
LEFT JOIN chat_polls p ON p.chat_id = ` + sessionChatID + `
LEFT JOIN chat_polls legacy_p ON legacy_p.chat_id = trim(s.teams_chat_id)
  AND trim(s.teams_chat_id) != trim(` + sessionChatID + `)
WHERE ` + where + `
ORDER BY ` + pollUpdatedAt + `, ` + pollNextAt + `,
         ` + pollActivityAt + `, ` + sessionUpdatedAt + `, s.id
LIMIT ?`
		args = append(args, pageSize)
		rows, err := db.QueryContext(ctx, query, args...)
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		out := make([]candidateRow, 0, pageSize)
		for rows.Next() {
			var item candidateRow
			if err := rows.Scan(&item.sessionID, &item.sessionRaw, &item.chatID, &item.pollChatID, &item.pollRaw,
				&item.updated, &item.next, &item.activity, &item.sessionUpdated); err != nil {
				return nil, err
			}
			if err := chargeRow([]byte(item.sessionRaw), []byte(item.pollRaw)); err != nil {
				_ = rows.Close()
				return nil, err
			}
			out = append(out, item)
		}
		return out, rows.Err()
	}

	result := make([]SessionContext, 0, limit)
	seenSessions := make(map[string]struct{}, limit)
	// A chat owns one durable poll frontier. Multiple historical/session rows
	// can temporarily point at the same Teams chat (for example while a
	// migration or fork repair is settling). Admit that chat only once per
	// cycle; polling it twice would issue duplicate Graph reads without adding
	// any delivery safety.
	seenChats := make(map[string]struct{}, limit)
	acceptedChats := make(map[string]struct{}, limit)
	malformedPolls := 0
	deferredOperational := make([]SessionContext, 0, limit)
	deferredOrdinary := make([]SessionContext, 0, limit)
	deferredSeen := make(map[string]struct{}, limit)
	for _, item := range preloadedMalformedPollRows {
		var session SessionContext
		if !jsonValueHasNoDuplicateKeys([]byte(item.sessionRaw)) || json.Unmarshal([]byte(item.sessionRaw), &session) != nil ||
			strings.TrimSpace(session.ID) == "" || strings.TrimSpace(session.ID) != strings.TrimSpace(item.sessionID) ||
			strings.TrimSpace(session.TeamsChatID) == "" || strings.TrimSpace(item.pollChatID) != strings.TrimSpace(session.TeamsChatID) ||
			(session.Status != "" && session.Status != SessionStatusActive) {
			// The fast quarantine lane is only an optimization for a row whose
			// session identity is already trusted. If that witness changed while
			// it was being read, retain the complete canonical query rather than
			// excluding a poll whose session may need corruption recovery.
			fastMalformedPollIDs = nil
			preloadedMalformedPollRows = nil
			break
		}
		chatID := strings.TrimSpace(session.TeamsChatID)
		if _, exists := seenSessions[session.ID]; exists {
			continue
		}
		if _, exists := seenChats[chatID]; exists {
			continue
		}
		seenSessions[session.ID] = struct{}{}
		seenChats[chatID] = struct{}{}
		acceptedChats[chatID] = struct{}{}
		malformedPolls++
		result = append(result, session)
		if len(result) >= limit || malformedPolls >= malformedLimit {
			break
		}
	}
	appendLane := func(operational bool, retry bool, quota int) error {
		if quota <= 0 || len(result) >= limit {
			return nil
		}
		valid := 0
		after := cursor{}
		const pageSize = 64
		for page := 0; valid < quota && len(result) < limit; page++ {
			// The keyset cursor makes this scan finite when the table is finite;
			// do not impose an arbitrary page count that can hide a healthy chat
			// behind more than 512 locally-corrupt rows. The caller's phase
			// context remains the resource boundary for an unusually large
			// corrupt table.
			if err := ctx.Err(); err != nil {
				return err
			}
			items, err := queryRows(operational, retry, after, pageSize)
			if err != nil {
				return err
			}
			if len(items) == 0 {
				break
			}
			for _, item := range items {
				if err := ctx.Err(); err != nil {
					return err
				}
				after = cursor{updated: item.updated, next: item.next, activity: item.activity, sessionUpdated: item.sessionUpdated, id: item.sessionID, set: true}
				var session SessionContext
				if !jsonValueHasNoDuplicateKeys([]byte(item.sessionRaw)) || json.Unmarshal([]byte(item.sessionRaw), &session) != nil ||
					strings.TrimSpace(session.ID) == "" || strings.TrimSpace(session.ID) != strings.TrimSpace(item.sessionID) ||
					strings.TrimSpace(session.TeamsChatID) == "" ||
					(item.chatID != "" && strings.TrimSpace(session.TeamsChatID) != strings.TrimSpace(item.chatID)) ||
					(session.Status != "" && session.Status != SessionStatusActive) {
					continue
				}
				if _, exists := seenSessions[session.ID]; exists {
					continue
				}
				chatID := strings.TrimSpace(session.TeamsChatID)
				if _, exists := seenChats[chatID]; exists {
					continue
				}
				pollMalformed := false
				var poll ChatPollState
				if item.chatID != "" {
					if !jsonValueHasNoDuplicateKeys(item.pollRaw) || json.Unmarshal(item.pollRaw, &poll) != nil || strings.TrimSpace(poll.ChatID) != strings.TrimSpace(item.chatID) || !chatPollAdmissionValid(poll) {
						pollMalformed = true
					}
				}
				if pollMalformed {
					if malformedPolls >= malformedLimit {
						continue
					}
					malformedPolls++
				} else if actualOperational := chatPollHasOperationalFrontier(poll); actualOperational != operational {
					if _, ok := deferredSeen[chatID]; !ok {
						deferredSeen[chatID] = struct{}{}
						if actualOperational {
							deferredOperational = append(deferredOperational, session)
						} else {
							deferredOrdinary = append(deferredOrdinary, session)
						}
					}
					seenChats[chatID] = struct{}{}
					continue
				} else {
					valid++
				}
				seenSessions[session.ID] = struct{}{}
				seenChats[chatID] = struct{}{}
				acceptedChats[chatID] = struct{}{}
				result = append(result, session)
				if valid >= quota || len(result) >= limit {
					break
				}
			}
			if len(items) < pageSize {
				break
			}
		}
		return nil
	}
	if err := appendLane(false, true, retryLimit); err != nil {
		return nil, malformedPolls, err
	}
	if err := appendLane(false, false, ordinaryLimit); err != nil {
		return nil, malformedPolls, err
	}
	for _, session := range deferredOperational {
		if len(result) >= limit {
			break
		}
		chatID := strings.TrimSpace(session.TeamsChatID)
		if _, ok := seenSessions[session.ID]; ok {
			continue
		}
		if _, ok := acceptedChats[chatID]; ok {
			continue
		}
		if _, ok := deferredSeen[chatID]; !ok {
			continue
		}
		seenSessions[session.ID] = struct{}{}
		acceptedChats[chatID] = struct{}{}
		result = append(result, session)
	}
	if err := appendLane(true, false, operationalLimit); err != nil {
		return nil, malformedPolls, err
	}
	for _, session := range deferredOrdinary {
		if len(result) >= limit {
			break
		}
		chatID := strings.TrimSpace(session.TeamsChatID)
		if _, ok := seenSessions[session.ID]; ok {
			continue
		}
		if _, ok := acceptedChats[chatID]; ok {
			continue
		}
		if _, ok := deferredSeen[chatID]; !ok {
			continue
		}
		seenSessions[session.ID] = struct{}{}
		acceptedChats[chatID] = struct{}{}
		result = append(result, session)
	}
	return result, malformedPolls, nil
}

func loadSQLiteHotPollWorkCandidatesLegacy(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, now time.Time, limit int) ([]SessionContext, error) {
	controlChatID = strings.TrimSpace(controlChatID)
	if limit <= 0 {
		limit = sqliteHotPollReadyLimit
	}
	operationalLimit, ordinaryLimit := sqliteHotPollLaneLimits(limit)
	retryLimit := sqliteHotPollRetryLimit(limit)
	if now.IsZero() {
		now = time.Now()
	}
	validSession := sqliteSessionValidJSONSQL("s.json", "s.id", "s.teams_chat_id")
	activeSession := sqliteSessionActiveJSONSQL("s.json", "s.status")
	// The legacy CTE path is only used when the indexed hot-poll projection is
	// unavailable. It therefore keeps the stricter semantic validator here so a
	// valid-looking row with a bad schedule type cannot consume the ordinary
	// LIMIT and hide the reserved malformed lane.
	validPoll := sqliteChatPollAdmissionValidJSONSQL("p.json", "p.chat_id")
	malformedPoll := `NOT (` + validPoll + `)`
	frontier := sqliteChatPollOperationalFrontierSQL("p.json")
	pendingPage := sqliteChatPollPendingPageSQL("p.json")
	pendingPageGraphReplay := sqliteChatPollPendingPageGraphReplaySQL("p.json")
	pollFailureCount := sqliteChatPollFailureCountSQL("p.json")
	canonicalTurnStatus := sqliteTurnSafetyStatusSQL("t.json", "t.status")
	excludeIdle := ""
	operationalIdle := ""
	ordinaryIdle := ""
	// Keep the arguments in the same order as the CTEs below.  In particular,
	// the idle predicate is appended after the operational/ordinary lane's
	// readiness arguments; putting it first makes every placeholder after the
	// control row receive the wrong value and silently removes work chats from
	// the candidate set.
	args := []any{controlChatID}
	if !idleBefore.IsZero() {
		// A malformed poll is admitted as a chat-local recovery candidate and
		// therefore bypasses schedule/idle predicates that depend on untrusted
		// JSON. For valid rows the derived frontier flag replaces the previous
		// JSON1 probes; an attempt is still checked with a guarded CASE because
		// it is a short-lived field that is not worth another column.
		excludeIdle = `  AND NOT (
    COALESCE(p.last_activity_at, 0) > 0
    AND COALESCE(p.last_activity_at, 0) <= ?
    AND COALESCE(s.updated_at, 0) <= ?
    AND COALESCE(p.parked_skip_eligible, 0) = 0
    AND p.poll_state IN (?)
	    AND ` + pollFailureCount + ` = 0
			AND ` + validPoll + `
    AND NOT ` + frontier + `
    AND CASE WHEN json_valid(p.json) THEN
      CASE WHEN json_type(p.json, '$.attempt') IS NULL THEN 1 ELSE 0 END
      ELSE 0 END = 1
    AND NOT EXISTS (
      SELECT 1 FROM turns t
      WHERE t.session_id = s.id
        AND ` + sqliteTurnActiveStatusSQL(canonicalTurnStatus) + `
    )
  )
		`
		operationalIdle, ordinaryIdle = excludeIdle, excludeIdle
	}
	args = append(args, controlChatID, controlChatID, sqliteTime(now), sqliteTime(now), chatPollStateParked, sqliteTime(now))
	if !idleBefore.IsZero() {
		idleBeforeUnix := sqliteTime(idleBefore)
		args = append(args, idleBeforeUnix, idleBeforeUnix, chatPollStateCold)
		args = append(args, sqliteTurnActiveStatusArgs()...)
	}
	args = append(args, retryLimit)
	args = append(args, controlChatID, controlChatID, sqliteTime(now), sqliteTime(now), chatPollStateParked, sqliteTime(now))
	if !idleBefore.IsZero() {
		idleBeforeUnix := sqliteTime(idleBefore)
		args = append(args, idleBeforeUnix, idleBeforeUnix, chatPollStateCold)
		args = append(args, sqliteTurnActiveStatusArgs()...)
	}
	args = append(args, ordinaryLimit)
	args = append(args, controlChatID, controlChatID, sqliteHotPollMalformedLimit)
	args = append(args, controlChatID, controlChatID, sqliteTime(now), sqliteTime(now))
	if !idleBefore.IsZero() {
		idleBeforeUnix := sqliteTime(idleBefore)
		args = append(args, idleBeforeUnix, idleBeforeUnix, chatPollStateCold)
		args = append(args, sqliteTurnActiveStatusArgs()...)
	}
	args = append(args, operationalLimit)
	args = append(args, limit, controlChatID)
	query := `WITH control AS (
    SELECT s.json, s.id, s.teams_chat_id AS chat_id, 0 AS lane,
           COALESCE(p.updated_at, 0) AS sort_updated,
           COALESCE(p.next_poll_at, 0) AS sort_next,
           COALESCE(p.last_activity_at, 0) AS sort_activity
    FROM sessions s
    JOIN chat_polls p ON p.chat_id = s.teams_chat_id
    WHERE s.teams_chat_id = ?
      AND ` + validSession + `
      AND ` + activeSession + `
      AND (` + validPoll + ` OR ` + malformedPoll + `)
    LIMIT 1
), retry AS (
    SELECT s.json, s.id, s.teams_chat_id AS chat_id, 1 AS lane,
           COALESCE(p.updated_at, 0) AS sort_updated,
           COALESCE(p.next_poll_at, 0) AS sort_next,
           COALESCE(p.last_activity_at, 0) AS sort_activity
    FROM sessions s
    LEFT JOIN chat_polls p ON p.chat_id = s.teams_chat_id
    WHERE COALESCE(s.teams_chat_id, '') != ''
      AND (? = '' OR s.teams_chat_id != ?)
      AND ` + validSession + `
      AND ` + activeSession + `
      AND p.chat_id IS NOT NULL
      AND ` + validPoll + `
      AND NOT ` + frontier + `
      AND ` + pollFailureCount + ` > 0
      AND COALESCE(p.next_poll_at, 0) <= ?
      AND COALESCE(p.blocked_until, 0) <= ?
      AND (COALESCE(p.parked_skip_eligible, 0) = 0
           OR (p.poll_state = ? AND COALESCE(p.next_poll_at, 0) <= ?))
` + ordinaryIdle + `
    ORDER BY sort_updated, sort_next, sort_activity, s.updated_at, s.id
    LIMIT ?
), ordinary AS (
    SELECT s.json, s.id, s.teams_chat_id AS chat_id, 2 AS lane,
           COALESCE(p.updated_at, 0) AS sort_updated,
           COALESCE(p.next_poll_at, 0) AS sort_next,
           COALESCE(p.last_activity_at, 0) AS sort_activity
    FROM sessions s
    LEFT JOIN chat_polls p ON p.chat_id = s.teams_chat_id
    WHERE COALESCE(s.teams_chat_id, '') != ''
      AND (? = '' OR s.teams_chat_id != ?)
      AND ` + validSession + `
      AND ` + activeSession + `
      AND (
        p.chat_id IS NULL
        OR (
          ` + validPoll + `
          AND NOT ` + frontier + `
          AND ` + pollFailureCount + ` = 0
          AND COALESCE(p.next_poll_at, 0) <= ?
          AND COALESCE(p.blocked_until, 0) <= ?
          AND (COALESCE(p.parked_skip_eligible, 0) = 0
               OR (p.poll_state = ? AND COALESCE(p.next_poll_at, 0) <= ?))
        )
      )
` + ordinaryIdle + `
    ORDER BY sort_updated, sort_next, sort_activity, s.updated_at, s.id
    LIMIT ?
), malformed AS (
    SELECT s.json, s.id, s.teams_chat_id AS chat_id, 1 AS lane,
           COALESCE(p.updated_at, 0) AS sort_updated,
           COALESCE(p.next_poll_at, 0) AS sort_next,
           COALESCE(p.last_activity_at, 0) AS sort_activity
    FROM sessions s
    JOIN chat_polls p ON p.chat_id = s.teams_chat_id
    WHERE COALESCE(s.teams_chat_id, '') != ''
      AND (? = '' OR s.teams_chat_id != ?)
      AND ` + validSession + `
      AND ` + activeSession + `
      AND ` + malformedPoll + `
    ORDER BY sort_updated, sort_next, sort_activity, s.updated_at, s.id
    LIMIT ?
), operational AS (
    SELECT s.json, s.id, s.teams_chat_id AS chat_id, 3 AS lane,
           COALESCE(p.updated_at, 0) AS sort_updated,
           COALESCE(p.next_poll_at, 0) AS sort_next,
           COALESCE(p.last_activity_at, 0) AS sort_activity
    FROM sessions s
    LEFT JOIN chat_polls p ON p.chat_id = s.teams_chat_id
    WHERE COALESCE(s.teams_chat_id, '') != ''
      AND (? = '' OR s.teams_chat_id != ?)
      AND ` + validSession + `
      AND ` + activeSession + `
      AND p.chat_id IS NOT NULL
      AND ((` + validPoll + `
        AND ` + frontier + `
        AND ((` + pendingPage + ` = 1 AND ` + pendingPageGraphReplay + ` = 0)
             OR (COALESCE(p.next_poll_at, 0) <= ?
                 AND COALESCE(p.blocked_until, 0) <= ?))))
` + operationalIdle + `
    ORDER BY sort_updated, sort_next, sort_activity, s.updated_at, s.id
    LIMIT ?
), admitted AS (
    SELECT * FROM control
    UNION ALL SELECT * FROM retry
    UNION ALL SELECT * FROM malformed
    UNION ALL SELECT * FROM ordinary
    UNION ALL SELECT * FROM operational
), limited AS (
    SELECT * FROM admitted
    ORDER BY lane, sort_updated, sort_next, sort_activity, id
    LIMIT ?
)
SELECT id, json FROM limited
WHERE chat_id != ?
ORDER BY lane, sort_updated, sort_next, sort_activity, id`
	rows, err := db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []SessionContext
	for rows.Next() {
		var sessionID string
		var raw []byte
		if err := rows.Scan(&sessionID, &raw); err != nil {
			return nil, err
		}
		var session SessionContext
		if !jsonValueHasNoDuplicateKeys(raw) {
			// Do not let encoding/json's last-key-wins behavior disagree with
			// SQLite JSON1's first-key lookup for a selected session. The raw row
			// remains available to the compatibility/repair path.
			continue
		}
		if err := json.Unmarshal(raw, &session); err != nil {
			continue
		}
		if strings.TrimSpace(session.ID) == "" || strings.TrimSpace(session.ID) != strings.TrimSpace(sessionID) || strings.TrimSpace(session.TeamsChatID) == "" {
			continue
		}
		out = append(out, session)
	}
	return out, rows.Err()
}

func loadSQLiteIdleWorkChatParkCandidates(ctx context.Context, db *sql.DB, controlChatID string, idleBefore time.Time, limit int) ([]IdleWorkChatParkCandidate, error) {
	controlChatID = strings.TrimSpace(controlChatID)
	if idleBefore.IsZero() || limit <= 0 {
		return nil, nil
	}
	validSession := sqliteSessionCanonicalValidJSONSQL("s.json", "s.id")
	validPoll := sqliteChatPollValidJSONSQL("p.json", "p.chat_id")
	canonicalSessionChat := sqliteCanonicalTextProjectionSQL("s.json", "$.teams_chat_id", "s.teams_chat_id")
	canonicalSessionStatus := sqliteCanonicalTextProjectionSQL("s.json", "$.status", "s.status")
	canonicalSessionUpdated := sqliteCanonicalTimeProjectionSQL("s.json", "$.updated_at", "s.updated_at")
	canonicalPollActivity := sqliteCanonicalTimeProjectionSQL("p.json", "$.last_activity_at", "p.last_activity_at")
	canonicalPollBlocked := sqliteCanonicalTimeProjectionSQL("p.json", "$.blocked_until", "p.blocked_until")
	canonicalPollState := sqliteCanonicalTextProjectionSQL("p.json", "$.state", "p.poll_state")
	canonicalPollParked := sqliteCanonicalParkedSkipProjectionSQL("p.json", "p.parked_skip_eligible", "p.poll_state")
	canonicalTurnStatus := sqliteTurnSafetyStatusSQL("t.json", "t.status")
	rows, err := db.QueryContext(ctx, `SELECT s.json, p.json
FROM chat_polls p
JOIN sessions s ON `+canonicalSessionChat+` = p.chat_id
WHERE `+canonicalPollActivity+` > 0
  AND `+canonicalPollActivity+` <= ?
  AND `+canonicalSessionUpdated+` <= ?
  AND (`+canonicalSessionStatus+` IS NULL OR `+canonicalSessionStatus+` = '' OR `+canonicalSessionStatus+` = ?)
  AND `+canonicalSessionChat+` != ''
  AND (? = '' OR `+canonicalSessionChat+` != ?)
  AND `+validSession+`
  AND `+validPoll+`
  AND `+canonicalPollBlocked+` <= ?
  AND `+canonicalPollParked+` = 0
  AND `+canonicalPollState+` IN (?, ?)
  AND NOT EXISTS (
    SELECT 1 FROM turns t
    WHERE t.session_id = s.id
      AND `+sqliteTurnActiveStatusSQL(canonicalTurnStatus)+`
  )
ORDER BY `+canonicalPollActivity+` ASC, `+canonicalSessionUpdated+` ASC, s.id
LIMIT ?`, append([]any{sqliteTime(idleBefore), sqliteTime(idleBefore), string(SessionStatusActive), controlChatID, controlChatID, sqliteTime(time.Now()), chatPollStateCold, chatPollStateParked}, append(sqliteTurnActiveStatusArgs(), limit)...)...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []IdleWorkChatParkCandidate
	for rows.Next() {
		var sessionRaw []byte
		var pollRaw []byte
		if err := rows.Scan(&sessionRaw, &pollRaw); err != nil {
			return nil, err
		}
		var candidate IdleWorkChatParkCandidate
		if !jsonValueHasNoDuplicateKeys(sessionRaw) || json.Unmarshal(sessionRaw, &candidate.Session) != nil {
			// A malformed session is local scheduler state.  Do not let it abort
			// auto-park discovery for every other chat; the SQL identity remains
			// held out by the admission query and the next repair/startup pass can
			// report it independently.
			continue
		}
		if !jsonValueHasNoDuplicateKeys(pollRaw) || json.Unmarshal(pollRaw, &candidate.Poll) != nil {
			continue
		}
		if strings.TrimSpace(candidate.Session.ID) == "" || strings.TrimSpace(candidate.Poll.ChatID) == "" || strings.TrimSpace(candidate.Session.TeamsChatID) != strings.TrimSpace(candidate.Poll.ChatID) {
			continue
		}
		annotateUnknownLoadedSession(&candidate.Session)
		out = append(out, candidate)
	}
	return out, rows.Err()
}

func loadSQLiteColdState(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (State, error) {
	return loadSQLiteColdStateWithChatSequences(ctx, q, true)
}

func loadSQLiteColdStateWithoutChatSequences(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (State, error) {
	return loadSQLiteColdStateWithChatSequences(ctx, q, false)
}

func loadSQLiteColdStateWithChatSequences(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, includeChatSequences bool) (State, error) {
	var raw []byte
	if err := q.QueryRowContext(ctx, `SELECT value FROM state_meta WHERE key = 'state_json'`).Scan(&raw); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return State{}, errors.New("sqlite teams store is missing state metadata")
		}
		return State{}, err
	}
	if len(raw) == 0 {
		return State{}, errors.New("sqlite teams store has empty state metadata")
	}
	state, err := loadStateData(raw)
	if err != nil {
		return State{}, err
	}
	state.ensure(time.Time{})
	if err := overlaySQLiteHistoryWatchProjection(ctx, q, &state); err != nil {
		return State{}, err
	}
	state.ChatSequences = map[string]ChatSequenceState{}
	if includeChatSequences {
		if err := loadSQLiteJSONMap(ctx, q, `SELECT json FROM chat_sequences`, state.ChatSequences, func(v ChatSequenceState) string { return v.ChatID }); err != nil {
			return State{}, err
		}
	}
	return state, nil
}

func loadSQLiteHistoryWatchProjection(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}) (map[string]HistoryWatchCheckpoint, time.Time, int64, int64, bool, error) {
	if sqliteHistoryWatchProjectionLoadTestHook != nil {
		sqliteHistoryWatchProjectionLoadTestHook()
	}
	var raw []byte
	var stateJSONRevision int64
	// Read the projection and the epoch in one scoped query.  The epoch is
	// required for mixed-version safety, but a second state_meta round trip on
	// every HistoryWatch poll was a measurable cost in the SQLite hot path.
	if err := q.QueryRowContext(ctx, `
SELECT value,
       COALESCE((SELECT CAST(value AS INTEGER) FROM state_meta WHERE key = ?), 0)
FROM state_meta WHERE key = ?`, sqliteStateJSONRevisionKey, sqliteHistoryWatchProjectionKey).Scan(&raw, &stateJSONRevision); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, time.Time{}, 0, 0, false, nil
		}
		return nil, time.Time{}, 0, 0, false, err
	}
	var projection sqliteHistoryWatchProjection
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &projection); err != nil {
			// The projection is a rebuildable cache of the canonical state_json
			// row. A torn/manual write here must not make the entire SQLite store
			// unreadable; return "not found" so callers fall back to state_json
			// and can rematerialize a clean projection on the next update.
			return nil, time.Time{}, 0, 0, false, nil
		}
	}
	if projection.HistoryWatch == nil {
		projection.HistoryWatch = make(map[string]HistoryWatchCheckpoint)
	}
	return projection.HistoryWatch, projection.HistoryWatchReady, projection.StateJSONRevision, stateJSONRevision, true, nil
}

func sqliteStateJSONRevision(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}) (int64, error) {
	var revision int64
	if err := q.QueryRowContext(ctx, `SELECT CAST(value AS INTEGER) FROM state_meta WHERE key = ?`, sqliteStateJSONRevisionKey).Scan(&revision); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return 0, nil
		}
		return 0, err
	}
	if revision < 0 {
		return 0, fmt.Errorf("invalid sqlite state_json revision %d", revision)
	}
	return revision, nil
}

func overlaySQLiteHistoryWatchProjection(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}, state *State) error {
	history, ready, projectionRevision, stateJSONRevision, found, err := loadSQLiteHistoryWatchProjection(ctx, q)
	if err != nil {
		return err
	}
	if !found {
		return nil
	}
	// A projection written before the epoch existed is treated as legacy. If a
	// full-state writer has since touched state_json, the revision differs and
	// the cold JSON is authoritative until the current helper rematerializes the
	// projection. This is deliberately fail-closed for mixed-version stores.
	if projectionRevision <= 0 || stateJSONRevision <= 0 || projectionRevision != stateJSONRevision {
		return nil
	}
	state.HistoryWatch = history
	state.HistoryWatchReady = ready
	return nil
}

func loadSQLiteJSONMap[T any](ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, query string, out map[string]T, key func(T) string, args ...any) error {
	rows, err := q.QueryContext(ctx, query, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var raw []byte
		if err := rows.Scan(&raw); err != nil {
			return err
		}
		var value T
		if err := json.Unmarshal(raw, &value); err != nil {
			return err
		}
		out[key(value)] = value
	}
	return rows.Err()
}

// loadSQLiteJSONMapBestEffort is used only for chat-local admission
// projections. A malformed row is held out of the current selection, while
// other rows remain available to the listener. Strict loading remains the
// default for execution, delivery, and ownership records where silently
// omitting a row could change work semantics.
func loadSQLiteJSONMapBestEffort[T any](ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, query string, out map[string]T, key func(T) string, args ...any) error {
	rows, err := q.QueryContext(ctx, query, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var raw []byte
		if err := rows.Scan(&raw); err != nil {
			return err
		}
		var value T
		if err := json.Unmarshal(raw, &value); err != nil {
			continue
		}
		if strings.TrimSpace(key(value)) == "" {
			continue
		}
		out[key(value)] = value
	}
	return rows.Err()
}

// Outbox JSON is an independently persisted delivery record. A single
// truncated/corrupt row must be held out of a hot snapshot so healthy rows can
// continue, while full-state writes preserve the raw row as opaque evidence.
// The indexed compatibility columns are selected together with JSON so legacy
// rows are hydrated consistently in every typed snapshot.
func loadSQLiteOutboxMap(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, query string, out map[string]OutboxMessage, key func(OutboxMessage) string, args ...any) error {
	rows, err := q.QueryContext(ctx, query, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var row sqliteOutboxProjectionRow
		if err := scanSQLiteOutboxProjectionRow(rows, &row); err != nil {
			return err
		}
		message, ok := decodeSQLiteOutboxProjection(row)
		if !ok || strings.TrimSpace(key(message)) == "" {
			continue
		}
		out[key(message)] = message
	}
	return rows.Err()
}

// loadSQLiteOutboxSessionMapNative is intentionally strict. A session-indexed
// query is safe only under the dedicated session projection marker, but a
// trigger may revoke that marker after the audit and a direct writer can still
// leave a contradictory row visible to an already-open reader. In either case
// a partial dedupe result is unsafe: the caller must discard it and run the
// canonical JSON oracle for the whole session.
func loadSQLiteOutboxSessionMapNative(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, out map[string]OutboxMessage, sessionID string) error {
	sessionID = strings.TrimSpace(sessionID)
	if sessionID == "" {
		return nil
	}
	decodedOutbox := make(map[string]OutboxMessage)
	rows, err := q.QueryContext(ctx, `SELECT `+sqliteOutboxProjectionSelect("o")+` FROM outbox_messages o WHERE o.session_id = ?`, sessionID)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var row sqliteOutboxProjectionRow
		if err := scanSQLiteOutboxProjectionRow(rows, &row); err != nil {
			return err
		}
		message, ok := decodeSQLiteOutboxProjection(row)
		if !ok || strings.TrimSpace(message.SessionID) != sessionID {
			return fmt.Errorf("%w: session-scoped outbox row %q is not canonical", ErrSQLiteOutboxProjectionUntrusted, strings.TrimSpace(row.id.String))
		}
		if strings.TrimSpace(message.ID) == "" {
			return fmt.Errorf("%w: session-scoped outbox row has no id", ErrSQLiteOutboxProjectionUntrusted)
		}
		decodedOutbox[message.ID] = message
	}
	if err := rows.Err(); err != nil {
		return err
	}
	for id, message := range decodedOutbox {
		out[id] = message
	}
	return nil
}

// loadSQLiteOutboxSessionMapCanonical is the fail-closed compatibility lane
// for a session-scoped dedupe snapshot. Unlike the bounded FIFO snapshot, a
// session dedupe read must not silently omit a row that the canonical JSON says
// belongs to this session: omission can make a later transcript delivery look
// new and cause a duplicate Teams message. The query therefore does not use a
// JSON1 field predicate at all; JSON1 keeps the first duplicate key while the
// Go decoder keeps the last. Every row is inspected by the canonical decoder,
// and a malformed row is rejected when any occurrence of its session_id can
// belong to the requested session.
func loadSQLiteOutboxSessionMapCanonical(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, out map[string]OutboxMessage, sessionID string) error {
	sessionID = strings.TrimSpace(sessionID)
	if sessionID == "" {
		return nil
	}
	lookupCtx, cancel := context.WithTimeout(ctx, sqliteOutboxCanonicalLookupMaxDuration)
	defer cancel()
	// Do not materialize an unbounded JSON blob during the exceptional
	// compatibility scan. A row outside the bounded envelope is not evidence
	// that it is unrelated to the requested session, so fail closed instead of
	// allowing a duplicate transcript delivery.
	jsonExpr := "CASE WHEN length(CAST(o.json AS BLOB)) <= ? THEN o.json ELSE NULL END"
	rows, err := q.QueryContext(lookupCtx, `SELECT `+sqliteOutboxProjectionSelectWithJSON("o.", jsonExpr)+`, length(CAST(o.json AS BLOB)) FROM outbox_messages o`, sqliteOutboxCanonicalLookupMaxJSONRowBytes)
	if err != nil {
		return err
	}
	defer rows.Close()
	decodedOutbox := make(map[string]OutboxMessage)
	var scannedRows int64
	var scannedJSONBytes int64
	for rows.Next() {
		var row sqliteOutboxProjectionRow
		var jsonBytes sql.NullInt64
		if err := scanSQLiteOutboxProjectionRow(rows, &row, &jsonBytes); err != nil {
			return err
		}
		scannedRows++
		if scannedRows > sqliteOutboxCanonicalLookupMaxRows {
			return fmt.Errorf("%w: canonical session lookup exceeded %d rows", ErrSQLiteOutboxProjectionUntrusted, sqliteOutboxCanonicalLookupMaxRows)
		}
		if !jsonBytes.Valid || jsonBytes.Int64 < 0 {
			return fmt.Errorf("%w: canonical session lookup encountered NULL JSON length", ErrSQLiteOutboxProjectionUntrusted)
		}
		if jsonBytes.Int64 > sqliteOutboxCanonicalLookupMaxJSONRowBytes {
			return fmt.Errorf("%w: canonical session lookup encountered %d-byte JSON row", ErrSQLiteOutboxProjectionUntrusted, jsonBytes.Int64)
		}
		if jsonBytes.Int64 > sqliteOutboxCanonicalLookupMaxJSONBytes-scannedJSONBytes {
			return fmt.Errorf("%w: canonical session lookup exceeded %d JSON bytes", ErrSQLiteOutboxProjectionUntrusted, sqliteOutboxCanonicalLookupMaxJSONBytes)
		}
		scannedJSONBytes += jsonBytes.Int64
		message, ok := decodeSQLiteOutboxProjection(row)
		if !ok {
			// A malformed row may have lost its identity or may contain duplicate
			// keys that disagree with the scalar projection. Without a complete
			// canonical decode there is no proof that it is unrelated to this
			// session; reject the entire snapshot rather than silently omitting it.
			return fmt.Errorf("%w: canonical session-scoped outbox row %q is not decodable", ErrSQLiteOutboxProjectionUntrusted, strings.TrimSpace(row.id.String))
		}
		if strings.TrimSpace(message.SessionID) != sessionID {
			continue
		}
		if strings.TrimSpace(message.ID) == "" {
			return fmt.Errorf("%w: canonical session-scoped outbox row has no id", ErrSQLiteOutboxProjectionUntrusted)
		}
		decodedOutbox[message.ID] = message
	}
	if err := lookupCtx.Err(); err != nil {
		return fmt.Errorf("%w: canonical session lookup stopped: %v", ErrSQLiteOutboxProjectionUntrusted, err)
	}
	if err := rows.Err(); err != nil {
		return err
	}
	for id, message := range decodedOutbox {
		out[id] = message
	}
	return nil
}

func loadSQLiteSessionMap(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, query string, out map[string]SessionContext, args ...any) error {
	rows, err := q.QueryContext(ctx, query, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var sqlID string
		var chatID, status sql.NullString
		// This compatibility timestamp is not used by the typed loader. Scan it
		// into an interface so a legacy TEXT/BLOB value cannot abort the whole
		// session snapshot before the canonical JSON has been inspected.
		var ignoredUpdatedAt any
		var raw []byte
		if err := rows.Scan(&sqlID, &chatID, &status, &ignoredUpdatedAt, &raw); err != nil {
			return err
		}
		var session SessionContext
		if err := json.Unmarshal(raw, &session); err != nil {
			// A corrupt session is held out of the scheduler. The SQL identity
			// is intentionally not promoted into a runnable SessionContext: it
			// does not prove a Codex thread or workspace binding.
			continue
		}
		if strings.TrimSpace(sqlID) == "" || strings.TrimSpace(session.ID) != strings.TrimSpace(sqlID) {
			continue
		}
		// The SQL chat binding is an indexed identity, not merely a sort
		// column.  Do not let a valid JSON payload from another chat become a
		// runnable session after a partial/cross-row repair.  Empty values are
		// retained for old non-Teams/session-only rows; hot admission already
		// requires a non-empty binding.
		if chatID.Valid && strings.TrimSpace(chatID.String) != "" &&
			strings.TrimSpace(session.TeamsChatID) != "" &&
			strings.TrimSpace(session.TeamsChatID) != strings.TrimSpace(chatID.String) {
			continue
		}
		// Preserve an explicit diagnostic even in the bounded hot projection.
		// The scheduler still holds unknown session statuses out of runnable
		// candidates; annotating here prevents the fast path from making the
		// row look like an ordinary inactive chat when it is later surfaced by
		// a diagnostic or repair snapshot.
		annotateUnknownLoadedSession(&session)
		out[session.ID] = session
	}
	return rows.Err()
}

func loadSQLiteTurnMap(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, query string, out map[string]Turn, holdMalformedActive bool, args ...any) error {
	rows, err := q.QueryContext(ctx, query, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var sqlID, sqlSessionID string
		var sqlStatus string
		var raw []byte
		if err := rows.Scan(&sqlID, &sqlSessionID, &sqlStatus, &raw); err != nil {
			return err
		}
		var turn Turn
		if jsonValueHasNoDuplicateKeys(raw) && json.Unmarshal(raw, &turn) == nil &&
			strings.TrimSpace(turn.ID) == strings.TrimSpace(sqlID) &&
			strings.TrimSpace(turn.SessionID) == strings.TrimSpace(sqlSessionID) {
			if holdMalformedActive && sqliteTurnStatusIsUnknown(TurnStatus(sqlStatus)) {
				// The canonical payload is readable, but an unknown indexed
				// status is still an unresolved mixed-version projection. Preserve
				// the indexed safety disposition instead of letting the payload's
				// terminal value release a possible owner.
				held := Turn{ID: sqlID, SessionID: sqlSessionID, Status: TurnStatus(sqlStatus)}
				normalizeLoadedTurnStatus(&held)
				out[sqlID] = held
				continue
			}
			normalizeLoadedTurnStatusWithIndexedFallback(&turn, TurnStatus(sqlStatus))
			out[turn.ID] = turn
			continue
		}
		if holdMalformedActive && sqliteTurnStatusIsSafetyActive(TurnStatus(sqlStatus)) &&
			strings.TrimSpace(sqlID) != "" && strings.TrimSpace(sqlSessionID) != "" {
			// Preserve the safety-relevant state from the indexed SQL columns
			// when the payload is malformed. This holds the affected chat from
			// starting a second execution without trusting any cursor/output
			// fields from the bad JSON.
			held := Turn{ID: sqlID, SessionID: sqlSessionID, Status: TurnStatus(sqlStatus)}
			normalizeLoadedTurnStatus(&held)
			out[sqlID] = held
		}
	}
	return rows.Err()
}

func sqliteTurnStatusIsSafetyActive(status TurnStatus) bool {
	trimmed := TurnStatus(strings.TrimSpace(string(status)))
	if trimmed == TurnStatusQueued || trimmed == TurnStatusRunning {
		return true
	}
	return sqliteTurnStatusIsUnknown(trimmed)
}

func sqliteTurnStatusIsUnknown(status TurnStatus) bool {
	trimmed := TurnStatus(strings.TrimSpace(string(status)))
	return strings.TrimSpace(string(trimmed)) != "" && !knownTurnStatus(trimmed)
}

// sqliteCanonicalTurnStatusSQL makes the JSON turn status authoritative when
// it is present.  The scalar column is a compatibility fallback for rows
// written before the status field was added, but it must not hide a live turn
// after a mixed-version/partial write.  An invalid present JSON type is a
// conservative unresolved value: active-status predicates retain the row as a
// safety fence, while queued-only predicates will not claim it.
func sqliteCanonicalTurnStatusSQL(jsonColumn, legacyColumn string) string {
	typeExpr := sqliteSafeJSONType(jsonColumn, "$.status")
	valueExpr := sqliteSafeJSONExtract(jsonColumn, "$.status")
	return "(CASE WHEN " + typeExpr + " = 'text' AND trim(COALESCE(" + valueExpr + ", '')) <> '' THEN trim(COALESCE(" + valueExpr + ", ''))" +
		" WHEN " + typeExpr + " IS NULL OR " + typeExpr + " = 'null' OR (" + typeExpr + " = 'text' AND trim(COALESCE(" + valueExpr + ", '')) = '') THEN trim(COALESCE(" + legacyColumn + ", ''))" +
		" ELSE '__invalid__' END)"
}

// sqliteTurnUnknownStatusSQL identifies a non-empty indexed status that the
// current decoder does not know.  A mixed-version/partial write can leave a
// terminal JSON status beside such a scalar projection; treating that row as
// terminal would be an unsafe claim that no execution is still in flight.
func sqliteTurnUnknownStatusSQL(column string) string {
	return "(" + column + " <> '' AND " + column + " NOT IN ('queued', 'running', 'completed', 'failed', 'interrupted'))"
}

// sqliteTurnSafetyStatusSQL preserves the canonical JSON status for normal
// rows, but exposes an unknown non-empty compatibility status to the callers
// that must fail closed.  This is intentionally not used by queued-only
// admission: unknown rows may fence work, but they must never become claimable
// merely because their JSON projection is stale.
func sqliteTurnSafetyStatusSQL(jsonColumn, legacyColumn string) string {
	canonical := sqliteCanonicalTurnStatusSQL(jsonColumn, legacyColumn)
	return "(CASE WHEN " + sqliteTurnUnknownStatusSQL(legacyColumn) + " THEN trim(COALESCE(" + legacyColumn + ", '')) ELSE " + canonical + " END)"
}

func sqliteTurnActiveSafetyStatusSQL(jsonColumn, legacyColumn string) string {
	return sqliteTurnActiveStatusSQL(sqliteTurnSafetyStatusSQL(jsonColumn, legacyColumn))
}

func sqliteTurnActiveStatusSQL(column string) string {
	return "(" + column + " IN (?, ?) OR (" + column + " <> '' AND " + column + " NOT IN (?, ?, ?)))"
}

func sqliteTurnActiveStatusArgs() []any {
	return []any{string(TurnStatusQueued), string(TurnStatusRunning), string(TurnStatusCompleted), string(TurnStatusFailed), string(TurnStatusInterrupted)}
}

func sqliteTurnUnresolvedStatusSQL(column string) string {
	return "(" + column + " IN (?, ?) OR (" + column + " <> '' AND " + column + " NOT IN (?, ?, ?, ?)))"
}

func sqliteTurnUnresolvedStatusArgs() []any {
	return []any{string(TurnStatusRunning), string(TurnStatusInterrupted), string(TurnStatusQueued), string(TurnStatusCompleted), string(TurnStatusFailed), string(TurnStatusInterrupted)}
}

// decodeSQLiteTurnExecutionMetadata validates only the small ownership
// surface needed by the linked-transcript probes. The SQL status/session
// columns are the indexed row identity; the JSON payload must agree when it
// supplies those fields. A malformed or contradictory payload is not an
// infrastructure failure, but it is not safe evidence that an interrupted
// execution has finished either.
func decodeSQLiteTurnExecutionMetadata(raw []byte, indexedSessionID string, indexedStatus TurnStatus) (struct {
	SessionID      string     `json:"session_id"`
	Status         TurnStatus `json:"status"`
	RecoveryReason string     `json:"recovery_reason"`
}, bool) {
	var meta struct {
		SessionID      string     `json:"session_id"`
		Status         TurnStatus `json:"status"`
		RecoveryReason string     `json:"recovery_reason"`
	}
	if err := json.Unmarshal(raw, &meta); err != nil {
		return meta, false
	}
	if strings.TrimSpace(indexedSessionID) == "" || meta.Status != indexedStatus {
		return meta, false
	}
	if embeddedSessionID := strings.TrimSpace(meta.SessionID); embeddedSessionID != "" && embeddedSessionID != strings.TrimSpace(indexedSessionID) {
		return meta, false
	}
	return meta, true
}

func loadSQLiteChatPollMap(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, query string, out map[string]ChatPollState, args ...any) error {
	rows, err := q.QueryContext(ctx, query, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var sqlChatID string
		var raw []byte
		if err := rows.Scan(&sqlChatID, &raw); err != nil {
			return err
		}
		if strings.TrimSpace(sqlChatID) == "" {
			continue
		}
		poll, ok := decodeChatPollState(sqlChatID, raw)
		if !ok {
			continue
		}
		out[sqlChatID] = poll
	}
	return rows.Err()
}

// loadSQLiteChatPollMapBestEffort is used by bounded hot admission.  The SQL
// identity is authoritative for a malformed poll row: turning it into a
// recovery placeholder prevents a missing typed projection from becoming a
// baseline-only first observation that silently consumes the current Graph
// head.  Other rows remain independently usable.
func loadSQLiteChatPollMapBestEffort(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, query string, out map[string]ChatPollState, args ...any) error {
	rows, err := q.QueryContext(ctx, query, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var sqlChatID string
		var raw []byte
		if err := rows.Scan(&sqlChatID, &raw); err != nil {
			return err
		}
		poll, ok := decodeChatPollStateForAdmission(sqlChatID, raw)
		if !ok {
			continue
		}
		out[strings.TrimSpace(sqlChatID)] = poll
	}
	return rows.Err()
}

// mergeSQLiteChatPollProjection overlays the small indexed schedule columns
// on a recovery placeholder without touching its raw JSON.  An opaque poll
// row cannot safely be rewritten by a normal retry/error callback, but its
// scalar projection is still a durable, chat-local place to keep a retry
// deadline.  Reading the projection back here prevents a restart from
// forgetting that gate and immediately re-probing the same broken row.
func mergeSQLiteChatPollProjection(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}, chatID string, poll *ChatPollState) error {
	if poll == nil || strings.TrimSpace(chatID) == "" {
		return nil
	}
	var recoveryRequired, nextPollAt, blockedUntil, lastActivityAt, updatedAt sql.NullInt64
	var pollState sql.NullString
	err := q.QueryRowContext(ctx, `SELECT `+
		sqliteStoredInt64SQL("recovery_required")+`, `+
		sqliteStoredInt64SQL("next_poll_at")+`, `+
		sqliteStoredInt64SQL("blocked_until")+`, poll_state, `+
		sqliteStoredInt64SQL("last_activity_at")+`, `+
		sqliteStoredInt64SQL("updated_at")+
		` FROM chat_polls WHERE chat_id = ?`, chatID).Scan(&recoveryRequired, &nextPollAt, &blockedUntil, &pollState, &lastActivityAt, &updatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return nil
	}
	if err != nil {
		return err
	}
	maxProjectionTime := func(current *time.Time, value sql.NullInt64) {
		if current == nil || !value.Valid || value.Int64 <= 0 {
			return
		}
		candidate := time.Unix(0, value.Int64).UTC()
		if candidate.After(*current) {
			*current = candidate
		}
	}
	maxProjectionTime(&poll.NextPollAt, nextPollAt)
	maxProjectionTime(&poll.BlockedUntil, blockedUntil)
	maxProjectionTime(&poll.LastActivityAt, lastActivityAt)
	maxProjectionTime(&poll.UpdatedAt, updatedAt)
	if pollState.Valid && strings.TrimSpace(pollState.String) != "" {
		// A blocked scalar state is the explicit durable signal written by an
		// opaque-row retry.  Do not replace a meaningful recovery state with an
		// empty/legacy value.
		poll.PollState = strings.TrimSpace(pollState.String)
	}
	if nullableInt64Value(recoveryRequired) != 0 {
		// This scalar bit is the only part of an opaque recovery disposition that
		// can be updated without rewriting the forensic JSON.  Preserve it across
		// restart; the reason/hash continue to come from the raw row when it can be
		// decoded, or remain available through the opaque-row audit path.
		poll.RecoveryRequired = true
	}
	return nil
}

// updateSQLiteOpaqueChatPollProjectionTx persists only compatibility/schedule
// columns for an opaque row.  The raw JSON comparison is an identity fence:
// if an explicit repair replaced the row before this callback reached the
// write, the old error must not modify the replacement frontier. Callers that
// explicitly invalidate a poll attempt pass clearAttempt=true; other opaque
// mutations preserve the unknown attempt sidecar rather than guessing.
func updateSQLiteOpaqueChatPollProjectionTx(ctx context.Context, tx *sql.Tx, chatID string, raw []byte, poll ChatPollState, clearAttempt bool) error {
	query := `UPDATE chat_polls
SET recovery_required = ?, next_poll_at = ?, blocked_until = ?, poll_state = ?, last_activity_at = ?,
    park_notice_sent_at = ?, parked_skip_eligible = ?, frontier_active = ?,
    admission_valid = 0, attempt_active = CASE WHEN ? != 0 THEN 0 ELSE attempt_active END, updated_at = ?`
	args := []any{
		sqliteBool(poll.RecoveryRequired), sqliteTime(poll.NextPollAt), sqliteTime(poll.BlockedUntil), poll.PollState,
		sqliteTime(poll.LastActivityAt), sqliteTime(poll.ParkNoticeSentAt),
		sqliteBool(chatPollParkedSkipEligible(poll)), sqliteBool(chatPollHasOperationalFrontier(poll)),
		sqliteBool(clearAttempt), sqliteTime(poll.UpdatedAt), strings.TrimSpace(chatID),
	}
	if len(raw) == 0 {
		// database/sql may scan a zero-length BLOB as a nil []byte. Binding that
		// value would compare against SQL NULL and miss the actual zeroblob(0)
		// evidence, so use SQLite's type/length identity for this one case. A
		// NULL JSON column remains unmatched and fails closed as a revision race.
		query += ` WHERE chat_id = ? AND typeof(json) = 'blob' AND length(json) = 0`
	} else {
		query += ` WHERE chat_id = ? AND json = ?`
		args = append(args, raw)
	}
	result, err := tx.ExecContext(ctx, query, args...)
	if err != nil {
		return err
	}
	rows, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if rows != 1 {
		return ErrChatPollRevisionChanged
	}
	return nil
}

func loadSQLiteRegisteredSessionIDs(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (map[string]struct{}, error) {
	rows, err := q.QueryContext(ctx, `SELECT id FROM sessions`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	known := make(map[string]struct{})
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		if id = strings.TrimSpace(id); id != "" {
			known[id] = struct{}{}
		}
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return known, rows.Close()
}

// sqliteCheckpointDisposition describes the result of decoding a checkpoint
// row without conflating a corrupt row with an absent row.  Checkpoint rows
// are the one SQLite table whose JSON is untrusted input: older versions and
// interrupted manual repairs have left rows whose typed payload is not
// decodable even though the SQL identity columns are intact.
type sqliteCheckpointDisposition string

const (
	sqliteCheckpointValid              sqliteCheckpointDisposition = "valid"
	sqliteCheckpointMalformedCanonical sqliteCheckpointDisposition = "malformed-canonical"
	sqliteCheckpointIdentityConflict   sqliteCheckpointDisposition = "identity-conflict"
	sqliteCheckpointForeign            sqliteCheckpointDisposition = "foreign/noncanonical"
	sqliteCheckpointMissing            sqliteCheckpointDisposition = "missing"
	sqliteCheckpointProvenanceInvalid  sqliteCheckpointDisposition = "provenance-invalid"
	sqliteCheckpointInfrastructure     sqliteCheckpointDisposition = "infrastructure-error"
)

type sqliteCheckpointRow struct {
	ID        string
	IDValid   bool
	SessionID sql.NullString
	Status    sql.NullString
	UpdatedAt sql.NullInt64
	Raw       []byte
}

type sqliteCheckpointRowScanner interface {
	Scan(...any) error
}

// scanSQLiteCanonicalCheckpointFastRow is used only by the linked-transcript
// snapshot, whose query is restricted to non-NULL primary-key values.  The
// COALESCE expressions keep nullable legacy metadata fail-closed while letting
// the normal row path scan concrete Go values instead of allocating through
// sql.Null* conversions on every poll.  A zero/empty value remains invalid to
// the decoder; this is an allocation optimization, not a trust downgrade.
func scanSQLiteCanonicalCheckpointFastRow(scanner sqliteCheckpointRowScanner) (sqliteCheckpointRow, error) {
	var id string
	var sessionID string
	var status string
	var updatedAt int64
	var raw []byte
	if err := scanner.Scan(&id, &sessionID, &status, &updatedAt, &raw); err != nil {
		return sqliteCheckpointRow{}, err
	}
	return sqliteCheckpointRow{
		ID:        id,
		IDValid:   strings.TrimSpace(id) != "",
		SessionID: sql.NullString{String: sessionID, Valid: strings.TrimSpace(sessionID) != ""},
		Status:    sql.NullString{String: status, Valid: strings.TrimSpace(status) != ""},
		UpdatedAt: sql.NullInt64{Int64: updatedAt, Valid: updatedAt != 0},
		Raw:       raw,
	}, nil
}

// scanSQLiteCheckpointIdentityFastRow is the no-change linked-transcript read
// path.  The caller already selected canonical IDs and only needs the SQL
// identity plus payload to validate a normal checkpoint.  Status and
// updated_at are needed only when preserving/repairing an opaque row, so the
// full nullable row decoder remains available for those paths without adding
// two extra driver conversions to every idle poll.
func scanSQLiteCheckpointIdentityFastRow(scanner sqliteCheckpointRowScanner) (sqliteCheckpointRow, error) {
	var id string
	var sessionID string
	var raw []byte
	if err := scanner.Scan(&id, &sessionID, &raw); err != nil {
		return sqliteCheckpointRow{}, err
	}
	return sqliteCheckpointRow{
		ID:        id,
		IDValid:   strings.TrimSpace(id) != "",
		SessionID: sql.NullString{String: sessionID, Valid: strings.TrimSpace(sessionID) != ""},
		Raw:       raw,
	}, nil
}

func scanSQLiteCheckpointRow(scanner sqliteCheckpointRowScanner) (sqliteCheckpointRow, error) {
	var id sql.NullString
	var row sqliteCheckpointRow
	if err := scanner.Scan(&id, &row.SessionID, &row.Status, &row.UpdatedAt, &row.Raw); err != nil {
		return sqliteCheckpointRow{}, err
	}
	row.ID = id.String
	row.IDValid = id.Valid
	return row, nil
}

// loadSQLiteCheckpointRow reads all SQL identity metadata with the raw JSON in
// one query.  Callers must use this instead of loadSQLiteJSONRow for
// ImportCheckpoint: a malformed checkpoint is still an addressable session
// local fence, not a missing row and not a reason to abort unrelated reads.
func loadSQLiteCheckpointRow(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}, query string, args ...any) (sqliteCheckpointRow, bool, error) {
	row, err := scanSQLiteCheckpointRow(q.QueryRowContext(ctx, query, args...))
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return sqliteCheckpointRow{}, false, nil
		}
		return sqliteCheckpointRow{}, false, err
	}
	return row, true, nil
}

func decodeSQLiteCheckpointRow(row sqliteCheckpointRow, requestedID string, requestedSessionID string, requireCanonical bool) (ImportCheckpoint, bool, sqliteCheckpointDisposition, error) {
	return decodeSQLiteCheckpointRowWithCanonicalIdentity(row, requestedID, requestedSessionID, requireCanonical, requireCanonical)
}

func decodeSQLiteCheckpointRowWithCanonicalIdentity(row sqliteCheckpointRow, requestedID string, requestedSessionID string, requireCanonical bool, enforceCanonicalIdentity bool) (ImportCheckpoint, bool, sqliteCheckpointDisposition, error) {
	requestedID = strings.TrimSpace(requestedID)
	requestedSessionID = strings.TrimSpace(requestedSessionID)
	rowID := strings.TrimSpace(row.ID)
	rowSessionID := strings.TrimSpace(row.SessionID.String)
	if requestedID == "" || !row.IDValid || rowID == "" || rowID != requestedID {
		return ImportCheckpoint{}, false, sqliteCheckpointIdentityConflict,
			fmt.Errorf("%w: checkpoint row id %q does not match requested %q", ErrSessionStateProvenanceMismatch, rowID, requestedID)
	}
	if requestedSessionID != "" && rowSessionID != "" && requestedSessionID != rowSessionID {
		return ImportCheckpoint{}, false, sqliteCheckpointIdentityConflict,
			fmt.Errorf("%w: checkpoint %q SQL session %q does not match requested %q", ErrSessionStateProvenanceMismatch, requestedID, rowSessionID, requestedSessionID)
	}
	if rowSessionID == "" {
		if requestedSessionID != "" {
			return ImportCheckpoint{}, false, sqliteCheckpointIdentityConflict,
				fmt.Errorf("%w: checkpoint %q has no SQL session identity", ErrSessionStateProvenanceMismatch, requestedID)
		}
		return ImportCheckpoint{}, false, sqliteCheckpointIdentityConflict,
			fmt.Errorf("%w: checkpoint %q has no SQL session identity", ErrSessionStateProvenanceMismatch, requestedID)
	}
	if requestedSessionID == "" {
		requestedSessionID = rowSessionID
	}
	canonicalSessionID, canonical := canonicalCheckpointSessionID(requestedID)
	if enforceCanonicalIdentity && canonical && canonicalSessionID != rowSessionID {
		// A canonical transcript:<session> key cannot be reinterpreted as an
		// operation-specific row merely because its SQL and JSON payload agree
		// with a different session.  This check is enabled when the caller has
		// independently established that the suffix names a registered session;
		// older stores also contain operation-local IDs in the transcript:*
		// namespace whose suffix is not a session ID.
		return ImportCheckpoint{}, false, sqliteCheckpointIdentityConflict,
			fmt.Errorf("%w: canonical checkpoint %q SQL session %q does not match key session %q", ErrSessionStateProvenanceMismatch, requestedID, rowSessionID, canonicalSessionID)
	}
	if requireCanonical && (!canonical || canonicalSessionID != rowSessionID || canonicalSessionID != requestedSessionID) {
		return ImportCheckpoint{}, false, sqliteCheckpointForeign,
			fmt.Errorf("%w: checkpoint %q is not the canonical row for session %q", ErrSessionStateProvenanceMismatch, requestedID, requestedSessionID)
	}

	var checkpoint ImportCheckpoint
	trimmed := bytes.TrimSpace(row.Raw)
	unmarshalErr := json.Unmarshal(row.Raw, &checkpoint)
	if len(trimmed) == 0 || bytes.Equal(trimmed, []byte("null")) {
		unmarshalErr = fmt.Errorf("JSON is null or empty")
	}
	if unmarshalErr == nil {
		// SQL identity and any non-empty embedded JSON identity must agree before
		// an optional-proof downgrade is considered. A valid JSON object carrying
		// another checkpoint/session remains a hard provenance error. An object
		// with no identity at all (or only one half of it) is just as opaque as an
		// empty/null payload, but a canonical SQL row can still provide a safe,
		// session-local fence for it.
		embeddedID := strings.TrimSpace(checkpoint.ID)
		embeddedSessionID := strings.TrimSpace(checkpoint.SessionID)
		if (embeddedID != "" && embeddedID != requestedID) ||
			(embeddedSessionID != "" && embeddedSessionID != requestedSessionID) {
			return ImportCheckpoint{}, false, sqliteCheckpointIdentityConflict,
				fmt.Errorf("%w: checkpoint %q embedded identity is id=%q session=%q", ErrSessionStateProvenanceMismatch, requestedID, checkpoint.ID, checkpoint.SessionID)
		}
		if embeddedID == "" || embeddedSessionID == "" {
			if canonical && canonicalSessionID == rowSessionID {
				return opaqueCanonicalImportCheckpointFromRow(row, requestedID, rowSessionID, invalidCanonicalCheckpointKind), true, sqliteCheckpointIdentityConflict, nil
			}
			return ImportCheckpoint{}, false, sqliteCheckpointIdentityConflict,
				fmt.Errorf("%w: checkpoint %q has incomplete embedded identity id=%q session=%q", ErrSessionStateProvenanceMismatch, requestedID, checkpoint.ID, checkpoint.SessionID)
		}
		if !importCheckpointOptionalProofUsable(checkpoint) {
			// The payload is readable and its identity is proven.  Preserve the
			// legacy fields for diagnosis and migration compatibility, but keep the
			// explicit marker that prevents automatic source use.  A later ordinary
			// write must still retain the raw row; the caller receives the
			// provenance-invalid disposition for that purpose.
			checkpoint.RecoveryProofUnusable = true
			return checkpoint, true, sqliteCheckpointProvenanceInvalid, nil
		}
		if err := validateImportCheckpointProvenance(checkpoint, requestedSessionID, requestedID); err != nil {
			// SQL id/session columns are the only trusted identity for an opaque
			// canonical row.  Do not return a partially decoded JSON value: it may
			// contain a foreign cursor, path, or execution owner.  Keep the row
			// addressable as a deterministic session-local fence instead.
			return ImportCheckpoint{}, false, sqliteCheckpointProvenanceInvalid, err
		}
		return checkpoint, true, sqliteCheckpointValid, nil
	} else {
		// A malformed row is recoverable as a deterministic fence only when
		// the SQL identity itself proves that it is the canonical per-session
		// checkpoint.  General readers also need this fallback: passing
		// requireCanonical=false means valid non-canonical operation rows are
		// allowed, not that an opaque canonical row should become an error.
		if !canonical || canonicalSessionID != rowSessionID {
			return ImportCheckpoint{}, false, sqliteCheckpointMalformedCanonical,
				fmt.Errorf("malformed non-canonical import checkpoint %q: JSON cannot be decoded", requestedID)
		}
		// A canonical row with trusted SQL identity is retained as an explicit
		// unresolved fallback. The raw payload is never written back by this
		// decoder; ordinary reads must not repair or erase evidence.
		return opaqueCanonicalImportCheckpointFromRow(row, requestedID, rowSessionID, malformedCanonicalCheckpointKind), true, sqliteCheckpointMalformedCanonical, nil
	}
}

func loadSQLiteCheckpointMap(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, query string, out map[string]ImportCheckpoint, args ...any) error {
	return loadSQLiteCheckpointMapWithCanonicalSessions(ctx, q, query, out, nil, args...)
}

func loadSQLiteCheckpointMapWithCanonicalSessions(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, query string, out map[string]ImportCheckpoint, canonicalSessionIDs map[string]struct{}, args ...any) error {
	rows, err := q.QueryContext(ctx, query, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	canonicalCandidates := make(map[string]struct{})
	for rows.Next() {
		row, err := scanSQLiteCheckpointRow(rows)
		if err != nil {
			return err
		}
		enforceCanonicalIdentity := false
		requestedSessionID := row.SessionID.String
		if canonicalSessionID, canonical := canonicalCheckpointSessionID(row.ID); canonical {
			if canonicalSessionIDs != nil {
				_, enforceCanonicalIdentity = canonicalSessionIDs[canonicalSessionID]
				if enforceCanonicalIdentity {
					// The primary key of transcript:<session> is the canonical
					// session identity. session_id is a derived compatibility
					// column and may be stale after an interrupted projection
					// update. Decode against the key-derived identity, while
					// still validating any embedded JSON identity below. This
					// recovers a safe canonical checkpoint without trusting a
					// contradictory scalar owner.
					requestedSessionID = canonicalSessionID
					row.SessionID = sql.NullString{String: canonicalSessionID, Valid: true}
				}
			} else if canonicalSessionID != strings.TrimSpace(row.SessionID.String) {
				canonicalCandidates[row.ID] = struct{}{}
			}
		}
		checkpoint, found, disposition, err := decodeSQLiteCheckpointRowWithCanonicalIdentity(row, row.ID, requestedSessionID, false, enforceCanonicalIdentity)
		if err != nil {
			if sqliteCheckpointDispositionIsRowLocal(disposition) {
				// A malformed/foreign operation row cannot be safely represented in
				// the typed map, but it must not make unrelated sessions unreadable.
				continue
			}
			return err
		}
		if found {
			out[checkpoint.ID] = checkpoint
		}
	}
	if err := rows.Err(); err != nil {
		return err
	}
	if len(canonicalCandidates) == 0 || canonicalSessionIDs != nil {
		return rows.Close()
	}
	registered, err := loadSQLiteRegisteredSessionIDs(ctx, q)
	if err != nil {
		return err
	}
	for id := range canonicalCandidates {
		canonicalSessionID, canonical := canonicalCheckpointSessionID(id)
		if canonical {
			if _, known := registered[canonicalSessionID]; known {
				delete(out, id)
			}
		}
	}
	return rows.Close()
}

func sqliteCheckpointDispositionIsRowLocal(disposition sqliteCheckpointDisposition) bool {
	switch disposition {
	case sqliteCheckpointMalformedCanonical, sqliteCheckpointIdentityConflict, sqliteCheckpointForeign, sqliteCheckpointProvenanceInvalid:
		return true
	default:
		return false
	}
}

func loadSQLiteCheckpointForID(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}, query string, args ...any) (ImportCheckpoint, bool, error) {
	checkpoint, found, _, err := loadSQLiteCheckpointForIDWithDisposition(ctx, q, query, args...)
	return checkpoint, found, err
}

func loadSQLiteCheckpointForIDWithDisposition(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}, query string, args ...any) (ImportCheckpoint, bool, sqliteCheckpointDisposition, error) {
	row, found, err := loadSQLiteCheckpointRow(ctx, q, query, args...)
	if err != nil || !found {
		return ImportCheckpoint{}, found, sqliteCheckpointMissing, err
	}
	// This is an unscoped point read.  The SQL session_id column is not a
	// caller-supplied identity; treating it as one would turn a stale derived
	// value into a false provenance conflict before the canonical key fallback
	// gets a chance to repair the read view.
	effectiveSessionID, enforceCanonicalIdentity, err := normalizeSQLiteCanonicalCheckpointRowIdentity(ctx, q, &row, "")
	if err != nil {
		return ImportCheckpoint{}, false, sqliteCheckpointInfrastructure, err
	}
	return decodeSQLiteCheckpointRowWithCanonicalIdentity(row, row.ID, effectiveSessionID, false, enforceCanonicalIdentity)
}

func sqliteCheckpointCanonicalIdentityIsRegistered(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}, id string) (bool, error) {
	sessionID, canonical := canonicalCheckpointSessionID(id)
	if !canonical {
		return false, nil
	}
	var one int
	err := q.QueryRowContext(ctx, `SELECT 1 FROM sessions WHERE id = ? LIMIT 1`, sessionID).Scan(&one)
	if errors.Is(err, sql.ErrNoRows) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	return one != 0, nil
}

func loadSQLiteSessionsByID(ctx context.Context, db *sql.DB, ids []string, out map[string]SessionContext) error {
	if len(ids) == 0 {
		return nil
	}
	placeholders := make([]string, len(ids))
	args := make([]any, len(ids))
	for i, id := range ids {
		placeholders[i] = "?"
		args[i] = id
	}
	query := `SELECT json FROM sessions WHERE id IN (` + strings.Join(placeholders, ",") + `)`
	return loadSQLiteJSONMap(ctx, db, query, out, func(v SessionContext) string { return v.ID }, args...)
}

// loadSQLiteForkPollingState is the scoped SQLite projection for the staged
// child poller.  fork_operations is an indexed, exceptional table; sessions
// and chat_polls are not.  Loading those two tables in full on every listener
// tick made one staged child impose the cost of the entire Teams state.  The
// operation row is the only discovery input, after which child session and
// poll rows are fetched by their durable identities in bounded batches.
func loadSQLiteForkPollingState(ctx context.Context, db *sql.DB) (State, error) {
	state := newState()
	rows, err := db.QueryContext(ctx, `SELECT id, json FROM fork_operations
WHERE phase IN (?, ?, ?)
ORDER BY updated_at, id`,
		string(ForkPhaseChildChatStaged),
		string(ForkPhaseHistoryPublishing),
		string(ForkPhaseHistoryVerified),
	)
	if err != nil {
		return State{}, err
	}
	var childSessionIDs []string
	childSessionsSeen := make(map[string]struct{})
	var childChatIDs []string
	childChatsSeen := make(map[string]struct{})
	for rows.Next() {
		var id string
		var raw []byte
		if err := rows.Scan(&id, &raw); err != nil {
			_ = rows.Close()
			return State{}, err
		}
		var operation ForkOperation
		if err := json.Unmarshal(raw, &operation); err != nil ||
			strings.TrimSpace(id) == "" || strings.TrimSpace(operation.ID) != strings.TrimSpace(id) {
			// A malformed fork operation is not a reason to materialize all
			// unrelated chats. It remains in SQLite for the normal explicit
			// repair/diagnostic path.
			continue
		}
		switch operation.Phase {
		case ForkPhaseChildChatStaged, ForkPhaseHistoryPublishing, ForkPhaseHistoryVerified:
		default:
			// The indexed phase is only an admission hint. The canonical JSON
			// phase must agree before a child becomes runnable.
			continue
		}
		state.ForkOperations[operation.ID] = operation
		if sessionID := strings.TrimSpace(operation.ChildSessionID); sessionID != "" {
			if _, seen := childSessionsSeen[sessionID]; !seen {
				childSessionsSeen[sessionID] = struct{}{}
				childSessionIDs = append(childSessionIDs, sessionID)
			}
		}
		if chatID := strings.TrimSpace(operation.ChildChatID); chatID != "" {
			if _, seen := childChatsSeen[chatID]; !seen {
				childChatsSeen[chatID] = struct{}{}
				childChatIDs = append(childChatIDs, chatID)
			}
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return State{}, err
	}
	if err := rows.Close(); err != nil {
		return State{}, err
	}

	const batchSize = 400
	for start := 0; start < len(childSessionIDs); start += batchSize {
		end := min(start+batchSize, len(childSessionIDs))
		placeholders := strings.TrimRight(strings.Repeat("?,", end-start), ",")
		args := make([]any, 0, end-start)
		for _, id := range childSessionIDs[start:end] {
			args = append(args, id)
		}
		if err := loadSQLiteSessionMap(ctx, db, `SELECT id, teams_chat_id, status, updated_at, json FROM sessions WHERE id IN (`+placeholders+`)`, state.Sessions, args...); err != nil {
			return State{}, err
		}
	}
	for _, session := range state.Sessions {
		if chatID := strings.TrimSpace(session.TeamsChatID); chatID != "" {
			if _, seen := childChatsSeen[chatID]; !seen {
				childChatsSeen[chatID] = struct{}{}
				childChatIDs = append(childChatIDs, chatID)
			}
		}
	}
	for start := 0; start < len(childChatIDs); start += batchSize {
		end := min(start+batchSize, len(childChatIDs))
		placeholders := strings.TrimRight(strings.Repeat("?,", end-start), ",")
		args := make([]any, 0, end-start)
		for _, id := range childChatIDs[start:end] {
			args = append(args, id)
		}
		if err := loadSQLiteChatPollMapBestEffort(ctx, db, `SELECT chat_id, json FROM chat_polls WHERE chat_id IN (`+placeholders+`)`, state.ChatPolls, args...); err != nil {
			return State{}, err
		}
	}
	return state, nil
}

func loadSQLiteJSONMapTx[T any](ctx context.Context, tx *sql.Tx, query string, args []any, out map[string]T, key func(T) string) error {
	rows, err := tx.QueryContext(ctx, query, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var raw []byte
		if err := rows.Scan(&raw); err != nil {
			return err
		}
		var value T
		if err := json.Unmarshal(raw, &value); err != nil {
			return err
		}
		out[key(value)] = value
	}
	return rows.Err()
}

func loadSQLiteOutboxMapTx(ctx context.Context, tx *sql.Tx, query string, args []any, out map[string]OutboxMessage, key func(OutboxMessage) string) error {
	return loadSQLiteOutboxMap(ctx, tx, query, out, key, args...)
}

// loadSQLiteOutboxForTurnTxWithNativeReady contains the common turn lookup.
// The caller supplies the complete capability proof so a production caller
// cannot accidentally treat a trusted marker without physical provenance as
// sufficient for the indexed path.
func loadSQLiteOutboxForTurnTxWithNativeReady(ctx context.Context, tx *sql.Tx, turnID string, out map[string]OutboxMessage, nativeReady bool) error {
	var query string
	var args []any
	if nativeReady {
		query = `SELECT ` + sqliteOutboxProjectionSelect("o") + ` FROM outbox_messages o WHERE o.turn_id = ? AND ` + sqliteOutboxProjectionValidSQL("o") + ` AND ` + sqliteOutboxTurnProjectionReadySQL("o")
		args = []any{turnID}
		rows, err := tx.QueryContext(ctx, query, args...)
		if err != nil {
			return err
		}
		defer rows.Close()
		turnID = strings.TrimSpace(turnID)
		decodedOutbox := make(map[string]OutboxMessage)
		for rows.Next() {
			var row sqliteOutboxProjectionRow
			if err := scanSQLiteOutboxProjectionRow(rows, &row); err != nil {
				return err
			}
			message, ok := decodeSQLiteOutboxProjection(row)
			if !ok || strings.TrimSpace(message.TurnID) != turnID || strings.TrimSpace(message.ID) == "" {
				return fmt.Errorf("%w: native turn-scoped outbox row %q is not canonical", ErrSQLiteOutboxProjectionUntrusted, strings.TrimSpace(row.id.String))
			}
			decodedOutbox[message.ID] = message
		}
		if err := rows.Err(); err != nil {
			return err
		}
		for id, message := range decodedOutbox {
			out[id] = message
		}
		return nil
	} else {
		// JSON1 keeps the first duplicate key while encoding/json keeps the
		// last. Do not use a JSON1 turn predicate in the fail-closed fallback:
		// a canonical row could otherwise be filtered out before the Go oracle
		// sees it. The untrusted path is exceptional; the trusted marker keeps
		// normal completion on the indexed query above.
		lookupCtx, cancel := context.WithTimeout(ctx, sqliteOutboxCanonicalLookupMaxDuration)
		defer cancel()
		jsonExpr := "CASE WHEN length(CAST(o.json AS BLOB)) <= ? THEN o.json ELSE NULL END"
		rows, err := tx.QueryContext(lookupCtx, `SELECT `+sqliteOutboxProjectionSelectWithJSON("o.", jsonExpr)+`, length(CAST(o.json AS BLOB)) FROM outbox_messages o`, sqliteOutboxCanonicalLookupMaxJSONRowBytes)
		if err != nil {
			return err
		}
		defer rows.Close()
		turnID = strings.TrimSpace(turnID)
		// The fallback is a canonical oracle, not a best-effort scan. Keep it
		// bounded because this function is called from durable completion and
		// anchor transactions; an oversized inherited outbox must defer rather
		// than monopolize the SQLite writer.
		var scannedRows int64
		var scannedJSONBytes int64
		decodedOutbox := make(map[string]OutboxMessage)
		for rows.Next() {
			var row sqliteOutboxProjectionRow
			var jsonBytes sql.NullInt64
			if err := scanSQLiteOutboxProjectionRow(rows, &row, &jsonBytes); err != nil {
				return err
			}
			scannedRows++
			if scannedRows > sqliteOutboxCanonicalLookupMaxRows {
				return fmt.Errorf("%w: canonical turn lookup exceeded %d rows", ErrSQLiteOutboxProjectionUntrusted, sqliteOutboxCanonicalLookupMaxRows)
			}
			if !jsonBytes.Valid || jsonBytes.Int64 < 0 {
				return fmt.Errorf("%w: canonical turn lookup encountered NULL JSON length", ErrSQLiteOutboxProjectionUntrusted)
			}
			if jsonBytes.Int64 > sqliteOutboxCanonicalLookupMaxJSONRowBytes {
				return fmt.Errorf("%w: canonical turn lookup encountered %d-byte JSON row", ErrSQLiteOutboxProjectionUntrusted, jsonBytes.Int64)
			}
			if jsonBytes.Int64 > sqliteOutboxCanonicalLookupMaxJSONBytes-scannedJSONBytes {
				return fmt.Errorf("%w: canonical turn lookup exceeded %d JSON bytes", ErrSQLiteOutboxProjectionUntrusted, sqliteOutboxCanonicalLookupMaxJSONBytes)
			}
			scannedJSONBytes += jsonBytes.Int64
			if err := lookupCtx.Err(); err != nil {
				return fmt.Errorf("%w: canonical turn lookup stopped: %v", ErrSQLiteOutboxProjectionUntrusted, err)
			}
			message, ok := decodeSQLiteOutboxProjection(row)
			if !ok {
				return fmt.Errorf("%w: canonical turn-scoped outbox row %q is not decodable", ErrSQLiteOutboxProjectionUntrusted, strings.TrimSpace(row.id.String))
			}
			if strings.TrimSpace(message.TurnID) == turnID {
				decodedOutbox[message.ID] = message
			}
		}
		if err := lookupCtx.Err(); err != nil {
			return fmt.Errorf("%w: canonical turn lookup stopped: %v", ErrSQLiteOutboxProjectionUntrusted, err)
		}
		if err := rows.Err(); err != nil {
			return err
		}
		for id, message := range decodedOutbox {
			out[id] = message
		}
		return nil
	}
}

func loadSQLiteJSONRow[T any](ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}, query string, args ...any) (T, bool, error) {
	value, _, found, err := loadSQLiteJSONRowWithRaw[T](ctx, q, query, args...)
	return value, found, err
}

// loadSQLiteJSONRowWithRaw is the same canonical decoder as
// loadSQLiteJSONRow, but returns the exact stored bytes as well. Chat-poll
// mutation paths need those bytes only when the row is opaque: doing a second
// SELECT for the raw JSON after decoding creates avoidable SQLite work while
// holding the durable state lock. Keeping the decoder in one helper preserves
// the existing recovery/sidecar behavior for every caller.
func loadSQLiteJSONRowWithRaw[T any](ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}, query string, args ...any) (T, []byte, bool, error) {
	var raw []byte
	if err := q.QueryRowContext(ctx, query, args...).Scan(&raw); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			var zero T
			return zero, nil, false, nil
		}
		var zero T
		return zero, raw, false, err
	}
	// A chat-poll row is an operational projection, not execution proof. Use
	// the SQL chat identity as a recovery placeholder for syntax/identity
	// failures, but retain a syntactically valid typed row here even when its
	// nested envelope is structurally unusable. The bridge must see that
	// envelope so it can move the exact pending receipt into gap evidence rather
	// than silently replacing it with a new baseline.
	var zero T
	if _, isChatPoll := any(zero).(ChatPollState); isChatPoll && len(args) == 1 {
		if chatID, ok := args[0].(string); ok {
			if poll, recoverable := decodeChatPollState(chatID, raw); recoverable {
				markChatPollRecoveryEvidence(&poll, raw)
				if poll.RecoveryRequired {
					if err := mergeSQLiteChatPollProjection(ctx, q, chatID, &poll); err != nil {
						var zero T
						return zero, raw, false, err
					}
				}
				return any(poll).(T), raw, true, nil
			}
		}
	}
	var value T
	if err := json.Unmarshal(raw, &value); err != nil {
		return zero, raw, false, err
	}
	return value, raw, true, nil
}

func saveSQLiteColdStateTx(ctx context.Context, tx *sql.Tx, state State) error {
	if err := upsertSQLiteSplitStateTx(ctx, tx, state); err != nil {
		return err
	}
	if err := replaceSQLiteChatSequencesTx(ctx, tx, state.ChatSequences); err != nil {
		return err
	}
	cold, err := json.Marshal(coldSQLiteState(state))
	if err != nil {
		return err
	}
	_, err = tx.ExecContext(ctx, `INSERT INTO state_meta(key, value) VALUES ('state_json', ?)
ON CONFLICT(key) DO UPDATE SET value = excluded.value`, cold)
	if err != nil {
		return err
	}
	stateJSONRevision, err := sqliteStateJSONRevision(ctx, tx)
	if err != nil {
		return err
	}
	if err := upsertSQLiteDashboardProjectionTx(ctx, tx, state, stateJSONRevision); err != nil {
		return err
	}
	if err := upsertSQLiteWorkflowProjectionTx(ctx, tx, state, stateJSONRevision); err != nil {
		return err
	}
	// HistoryWatch has a dedicated projection update path.  Do not rewrite that
	// projection on every unrelated cold-state/outbox update: it adds a JSON
	// marshal and state_meta write to the hot queue path and can overwrite a
	// newer watcher projection when a legacy full-state writer races with it.
	// The state_json revision trigger invalidates a stale projection; the next
	// HistoryWatch read/update will rebuild it from the canonical cold state.
	return nil
}

func upsertSQLiteHistoryWatchProjectionTx(ctx context.Context, tx *sql.Tx, history map[string]HistoryWatchCheckpoint, ready time.Time, stateJSONRevision int64) error {
	if history == nil {
		history = make(map[string]HistoryWatchCheckpoint)
	}
	raw, err := json.Marshal(sqliteHistoryWatchProjection{HistoryWatch: history, HistoryWatchReady: ready, StateJSONRevision: stateJSONRevision})
	if err != nil {
		return err
	}
	_, err = tx.ExecContext(ctx, `INSERT INTO state_meta(key, value) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET value = excluded.value`, sqliteHistoryWatchProjectionKey, raw)
	return err
}

func upsertSQLiteDashboardProjectionTx(ctx context.Context, tx *sql.Tx, state State, stateJSONRevision int64) error {
	if stateJSONRevision <= 0 {
		// Very old SQLite fixtures may not have the revision trigger yet.  Do not
		// publish an unfenced cache; the canonical state_json fallback remains
		// correct until normal schema preparation installs the revision.
		return nil
	}
	state.ensure(time.Time{})
	raw, err := json.Marshal(sqliteDashboardProjection{
		DashboardViews:    state.DashboardViews,
		DashboardNumbers:  state.DashboardNumbers,
		StateJSONRevision: stateJSONRevision,
	})
	if err != nil {
		return err
	}
	_, err = tx.ExecContext(ctx, `INSERT INTO state_meta(key, value) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET value = excluded.value`, sqliteDashboardProjectionKey, raw)
	return err
}

func upsertSQLiteWorkflowProjectionTx(ctx context.Context, tx *sql.Tx, state State, stateJSONRevision int64) error {
	if stateJSONRevision <= 0 {
		// Very old SQLite fixtures may not have the revision trigger yet.  Do not
		// publish an unfenced cache; the canonical state_json fallback remains
		// correct until normal schema preparation installs the revision.
		return nil
	}
	raw, err := json.Marshal(sqliteWorkflowProjection{
		Workflow:          state.Workflow,
		StateJSONRevision: stateJSONRevision,
	})
	if err != nil {
		return err
	}
	_, err = tx.ExecContext(ctx, `INSERT INTO state_meta(key, value) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET value = excluded.value`, sqliteWorkflowProjectionKey, raw)
	return err
}

const (
	sqliteRuntimeKeyScope                    = "scope"
	sqliteRuntimeKeyMachineIdentity          = "machine_identity"
	sqliteRuntimeKeyMachines                 = "machines"
	sqliteRuntimeKeyControlLease             = "control_lease"
	sqliteRuntimeKeyServiceOwner             = "service_owner"
	sqliteRuntimeKeyLockOwner                = "lock_owner"
	sqliteRuntimeKeyServiceControl           = "service_control"
	sqliteRuntimeKeyUpgrade                  = "upgrade"
	sqliteRuntimeKeyAutoUpdate               = "auto_update"
	sqliteRuntimeKeyControlChat              = "control_chat"
	sqliteRuntimeProjectionMaterializedKey   = "runtime_state_materialized"
	sqliteRuntimeProjectionMaterializedValue = "1"
)

// ErrSQLiteRuntimeProjectionIncomplete means a store that has already
// materialized its runtime projection is missing one or more required rows.
// Falling back to state_json in this state could overwrite a newer owner or
// lease with an older cold snapshot, so full-state runtime mutations fail
// closed until the projection is repaired by an explicit recovery path.
var ErrSQLiteRuntimeProjectionIncomplete = errors.New("SQLite runtime projection is incomplete")

func sqliteRuntimeProjectionIncompleteError(detail string) error {
	return fmt.Errorf("%w: %w: %s", ErrSQLiteRuntimeProjectionIncomplete, ErrControlLeaseStateUntrusted, detail)
}

var sqliteRuntimeRequiredKeys = []string{
	sqliteRuntimeKeyScope,
	sqliteRuntimeKeyMachineIdentity,
	sqliteRuntimeKeyMachines,
	sqliteRuntimeKeyControlLease,
	sqliteRuntimeKeyServiceOwner,
	sqliteRuntimeKeyLockOwner,
}

var sqliteRuntimePersistedKeys = append(append([]string{}, sqliteRuntimeRequiredKeys...),
	sqliteRuntimeKeyServiceControl,
	sqliteRuntimeKeyUpgrade,
	sqliteRuntimeKeyAutoUpdate,
	sqliteRuntimeKeyControlChat,
)

func saveSQLiteRuntimeStateTx(ctx context.Context, tx *sql.Tx, state State) error {
	machines := state.Machines
	if machines == nil {
		// json.Marshal(nil-map) emits null, which encoding/json would accept as a
		// valid map on read and thereby hide a torn required projection.  Persist
		// the canonical empty object for an initialized store instead.
		machines = map[string]MachineRecord{}
	}
	values := map[string]any{
		sqliteRuntimeKeyScope:           state.Scope,
		sqliteRuntimeKeyMachineIdentity: state.MachineIdentity,
		sqliteRuntimeKeyMachines:        machines,
		sqliteRuntimeKeyControlLease:    state.ControlLease,
		sqliteRuntimeKeyServiceOwner:    state.ServiceOwner,
		sqliteRuntimeKeyLockOwner:       state.LockOwner,
		sqliteRuntimeKeyServiceControl:  state.ServiceControl,
		sqliteRuntimeKeyUpgrade:         state.Upgrade,
		sqliteRuntimeKeyAutoUpdate:      state.AutoUpdate,
		sqliteRuntimeKeyControlChat:     state.ControlChat,
	}
	stmt, err := tx.PrepareContext(ctx, `INSERT INTO runtime_state(key, json) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET json = excluded.json`)
	if err != nil {
		return err
	}
	defer stmt.Close()
	for _, key := range sqliteRuntimePersistedKeys {
		data, err := json.Marshal(values[key])
		if err != nil {
			return err
		}
		if _, err := stmt.ExecContext(ctx, key, data); err != nil {
			return err
		}
	}
	return markSQLiteRuntimeProjectionMaterializedTx(ctx, tx)
}

func markSQLiteRuntimeProjectionMaterializedTx(ctx context.Context, tx *sql.Tx) error {
	_, err := tx.ExecContext(ctx, `INSERT INTO state_meta(key, value) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET value = excluded.value`, sqliteRuntimeProjectionMaterializedKey, sqliteRuntimeProjectionMaterializedValue)
	return err
}

// sqliteRuntimeObjectJSON rejects JSON null for required value projections.
// encoding/json accepts null when decoding into a struct or map and silently
// produces a zero value; that would make a torn scope/machine projection look
// complete and could overwrite a newer durable value on the next runtime write.
// Empty objects remain valid because an initialized store may not have selected
// a scope or machine identity yet.
func sqliteRuntimeObjectJSON(raw []byte) bool {
	raw = bytes.TrimSpace(raw)
	return len(raw) >= 2 && raw[0] == '{' && raw[len(raw)-1] == '}' && json.Valid(raw)
}

func loadSQLiteRuntimeState(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (State, map[string]bool, error) {
	return loadSQLiteRuntimeStateWithMode(ctx, q, true)
}

// loadSQLiteRuntimeStateBestEffort is used only by bounded liveness/admission
// paths.  A malformed optional projection row must not make the listener
// repeatedly decode the cold state or stop healthy chats from being admitted.
// The full Store.Load and migration paths continue to use the strict loader.
func loadSQLiteRuntimeStateBestEffort(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (State, map[string]bool, error) {
	return loadSQLiteRuntimeStateWithMode(ctx, q, false)
}

func loadSQLiteRuntimeStateWithMode(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, strict bool) (State, map[string]bool, error) {
	state := State{
		SchemaVersion: SchemaVersion,
		Machines:      map[string]MachineRecord{},
	}
	seen := make(map[string]bool)
	rows, err := q.QueryContext(ctx, `SELECT key, json FROM runtime_state`)
	if err != nil {
		return State{}, nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var key string
		var raw []byte
		if err := rows.Scan(&key, &raw); err != nil {
			return State{}, nil, err
		}
		var decodeErr error
		switch key {
		case sqliteRuntimeKeyScope:
			if !sqliteRuntimeObjectJSON(raw) {
				decodeErr = errors.New("runtime scope projection is not a JSON object")
			} else {
				decodeErr = json.Unmarshal(raw, &state.Scope)
			}
		case sqliteRuntimeKeyMachineIdentity:
			if !sqliteRuntimeObjectJSON(raw) {
				decodeErr = errors.New("runtime machine identity projection is not a JSON object")
			} else {
				decodeErr = json.Unmarshal(raw, &state.MachineIdentity)
			}
		case sqliteRuntimeKeyMachines:
			if !sqliteRuntimeObjectJSON(raw) {
				decodeErr = errors.New("runtime machines projection is not a JSON object")
			} else {
				decodeErr = json.Unmarshal(raw, &state.Machines)
			}
			if decodeErr == nil && state.Machines == nil {
				state.Machines = map[string]MachineRecord{}
			}
		case sqliteRuntimeKeyControlLease:
			decodeErr = json.Unmarshal(raw, &state.ControlLease)
			if decodeErr == nil {
				decodeErr = validateControlLeaseShape(state.ControlLease)
			}
		case sqliteRuntimeKeyServiceOwner:
			decodeErr = json.Unmarshal(raw, &state.ServiceOwner)
		case sqliteRuntimeKeyLockOwner:
			decodeErr = json.Unmarshal(raw, &state.LockOwner)
		case sqliteRuntimeKeyServiceControl:
			decodeErr = json.Unmarshal(raw, &state.ServiceControl)
		case sqliteRuntimeKeyUpgrade:
			decodeErr = json.Unmarshal(raw, &state.Upgrade)
		case sqliteRuntimeKeyAutoUpdate:
			decodeErr = json.Unmarshal(raw, &state.AutoUpdate)
		case sqliteRuntimeKeyControlChat:
			decodeErr = json.Unmarshal(raw, &state.ControlChat)
		default:
			continue
		}
		if decodeErr != nil {
			if strict {
				return State{}, nil, decodeErr
			}
			continue
		}
		seen[key] = true
	}
	if err := rows.Err(); err != nil {
		return State{}, nil, err
	}
	state.ensure(time.Time{})
	return state, seen, nil
}

func sqliteRuntimeStateUsable(seen map[string]bool) bool {
	for _, key := range sqliteRuntimeRequiredKeys {
		if !seen[key] {
			return false
		}
	}
	return true
}

func sqliteRuntimeProjectionMaterialized(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (bool, error) {
	rows, err := q.QueryContext(ctx, `SELECT value FROM state_meta WHERE key = ?`, sqliteRuntimeProjectionMaterializedKey)
	if err != nil {
		return false, err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return false, err
		}
		return false, nil
	}
	var raw []byte
	if err := rows.Scan(&raw); err != nil {
		return false, err
	}
	if err := rows.Err(); err != nil {
		return false, err
	}
	// Presence is the authority. Treat an unknown marker value as materialized
	// too, so a torn/manual marker write cannot reopen the unsafe cold fallback.
	return true, nil
}

func sqliteRuntimeProjectionStarted(seen map[string]bool, invalid map[string][]byte) bool {
	for _, key := range sqliteRuntimeRequiredKeys {
		if seen[key] || invalid[key] != nil {
			return true
		}
	}
	return false
}

func overlaySQLiteRuntimeState(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, state *State) error {
	return overlaySQLiteRuntimeStateWithMode(ctx, q, state, true)
}

func overlaySQLiteRuntimeStateBestEffort(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, state *State) error {
	return overlaySQLiteRuntimeStateWithMode(ctx, q, state, false)
}

func overlaySQLiteRuntimeStateWithMode(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, state *State, strict bool) error {
	var runtimeState State
	var seen map[string]bool
	var err error
	if strict {
		runtimeState, seen, err = loadSQLiteRuntimeState(ctx, q)
	} else {
		runtimeState, seen, err = loadSQLiteRuntimeStateBestEffort(ctx, q)
	}
	if err != nil {
		return err
	}
	if !sqliteRuntimeStateUsable(seen) {
		materialized, err := sqliteRuntimeProjectionMaterialized(ctx, q)
		if err != nil {
			return err
		}
		if materialized && strict {
			return sqliteRuntimeProjectionIncompleteError("missing required runtime rows")
		}
		if materialized {
			overlaySQLiteRuntimeStateValues(state, runtimeState, seen)
			state.ensure(time.Time{})
		}
		return nil
	}
	overlaySQLiteRuntimeStateValues(state, runtimeState, seen)
	state.ensure(time.Time{})
	return nil
}

func overlaySQLiteRuntimeStateValues(state *State, runtimeState State, seen map[string]bool) {
	if state == nil {
		return
	}
	state.Scope = runtimeState.Scope
	state.MachineIdentity = runtimeState.MachineIdentity
	state.Machines = runtimeState.Machines
	state.ControlLease = runtimeState.ControlLease
	state.ServiceOwner = runtimeState.ServiceOwner
	state.LockOwner = runtimeState.LockOwner
	if seen[sqliteRuntimeKeyServiceControl] {
		state.ServiceControl = runtimeState.ServiceControl
	}
	if seen[sqliteRuntimeKeyUpgrade] {
		state.Upgrade = runtimeState.Upgrade
	}
	if seen[sqliteRuntimeKeyAutoUpdate] {
		state.AutoUpdate = runtimeState.AutoUpdate
	}
	if seen[sqliteRuntimeKeyControlChat] {
		state.ControlChat = runtimeState.ControlChat
	}
}

// readUpgradeSQLite reads the bounded runtime projection used by the main-loop
// upgrade notice check. A complete runtime projection is authoritative for
// SQLite stores and avoids decoding the growing cold state document and chat
// sequences on every poll. Older stores with an incomplete projection fall
// back to the compatibility loader in ReadUpgrade.
func (s *Store) readUpgradeSQLiteUnlocked(ctx context.Context) (UpgradeRequest, bool, bool, error) {
	var out UpgradeRequest
	found := false
	handled := false
	pointer, ok, err := s.currentSQLitePointerUnlocked()
	if err != nil || !ok {
		return out, found, handled, err
	}
	db, err := s.sqliteDBUnlocked(pointer)
	if err != nil {
		return out, found, handled, err
	}
	runtimeState, seen, err := loadSQLiteRuntimeState(ctx, db)
	if err != nil {
		return out, found, handled, err
	}
	if !sqliteRuntimeStateUsable(seen) {
		materialized, materializedErr := sqliteRuntimeProjectionMaterialized(ctx, db)
		if materializedErr != nil {
			return out, found, handled, materializedErr
		}
		if materialized {
			return out, found, handled, sqliteRuntimeProjectionIncompleteError("missing required runtime rows")
		}
		return out, found, handled, nil
	}
	if !seen[sqliteRuntimeKeyUpgrade] {
		return out, found, handled, nil
	}
	handled = true
	if runtimeState.Upgrade == nil || runtimeState.Upgrade.ID == "" {
		return out, found, handled, nil
	}
	out = *runtimeState.Upgrade
	found = true
	return out, found, handled, nil
}

func seedMissingSQLiteRuntimeOptionalState(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, state *State, seen map[string]bool) error {
	if seen[sqliteRuntimeKeyServiceControl] && seen[sqliteRuntimeKeyUpgrade] && seen[sqliteRuntimeKeyAutoUpdate] && seen[sqliteRuntimeKeyControlChat] {
		return nil
	}
	cold, err := loadSQLiteColdState(ctx, q)
	if err != nil {
		return err
	}
	if !seen[sqliteRuntimeKeyServiceControl] {
		state.ServiceControl = cold.ServiceControl
	}
	if !seen[sqliteRuntimeKeyUpgrade] {
		state.Upgrade = cold.Upgrade
	}
	if !seen[sqliteRuntimeKeyAutoUpdate] {
		state.AutoUpdate = cold.AutoUpdate
	}
	if !seen[sqliteRuntimeKeyControlChat] {
		state.ControlChat = cold.ControlChat
	}
	return nil
}

// loadSQLiteOutboxForTurnTx is retained for package-local diagnostic tests and
// callers that already own a trusted test fixture. Runtime Store callers use
// the owner below, which adds the physical database provenance check.
func loadSQLiteOutboxForTurnTx(ctx context.Context, tx *sql.Tx, turnID string, out map[string]OutboxMessage) error {
	marker, err := sqliteReadMetaValueContext(ctx, tx, sqliteOutboxTurnProjectionTrustKey)
	if err != nil {
		return err
	}
	return loadSQLiteOutboxForTurnTxWithNativeReady(ctx, tx, turnID, out, strings.TrimSpace(marker) == sqliteOutboxTurnProjectionTrustTrusted)
}

func (s *Store) loadSQLiteOutboxForTurnTx(ctx context.Context, tx *sql.Tx, turnID string, out map[string]OutboxMessage) error {
	marker, err := sqliteReadMetaValueContext(ctx, tx, sqliteOutboxTurnProjectionTrustKey)
	if err != nil {
		return err
	}
	nativeReady := false
	if strings.TrimSpace(marker) == sqliteOutboxTurnProjectionTrustTrusted && strings.TrimSpace(s.sqliteDBPath) != "" {
		nativeReady, err = sqliteOutboxProjectionTrustProvenanceMatchesCurrent(ctx, tx, sqliteOutboxTurnProjectionTrustKey, s.sqliteDBPath)
		if err != nil {
			return err
		}
	}
	return loadSQLiteOutboxForTurnTxWithNativeReady(ctx, tx, turnID, out, nativeReady)
}

func (s *Store) updateSQLiteRuntimeState(ctx context.Context, fn func(*State) error) (bool, error) {
	return s.updateSQLiteRuntimeStateWithTx(ctx, fn, nil)
}

// updateSQLiteRuntimeStateWithTx applies a runtime-state mutation without
// decoding unrelated hot rows. An optional afterTx callback can update a
// small, explicitly selected set of split-table rows in the same transaction.
// This is used by lifecycle migrations that need runtime-state atomicity while
// still preserving the runtime fast path for stores with a damaged/unrelated
// hot row.
func (s *Store) updateSQLiteRuntimeStateWithTx(ctx context.Context, fn func(*State) error, afterTx func(context.Context, *sql.Tx) error) (bool, error) {
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		handled = true
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		state, seen, err := loadSQLiteRuntimeState(ctx, tx)
		if err != nil {
			return err
		}
		materialized, err := sqliteRuntimeProjectionMaterialized(ctx, tx)
		if err != nil {
			return err
		}
		if materialized && !sqliteRuntimeStateUsable(seen) {
			return sqliteRuntimeProjectionIncompleteError("missing required runtime rows")
		}
		seedRuntime := !sqliteRuntimeStateUsable(seen)
		seedOptional := !seen[sqliteRuntimeKeyServiceControl] || !seen[sqliteRuntimeKeyUpgrade] || !seen[sqliteRuntimeKeyAutoUpdate] || !seen[sqliteRuntimeKeyControlChat]
		if seedRuntime {
			state, err = loadSQLiteColdState(ctx, tx)
			if err != nil {
				return err
			}
		} else if err := seedMissingSQLiteRuntimeOptionalState(ctx, tx, &state, seen); err != nil {
			return err
		}
		if err := fn(&state); err != nil {
			if errors.Is(err, errStoreNoChange) && (seedRuntime || seedOptional) {
				state.ensure(time.Now())
				if afterTx != nil {
					if err := afterTx(ctx, tx); err != nil {
						return err
					}
				}
				if saveErr := saveSQLiteRuntimeStateTx(ctx, tx, state); saveErr != nil {
					return saveErr
				}
				return tx.Commit()
			}
			return err
		}
		state.ensure(time.Now())
		if afterTx != nil {
			if err := afterTx(ctx, tx); err != nil {
				return err
			}
		}
		if err := saveSQLiteRuntimeStateTx(ctx, tx, state); err != nil {
			return err
		}
		return tx.Commit()
	})
	if errors.Is(err, errStoreNoChange) {
		return handled, nil
	}
	return handled, err
}

type sqliteLegacyHistoryGatePage struct {
	retired        int
	rowsRead       int
	afterCreatedAt int64
	afterID        string
}

// retireLegacyHistoryGateOutboxSQLitePageTx retires one bounded page of
// obsolete history-gate notices while the caller owns the transaction. It
// deliberately reads raw outbox rows instead of the full state document: a
// malformed unrelated hot row must not prevent an upgrade from establishing
// its drain fence.
//
// The caller must commit this page before starting the next one. Keeping the
// transaction page-local is important: startup cleanup is compatibility work,
// and a large outbox must not hold the sole SQLite connection long enough to
// block the owner heartbeat or the normal delivery path.
func retireLegacyHistoryGateOutboxSQLitePageTx(ctx context.Context, tx *sql.Tx, pageSize int, afterCreatedAt int64, afterID string, includeActiveSending bool, capability storeOwnerCapability) (sqliteLegacyHistoryGatePage, error) {
	if pageSize <= 0 {
		pageSize = 128
	}
	if capability.bound() {
		// BeginTx is deferred in the SQLite driver. Reserve the writer slot
		// before reading/decode/linked-record work so a takeover cannot commit a
		// new control lease between the owner check and this page's outbox
		// updates. The self-assignment is intentionally a no-op on the durable
		// revision; it only upgrades the transaction to the writer side.
		if _, err := tx.ExecContext(ctx, `UPDATE state_meta SET value = value WHERE key = ?`, sqliteStateJSONRevisionKey); err != nil {
			return sqliteLegacyHistoryGatePage{}, err
		}
		matches, err := sqliteStoreActiveOwnerCapabilityMatchesTx(ctx, tx, capability.machineID, capability.leaseGeneration)
		if err != nil {
			return sqliteLegacyHistoryGatePage{}, err
		}
		if !matches {
			return sqliteLegacyHistoryGatePage{}, ErrControlLeaseNotHeld
		}
	}
	type candidate struct {
		id        string
		createdAt int64
		message   OutboxMessage
	}
	result := sqliteLegacyHistoryGatePage{afterCreatedAt: afterCreatedAt, afterID: afterID}
	clauses := []string{"status IN (?, ?)"}
	args := []any{string(OutboxStatusQueued), string(OutboxStatusSending)}
	if afterID != "" || afterCreatedAt != 0 {
		clauses = append(clauses, "(created_at > ? OR (created_at = ? AND id > ?))")
		args = append(args, afterCreatedAt, afterCreatedAt, afterID)
	}
	args = append(args, pageSize+1)
	rows, err := tx.QueryContext(ctx, `SELECT id, created_at, json
FROM outbox_messages
WHERE `+strings.Join(clauses, " AND ")+`
ORDER BY created_at, id
LIMIT ?`, args...)
	if err != nil {
		return result, err
	}
	rowsRead := 0
	candidates := make([]candidate, 0, pageSize)
	for rows.Next() {
		var rowID string
		var createdAt int64
		var raw []byte
		if err := rows.Scan(&rowID, &createdAt, &raw); err != nil {
			_ = rows.Close()
			return result, err
		}
		rowsRead++
		result.afterCreatedAt = createdAt
		result.afterID = rowID
		var msg OutboxMessage
		if err := json.Unmarshal(raw, &msg); err != nil {
			continue
		}
		if strings.TrimSpace(msg.ID) == "" || msg.ID != rowID {
			continue
		}
		candidates = append(candidates, candidate{id: rowID, createdAt: createdAt, message: msg})
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return result, err
	}
	if err := rows.Close(); err != nil {
		return result, err
	}
	for _, item := range candidates {
		if !legacyHistoryGateNoticeRetirable(item.message, time.Now(), includeActiveSending) {
			continue
		}
		state := newState()
		state.OutboxMessages[item.id] = item.message
		if err := loadSQLiteOutboxLinkedRecordsTx(ctx, tx, &state, item.id); err != nil {
			return result, err
		}
		updated, err := markOutboxSkippedLocked(&state, item.message, "obsolete automatic history-gate notice", time.Now())
		if err != nil {
			return result, err
		}
		if updated.Status == item.message.Status {
			continue
		}
		if err := upsertSQLiteOutboxTx(ctx, tx, updated); err != nil {
			return result, err
		}
		if err := upsertSQLiteOutboxLinkedRecordsTx(ctx, tx, state); err != nil {
			return result, err
		}
		result.retired++
	}
	if capability.bound() {
		matches, err := sqliteStoreActiveOwnerCapabilityMatchesTx(ctx, tx, capability.machineID, capability.leaseGeneration)
		if err != nil {
			return result, err
		}
		if !matches {
			return result, ErrControlLeaseNotHeld
		}
	}
	result.rowsRead = rowsRead
	return result, nil
}

func (s *Store) retireLegacyHistoryGateOutboxSQLite(ctx context.Context, pageSize int, maxPages int, includeActiveSending bool, capability storeOwnerCapability) (int, bool, error) {
	if pageSize <= 0 {
		pageSize = 128
	}
	if maxPages <= 0 {
		maxPages = 16
	}
	retired := 0
	handled := false
	var afterCreatedAt int64
	var afterID string
	for page := 0; page < maxPages; page++ {
		var result sqliteLegacyHistoryGatePage
		pageHandled := false
		err := s.withStateLock(ctx, func() error {
			pointer, ok, err := s.currentSQLitePointerUnlocked()
			if err != nil || !ok {
				return err
			}
			pageHandled = true
			handled = true
			db, err := s.sqliteDBUnlocked(pointer)
			if err != nil {
				return err
			}
			tx, err := db.BeginTx(ctx, nil)
			if err != nil {
				return err
			}
			defer tx.Rollback()
			result, err = retireLegacyHistoryGateOutboxSQLitePageTx(ctx, tx, pageSize, afterCreatedAt, afterID, includeActiveSending, capability)
			if err != nil {
				return err
			}
			return tx.Commit()
		})
		if err != nil {
			return retired, handled, err
		}
		if !pageHandled {
			return retired, false, nil
		}
		retired += result.retired
		afterCreatedAt = result.afterCreatedAt
		afterID = result.afterID
		if sqliteLegacyHistoryGatePageTestHook != nil {
			sqliteLegacyHistoryGatePageTestHook()
		}
		if result.rowsRead <= pageSize {
			break
		}
	}
	return retired, handled, nil
}

// rebindSQLiteScopeForMigration updates only the bounded runtime projection and
// the small state_meta document. It deliberately leaves all business-data
// tables untouched.
func (s *Store) rebindSQLiteScopeForMigration(ctx context.Context, fn func(*State) error) (bool, error) {
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		handled = true
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		runtimeState, seen, err := loadSQLiteRuntimeState(ctx, tx)
		if err != nil {
			return err
		}
		if !sqliteRuntimeStateUsable(seen) {
			return errors.New("sqlite teams store is missing required runtime state")
		}
		coldState, err := loadSQLiteColdStateWithoutChatSequences(ctx, tx)
		if err != nil {
			return err
		}
		runtimeState.ControlChat = coldState.ControlChat
		if err := fn(&runtimeState); err != nil {
			return err
		}
		coldState.ControlChat = runtimeState.ControlChat
		if err := saveSQLiteRuntimeStateTx(ctx, tx, runtimeState); err != nil {
			return err
		}
		cold, err := json.Marshal(coldSQLiteState(coldState))
		if err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `INSERT INTO state_meta(key, value) VALUES ('state_json', ?)
ON CONFLICT(key) DO UPDATE SET value = excluded.value`, cold); err != nil {
			return err
		}
		return tx.Commit()
	})
	return handled, err
}

func (s *Store) importCheckpointSQLite(ctx context.Context, id string) (ImportCheckpoint, bool, bool, error) {
	var out ImportCheckpoint
	found := false
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		handled = true
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		out, found, _, err = loadSQLiteCheckpointForIDWithDisposition(ctx, db, `SELECT id, session_id, status, updated_at, json FROM import_checkpoints WHERE id = ?`, id)
		return err
	})
	return out, found, handled, err
}

// RepairOpaqueImportCheckpoint replaces one opaque canonical SQLite row only
// when its exact raw payload is still the one the caller inspected.  This is
// intentionally a narrow, explicit operation: ordinary reads, queue claims,
// and unrelated state updates must never turn a forensic fallback into a new
// typed row.  The raw compare is kept in the UPDATE predicate as well as the
// transaction-local read so an external/manual writer cannot be overwritten
// by a stale repair decision.
func (s *Store) RepairOpaqueImportCheckpoint(ctx context.Context, id string, expectedRaw []byte, replacement ImportCheckpoint) error {
	if ctx == nil {
		ctx = context.Background()
	}
	id = strings.TrimSpace(id)
	if id == "" || expectedRaw == nil {
		return ErrCheckpointRepairConflict
	}
	expectedSessionID, canonical := canonicalCheckpointSessionID(id)
	if !canonical {
		return fmt.Errorf("%w: checkpoint %q is not a canonical session checkpoint", ErrCheckpointRepairConflict, id)
	}
	if replacement.ID != "" && strings.TrimSpace(replacement.ID) != id {
		return fmt.Errorf("%w: replacement id %q does not match %q", ErrSessionStateProvenanceMismatch, replacement.ID, id)
	}
	if replacement.SessionID != "" && strings.TrimSpace(replacement.SessionID) != expectedSessionID {
		return fmt.Errorf("%w: replacement session %q does not match %q", ErrSessionStateProvenanceMismatch, replacement.SessionID, expectedSessionID)
	}
	replacement.ID = id
	replacement.SessionID = expectedSessionID
	if replacement.RecoveryProofUnusable || !importCheckpointOptionalProofUsable(replacement) {
		return fmt.Errorf("%w: replacement recovery proof is not usable", ErrSessionStateProvenanceMismatch)
	}
	if err := validateImportCheckpointProvenance(replacement, expectedSessionID, id); err != nil {
		return err
	}
	replacementRaw, err := json.Marshal(replacement)
	if err != nil {
		return err
	}
	return s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil {
			return err
		}
		if !ok {
			return ErrSQLiteCheckpointRepairUnavailable
		}
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		row, found, err := loadSQLiteCheckpointRow(ctx, tx, `SELECT id, session_id, status, updated_at, json FROM import_checkpoints WHERE id = ?`, id)
		if err != nil {
			return err
		}
		// For the canonical per-session checkpoint the primary key is the
		// durable identity.  session_id is a nullable compatibility projection
		// and may be NULL or stale after an interrupted projection update.  The
		// exact raw-payload CAS below still fences the repair; rejecting the row
		// here merely makes point-read normalization and explicit repair disagree
		// about the same forensic row.
		if !found || strings.TrimSpace(row.ID) != id {
			return ErrCheckpointRepairConflict
		}
		if !bytes.Equal(row.Raw, expectedRaw) {
			// A client may lose the commit response after SQLite has committed.
			// If the row already contains the exact requested replacement, the
			// retry is idempotently complete; any other raw value is a conflict.
			if bytes.Equal(row.Raw, replacementRaw) {
				// An earlier repair may have committed the JSON but lost the
				// response before its identity projection was normalized.  Make
				// the retry repair that derived column as well, without requiring
				// the old session_id value to be present.
				if _, err := tx.ExecContext(ctx, `UPDATE import_checkpoints SET session_id = ? WHERE id = ? AND json = ?`, replacement.SessionID, id, replacementRaw); err != nil {
					return err
				}
				return tx.Commit()
			}
			return ErrCheckpointRepairConflict
		}
		result, err := tx.ExecContext(ctx, `UPDATE import_checkpoints SET session_id = ?, status = ?, updated_at = ?, json = ? WHERE id = ? AND json = ?`,
			replacement.SessionID, replacement.Status, sqliteTime(replacement.UpdatedAt), replacementRaw, id, expectedRaw)
		if err != nil {
			return err
		}
		rowsAffected, err := result.RowsAffected()
		if err != nil {
			return err
		}
		if rowsAffected != 1 {
			return ErrCheckpointRepairConflict
		}
		return tx.Commit()
	})
}

// promoteProofBackedImportCheckpointSQLite is the SQLite half of the narrow
// compatibility promotion API.  The typed row is loaded and compared inside
// the same transaction that writes the replacement, so a scanner cannot move
// a cursor or install a new quarantine between validation and promotion.
func (s *Store) promoteProofBackedImportCheckpointSQLite(ctx context.Context, expected ImportCheckpoint, replacement ImportCheckpoint) (bool, bool, error) {
	changed := false
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		handled = true
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		current, found, _, err := loadSQLiteCanonicalCheckpointRow(ctx, tx, expected.ID, expected.SessionID)
		if err != nil {
			return err
		}
		if !found || !proofBackedCheckpointCASMatches(current, expected) || !current.LegacySourceUnverified && !current.RecoveryProofUnusable {
			return ErrProofBackedCheckpointPromotionConflict
		}
		replacement.UpdatedAt = time.Now()
		if err := upsertSQLiteImportCheckpointTx(ctx, tx, replacement); err != nil {
			return err
		}
		if err := tx.Commit(); err != nil {
			return err
		}
		changed = true
		return nil
	})
	return changed, handled, err
}

func (s *Store) loadSQLiteImportCheckpointsByIDsUnlocked(ctx context.Context, pointer storeSQLitePointer, requested map[string]string) (map[string]ImportCheckpoint, error) {
	out := make(map[string]ImportCheckpoint, len(requested))
	if len(requested) == 0 {
		return out, nil
	}
	db, err := s.sqliteDBUnlocked(pointer)
	if err != nil {
		return nil, err
	}
	ids := make([]string, 0, len(requested))
	for id := range requested {
		ids = append(ids, id)
	}
	for start := 0; start < len(ids); start += sqliteQueryParameterBatchSize {
		end := start + sqliteQueryParameterBatchSize
		if end > len(ids) {
			end = len(ids)
		}
		batch := ids[start:end]
		args := make([]any, 0, len(batch))
		for _, id := range batch {
			args = append(args, id)
		}
		placeholders := strings.TrimRight(strings.Repeat("?,", len(batch)), ",")
		rows, err := db.QueryContext(ctx, `SELECT id, COALESCE(session_id, ''), json FROM import_checkpoints WHERE id IN (`+placeholders+`)`, args...)
		if err != nil {
			return nil, err
		}
		for rows.Next() {
			row, err := scanSQLiteCheckpointIdentityFastRow(rows)
			if err != nil {
				_ = rows.Close()
				return nil, err
			}
			sessionID := strings.TrimSpace(requested[row.ID])
			if canonicalSessionID, canonical := canonicalCheckpointSessionID(row.ID); canonical && canonicalSessionID == sessionID {
				// ImportCheckpointsForSessions constructs this map from registered
				// session identities. The primary key is therefore the trusted
				// canonical identity; session_id is only a derived projection and
				// may be stale or NULL after an interrupted write.
				row.SessionID = sql.NullString{String: canonicalSessionID, Valid: true}
			}
			checkpoint, _, _, err := decodeSQLiteCheckpointRowWithCanonicalIdentity(row, row.ID, sessionID, false, true)
			if err != nil {
				_ = rows.Close()
				return nil, err
			}
			out[row.ID] = checkpoint
		}
		if err := rows.Err(); err != nil {
			_ = rows.Close()
			return nil, err
		}
		if err := rows.Close(); err != nil {
			return nil, err
		}
	}
	return out, nil
}

func (s *Store) updateImportCheckpointSQLite(ctx context.Context, parentSessionID string, id string, fn func(ImportCheckpoint, bool, time.Time) (ImportCheckpoint, bool, error), capability storeOwnerCapability) (ImportCheckpoint, bool, bool, error) {
	var out ImportCheckpoint
	changed := false
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		if capability.bound() {
			lease, loadErr := loadSQLiteControlLease(ctx, tx)
			if loadErr != nil {
				return loadErr
			}
			if err := validateStoreOwnerCapability(&State{ControlLease: lease}, capability); err != nil {
				return err
			}
		}
		if err := ensureSQLiteParentUnfencedTx(ctx, tx, parentSessionID); err != nil {
			return err
		}
		current, found, opaque, err := loadSQLiteCanonicalCheckpointRow(ctx, tx, id, "")
		if err != nil {
			return err
		}
		now := time.Now()
		next, updateChanged, err := fn(current, found, now)
		if err != nil {
			return err
		}
		if err := validateImportCheckpointUpdateProvenance(id, current, found, next); err != nil {
			return err
		}
		if opaque && updateChanged {
			return ErrOpaqueCheckpoint
		}
		out = next
		handled = true
		if !updateChanged {
			return tx.Commit()
		}
		next.ID = id
		if err := upsertSQLiteImportCheckpointTx(ctx, tx, next); err != nil {
			return err
		}
		out = next
		changed = true
		return tx.Commit()
	})
	return out, changed, handled, err
}

func (s *Store) recordTranscriptCheckpointSQLite(ctx context.Context, parentSessionID string, checkpoint ImportCheckpoint, ledger TranscriptLedgerRecord, capability storeOwnerCapability) (bool, error) {
	handled := false
	run := func() error {
		return s.withStateLock(ctx, func() error {
			pointer, ok, err := s.currentSQLitePointerUnlocked()
			if err != nil || !ok {
				return err
			}
			db, err := s.sqliteDBUnlocked(pointer)
			if err != nil {
				return err
			}
			tx, err := db.BeginTx(ctx, nil)
			if err != nil {
				return err
			}
			defer tx.Rollback()
			if capability.bound() {
				lease, loadErr := loadSQLiteControlLease(ctx, tx)
				if loadErr != nil {
					return loadErr
				}
				if err := validateStoreOwnerCapability(&State{ControlLease: lease}, capability); err != nil {
					return err
				}
			}
			if err := ensureSQLiteParentUnfencedTx(ctx, tx, parentSessionID); err != nil {
				return err
			}
			state := State{
				SchemaVersion:            SchemaVersion,
				ImportCheckpoints:        map[string]ImportCheckpoint{},
				TranscriptLedger:         map[string]TranscriptLedgerRecord{},
				legacyUnresolvedSessions: map[string]bool{},
			}
			if existing, ok, disposition, err := loadSQLiteCheckpointForIDWithDisposition(ctx, tx, `SELECT id, session_id, status, updated_at, json FROM import_checkpoints WHERE id = ?`, checkpoint.ID); err != nil {
				return err
			} else if ok {
				if disposition == sqliteCheckpointMalformedCanonical {
					return ErrOpaqueCheckpoint
				}
				if err := validateLoadedTranscriptCheckpointRow(existing, checkpoint.ID, checkpoint.SessionID); err != nil {
					return err
				}
				state.ImportCheckpoints[existing.ID] = existing
			}
			if err := loadSQLiteSessionTranscriptCheckpointTx(ctx, tx, &state, checkpoint.SessionID); err != nil {
				return err
			}
			if err := markSQLiteLegacyUnresolvedSessionTx(ctx, tx, &state, checkpoint.SessionID); err != nil {
				return err
			}
			if err := validateTranscriptCheckpointRecordProvenance(&state, checkpoint); err != nil {
				return err
			}
			previous, _ := state.ImportCheckpoints[checkpoint.ID]
			if stateHasUnresolvedExecution(&state, checkpoint.SessionID) &&
				!importCheckpointIsExplicitHistoryRun(previous) {
				return ErrUnresolvedExecution
			}
			nextCheckpoint, nextLedger := applyRecordTranscriptCheckpointLocked(&state, checkpoint, ledger, time.Now())
			if err := upsertSQLiteImportCheckpointTx(ctx, tx, nextCheckpoint); err != nil {
				return err
			}
			if err := upsertSQLiteTranscriptLedgerTx(ctx, tx, nextLedger); err != nil {
				return err
			}
			if err := pruneSQLiteTranscriptLedgerTx(ctx, tx, maxRetainedTranscriptLedgerRecords); err != nil {
				return err
			}
			if err := pruneSQLiteTranscriptDeliveriesTx(ctx, tx, maxRetainedTranscriptDeliveries); err != nil {
				return err
			}
			handled = true
			return tx.Commit()
		})
	}
	if sessionID := strings.TrimSpace(checkpoint.SessionID); sessionID != "" {
		err := s.withSessionLock(ctx, sessionID, run)
		return handled, err
	}
	err := run()
	return handled, err
}

func (s *Store) updateSQLiteColdState(ctx context.Context, fn func(*State) error) (bool, error) {
	return s.updateSQLiteColdStateIfChanged(ctx, func(state *State) (bool, error) {
		if err := fn(state); err != nil {
			return false, err
		}
		return true, nil
	})
}

// updateSQLiteColdStateIfChanged keeps the transaction and cold-state lock
// narrow while allowing callers that can prove a no-op to avoid rewriting the
// state_json row and all split metadata. In particular, history-watch polls
// must not rewrite SQLite for an unchanged incomplete tail.
func (s *Store) updateSQLiteColdStateIfChanged(ctx context.Context, fn func(*State) (bool, error)) (bool, error) {
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		handled = true
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		state, err := loadSQLiteColdState(ctx, tx)
		if err != nil {
			return err
		}
		changed, err := fn(&state)
		if err != nil {
			return err
		}
		if !changed {
			return tx.Commit()
		}
		state.ensure(time.Now())
		if err := saveSQLiteColdStateTx(ctx, tx, state); err != nil {
			return err
		}
		return tx.Commit()
	})
	if errors.Is(err, errStoreNoChange) {
		return handled, nil
	}
	return handled, err
}

// updateSQLiteHistoryWatchIfChanged updates only the history-watch projection.
// Older pointers that lack the projection are read through JSON1 once and are
// materialized lazily on the first changed update. The projection lives in the
// existing state_meta table, so no schema migration is required; each update
// remains atomic under the same store lock and SQLite transaction.
func (s *Store) updateSQLiteHistoryWatchIfChanged(ctx context.Context, fn func(map[string]HistoryWatchCheckpoint, *time.Time) error) (bool, error) {
	return s.updateSQLiteHistoryWatchIfChangedWithCapability(ctx, fn, storeOwnerCapability{})
}

func (s *Store) updateSQLiteHistoryWatchIfChangedWithCapability(ctx context.Context, fn func(map[string]HistoryWatchCheckpoint, *time.Time) error, capability storeOwnerCapability) (bool, error) {
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		handled = true
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		if capability.bound() {
			lease, loadErr := loadSQLiteControlLease(ctx, tx)
			if loadErr != nil {
				return loadErr
			}
			if err := validateStoreOwnerCapability(&State{ControlLease: lease}, capability); err != nil {
				return err
			}
		}

		history, ready, projectionRevision, stateJSONRevision, found, err := loadSQLiteHistoryWatchProjection(ctx, tx)
		if err != nil {
			return err
		}
		// A missing/legacy projection or a revision mismatch means an older
		// full-state writer may have changed state_json. Start from that JSON and
		// rematerialize a current projection after applying this update.
		if found && (projectionRevision <= 0 || stateJSONRevision <= 0 || projectionRevision != stateJSONRevision) {
			found = false
		}
		if !found {
			// Old SQLite pointers have only state_json.  Read just the two
			// history-watch members once, then materialize the projection on
			// the first changed update below.
			var raw []byte
			var readyRaw sql.NullString
			if err := tx.QueryRowContext(ctx, `
SELECT CASE WHEN json_valid(value) THEN COALESCE(json_extract(value, '$.history_watch'), '{}') ELSE '{}' END,
       CASE WHEN json_valid(value) THEN json_extract(value, '$.history_watch_ready') ELSE NULL END
FROM state_meta WHERE key = 'state_json'`).Scan(&raw, &readyRaw); err != nil {
				if errors.Is(err, sql.ErrNoRows) {
					return errors.New("sqlite teams store is missing state metadata")
				}
				return err
			}
			history = make(map[string]HistoryWatchCheckpoint)
			if len(raw) > 0 && string(raw) != "null" {
				var rows map[string]json.RawMessage
				if err := json.Unmarshal(raw, &rows); err != nil {
					return err
				}
				if err := decodeJSONHistoryWatchRows(rows, history); err != nil {
					return err
				}
			}
			if readyRaw.Valid && strings.TrimSpace(readyRaw.String) != "" {
				ready, err = time.Parse(time.RFC3339Nano, readyRaw.String)
				if err != nil {
					// This is only a scheduling hint. Ignore a malformed value and
					// let the next successful history update establish it again.
					ready = time.Time{}
				}
			}
			// A legacy SQLite pointer has no projection row, so the loader
			// cannot supply the state_json revision.  Fetch it before
			// materializing the projection; revision zero is intentionally
			// rejected by the overlay path and would otherwise force every
			// subsequent update back through JSON1.
			stateJSONRevision, err = sqliteStateJSONRevision(ctx, tx)
			if err != nil {
				return err
			}
		}
		before := cloneHistoryWatchCheckpoints(history)
		beforeReady := ready
		if err := fn(history, &ready); err != nil {
			return err
		}
		if !historyWatchCheckpointsEqual(before, history) || !beforeReady.Equal(ready) {
			if err := upsertSQLiteHistoryWatchProjectionTx(ctx, tx, history, ready, stateJSONRevision); err != nil {
				return err
			}
		}
		return tx.Commit()
	})
	if errors.Is(err, errStoreNoChange) {
		return handled, nil
	}
	return handled, err
}

func (s *Store) recordControlChatBindingSQLite(ctx context.Context, update ControlChatBindingUpdate) (bool, bool, error) {
	changed := false
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		handled = true
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		state, err := loadSQLiteColdState(ctx, tx)
		if err != nil {
			return err
		}
		if err := overlaySQLiteRuntimeState(ctx, tx, &state); err != nil {
			return err
		}
		changed = applyControlChatBindingUpdate(&state, update, time.Now())
		if !changed {
			return tx.Commit()
		}
		state.ensure(time.Now())
		if err := saveSQLiteRuntimeStateTx(ctx, tx, state); err != nil {
			return err
		}
		if err := saveSQLiteColdStateTx(ctx, tx, state); err != nil {
			return err
		}
		return tx.Commit()
	})
	return changed, handled, err
}

func (s *Store) historyWatchStateSQLite(ctx context.Context) (State, bool, error) {
	var state State
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		history, ready, projectionRevision, stateJSONRevision, found, projectionErr := loadSQLiteHistoryWatchProjection(ctx, db)
		if projectionErr != nil {
			return projectionErr
		}
		if found && projectionRevision > 0 && stateJSONRevision > 0 && projectionRevision == stateJSONRevision {
			// The history projection is maintained in the same durable state
			// transaction as its revision. Reading only this row avoids decoding
			// the potentially hundreds-of-megabytes state_json document on every
			// backlog wake. The full cold fallback below remains necessary for a
			// first migration or a mixed-version/stale projection.
			state = State{
				SchemaVersion:     SchemaVersion,
				HistoryWatch:      history,
				HistoryWatchReady: ready,
			}
			handled = true
			return nil
		}
		state, err = loadSQLiteColdState(ctx, db)
		handled = true
		return err
	})
	return state, handled, err
}

func (s *Store) historyWatchOriginStateSQLite(ctx context.Context, threadID string) (State, bool, error) {
	state := State{
		SchemaVersion: SchemaVersion,
		Sessions:      make(map[string]SessionContext),
		Turns:         make(map[string]Turn),
		InboundEvents: make(map[string]InboundEvent),
	}
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		handled = true
		if err := loadSQLiteSessionMap(ctx, db, `SELECT id, teams_chat_id, status, updated_at, json FROM sessions`, state.Sessions); err != nil {
			return err
		}
		if err := loadSQLiteTurnMap(ctx, db, `SELECT id, session_id, status, json FROM turns`, state.Turns, true); err != nil {
			return err
		}

		threadID = strings.TrimSpace(threadID)
		sessionIDs := make(map[string]struct{})
		inboundIDs := make(map[string]struct{})
		for _, session := range state.Sessions {
			if strings.TrimSpace(session.CodexThreadID) == threadID {
				if sessionID := strings.TrimSpace(session.ID); sessionID != "" {
					sessionIDs[sessionID] = struct{}{}
				}
			}
		}
		for _, turn := range state.Turns {
			if strings.TrimSpace(turn.CodexThreadID) != threadID {
				continue
			}
			if sessionID := strings.TrimSpace(turn.SessionID); sessionID != "" {
				sessionIDs[sessionID] = struct{}{}
			}
			if inboundID := strings.TrimSpace(turn.InboundEventID); inboundID != "" {
				inboundIDs[inboundID] = struct{}{}
			}
		}
		if err := loadSQLiteHistoryWatchInboundRows(ctx, db, "session_id", sortedMapKeys(sessionIDs), state.InboundEvents); err != nil {
			return err
		}
		return loadSQLiteHistoryWatchInboundRows(ctx, db, "id", sortedMapKeys(inboundIDs), state.InboundEvents)
	})
	return state, handled, err
}

func loadSQLiteHistoryWatchInboundRows(ctx context.Context, db *sql.DB, column string, values []string, out map[string]InboundEvent) error {
	if len(values) == 0 {
		return nil
	}
	switch column {
	case "id", "session_id":
	default:
		return fmt.Errorf("unsupported history-watch inbound lookup column %q", column)
	}
	const batchSize = 400
	for start := 0; start < len(values); start += batchSize {
		end := min(start+batchSize, len(values))
		placeholders := make([]string, 0, end-start)
		args := make([]any, 0, end-start)
		for _, value := range values[start:end] {
			placeholders = append(placeholders, "?")
			args = append(args, value)
		}
		query := `SELECT json FROM inbound_events WHERE ` + column + ` IN (` + strings.Join(placeholders, ",") + `)`
		if err := loadSQLiteJSONMapBestEffort(ctx, db, query, out, func(v InboundEvent) string { return v.ID }, args...); err != nil {
			return err
		}
	}
	return nil
}

func (s *Store) claimControlLeaseSQLite(ctx context.Context, claim ControlLeaseClaim) (ControlLeaseDecision, bool, error) {
	var out ControlLeaseDecision
	var handled bool
	// Schema/bootstrap paths use the state-file lock before they perform any
	// structural SQLite mutation. Lease acquisition must take the same short
	// inter-process lock; otherwise a replacement claimant can commit between
	// the bootstrap lease check and ALTER/CREATE/trigger repair. The lock is held
	// only for the bounded lease transaction, never for polling or heartbeat.
	err := s.withStateLock(ctx, func() error {
		var err error
		out, handled, err = s.claimControlLeaseSQLiteUnlocked(ctx, claim)
		return err
	})
	return out, handled, err
}

func (s *Store) claimControlLeaseSQLiteUnlocked(ctx context.Context, claim ControlLeaseClaim) (ControlLeaseDecision, bool, error) {
	var out ControlLeaseDecision
	handled, err := s.withSQLiteRuntimeDB(ctx, func(db *sql.DB) error {
		// Claiming the control lease is the ownership boundary for every
		// owner-scoped SQLite write.  Do not let an alternate caller acquire it
		// while schema/trigger preparation is still incomplete; the listener's
		// explicit preflight is the normal path, but the store API must enforce
		// the same invariant for direct claim callers and restart races.
		ready, readyErr := sqliteSchemaPreparationReadyContext(ctx, db)
		if readyErr != nil {
			return readyErr
		}
		if !ready {
			return fmt.Errorf("%w: schema preparation is required before control-lease claim", ErrSQLiteSchemaPreparationRequired)
		}
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		// A ready marker can survive a crash between structural repair and
		// preparation-claim cleanup.  The claim remains a hard fence: allowing a
		// new owner to proceed would let its heartbeat race a repair that the old
		// process may still be finishing.  Do this inside the same transaction as
		// lease admission so direct claim callers have the same invariant as the
		// listener startup path.
		if blocked, blockErr := sqliteSchemaPreparationClaimBlocksHeartbeat(ctx, tx); blockErr != nil {
			return blockErr
		} else if blocked {
			return ErrSQLiteSchemaPreparationInProgress
		}
		state, seen, invalid, err := loadSQLiteRequiredRuntimeStateDetailed(ctx, tx)
		if err != nil {
			return err
		}
		materialized, err := sqliteRuntimeProjectionMaterialized(ctx, tx)
		if err != nil {
			return err
		}
		if len(invalid) > 0 {
			// An unknown control-lease status is not an expired lease proof. It
			// is a semantically valid row whose meaning this binary does not
			// understand, so never fall back to the older cold copy and claim
			// over a possibly live writer.
			if err := invalidSQLiteRequiredRuntimeError(invalid); errors.Is(err, ErrControlLeaseStatusUnknown) {
				return err
			}
			// A malformed required runtime row is different from a legacy missing
			// projection.  It may be repaired only when an independently decoded
			// lease proves that the previous owner is no longer live.  Otherwise an
			// unknown row could hide a live writer and a replacement claim would
			// split ownership.
			cold, loadErr := loadSQLiteColdState(ctx, tx)
			if loadErr != nil {
				return loadErr
			}
			lease := cold.ControlLease
			if seen[sqliteRuntimeKeyControlLease] {
				lease = state.ControlLease
			} else if !sqliteCorruptControlLeaseExpiryProven(cold.ControlLease, state, claim) {
				// The cold control-lease copy is only a fallback snapshot.  When
				// the current lease row itself is corrupt, an expired cold copy
				// cannot establish that the current writer is gone: a valid
				// runtime owner row may have renewed the lease after the cold
				// snapshot was written.  Require a matching, stale/dead runtime
				// owner witness before allowing recovery.
				return fmt.Errorf("%w: sqlite Teams runtime state is corrupt; control lease expiry is not provable", ErrControlLeaseStateUntrusted)
			}
			if !sqliteControlLeaseDefinitelyExpired(lease, claim.Now) {
				return fmt.Errorf("%w: sqlite Teams runtime state is corrupt; control lease expiry is not provable", ErrControlLeaseStateUntrusted)
			}
			overlaySQLiteRequiredRuntimeState(&cold, state, seen)
			return claimControlLeaseSQLiteWithRecoveredRuntime(ctx, tx, claim, cold, invalid, &out)
		}
		if !sqliteRuntimeStateUsable(seen) {
			if materialized {
				return sqliteRuntimeProjectionIncompleteError("missing required runtime rows")
			}
			if !seen[sqliteRuntimeKeyControlLease] && sqliteRuntimeProjectionStarted(seen, invalid) {
				return fmt.Errorf("%w: sqlite control lease projection is missing", ErrControlLeaseStateUntrusted)
			}
			state, err = loadSQLiteLivenessState(ctx, tx)
			if err != nil {
				return err
			}
		}
		decision, err := claimControlLeaseInState(&state, claim)
		out = decision
		if err != nil && !errors.Is(err, errStoreNoChange) {
			return err
		}
		if !errors.Is(err, errStoreNoChange) {
			if err := saveSQLiteRequiredRuntimeStateTx(ctx, tx, state); err != nil {
				return err
			}
		}
		return tx.Commit()
	})
	return out, handled, err
}

// claimControlLeaseSQLiteWithRecoveredRuntime completes the expired-lease
// repair after the caller has established an independent liveness proof.  It
// is kept separate from the normal path so the common heartbeat/claim case
// does not allocate or write an opaque-row record.
func claimControlLeaseSQLiteWithRecoveredRuntime(ctx context.Context, tx *sql.Tx, claim ControlLeaseClaim, cold State, invalid map[string][]byte, out *ControlLeaseDecision) error {
	// The caller passes the cold state as the base.  Valid runtime rows are
	// authoritative where present, while invalid rows deliberately do not
	// overwrite the independently decoded cold values.
	decision, err := claimControlLeaseInState(&cold, claim)
	if out != nil {
		*out = decision
	}
	if err != nil && !errors.Is(err, errStoreNoChange) {
		return err
	}
	if !errors.Is(err, errStoreNoChange) {
		if err := quarantineSQLiteRuntimeRowsTx(ctx, tx, invalid); err != nil {
			return err
		}
		if err := saveSQLiteRequiredRuntimeStateTx(ctx, tx, cold); err != nil {
			return err
		}
	}
	return tx.Commit()
}

func overlaySQLiteRequiredRuntimeState(state *State, runtime State, seen map[string]bool) {
	if state == nil {
		return
	}
	use := func(key string) bool { return seen == nil || seen[key] }
	if use(sqliteRuntimeKeyScope) {
		state.Scope = runtime.Scope
	}
	if use(sqliteRuntimeKeyMachineIdentity) {
		state.MachineIdentity = runtime.MachineIdentity
	}
	if use(sqliteRuntimeKeyMachines) {
		state.Machines = runtime.Machines
	}
	if use(sqliteRuntimeKeyControlLease) {
		state.ControlLease = runtime.ControlLease
	}
	if use(sqliteRuntimeKeyServiceOwner) {
		state.ServiceOwner = runtime.ServiceOwner
	}
	if use(sqliteRuntimeKeyLockOwner) {
		state.LockOwner = runtime.LockOwner
	}
	state.ensure(time.Time{})
}

func sqliteControlLeaseDefinitelyExpired(lease ControlLease, now time.Time) bool {
	if now.IsZero() {
		now = time.Now()
	}
	if strings.TrimSpace(lease.HolderMachineID) == "" || lease.LeaseUntil.IsZero() {
		return false
	}
	if lease.Status != "" && lease.Status != ControlLeaseStatusActive {
		return false
	}
	return !lease.LeaseUntil.After(now)
}

// sqliteCorruptControlLeaseExpiryProven allows the cold lease snapshot to be
// used only when the current runtime owner projection independently confirms
// that the holder represented by that snapshot is no longer live.  A cold
// lease can be older than a valid runtime heartbeat, so checking its expiry
// alone would let a claimant split ownership after a torn control_lease write.
func sqliteCorruptControlLeaseExpiryProven(cold ControlLease, runtime State, claim ControlLeaseClaim) bool {
	if !sqliteControlLeaseDefinitelyExpired(cold, claim.Now) || strings.TrimSpace(cold.HolderMachineID) == "" {
		return false
	}
	foundMatchingWitness := false
	for _, owner := range []*OwnerMetadata{runtime.ServiceOwner, runtime.LockOwner} {
		if owner == nil || strings.TrimSpace(owner.MachineID) == "" {
			continue
		}
		if !IsStale(*owner, claim.Duration, claim.Now) && !OwnerAppearsLocallyDead(*owner) {
			return false
		}
		if strings.TrimSpace(owner.MachineID) == strings.TrimSpace(cold.HolderMachineID) &&
			(cold.Generation <= 0 || owner.LeaseGeneration == cold.Generation) {
			foundMatchingWitness = true
		}
	}
	return foundMatchingWitness
}

const sqliteRuntimeOpaqueMetaPrefix = "runtime_opaque:"

func quarantineSQLiteRuntimeRowsTx(ctx context.Context, tx *sql.Tx, invalid map[string][]byte) error {
	keys := make([]string, 0, len(invalid))
	for key := range invalid {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		raw := invalid[key]
		metaKey := sqliteRuntimeOpaqueMetaPrefix + key + ":" + sha256Bytes(raw)
		if _, err := tx.ExecContext(ctx, `INSERT OR IGNORE INTO state_meta(key, value) VALUES (?, ?)`, metaKey, raw); err != nil {
			return err
		}
	}
	return nil
}

func loadSQLiteRequiredRuntimeState(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (State, map[string]bool, error) {
	state, seen, invalid, err := loadSQLiteRequiredRuntimeStateDetailed(ctx, q)
	if err != nil {
		return State{}, nil, err
	}
	if len(invalid) != 0 {
		return State{}, nil, invalidSQLiteRequiredRuntimeError(invalid)
	}
	return state, seen, nil
}

// loadSQLiteRequiredRuntimeStateDetailed decodes required runtime rows one at
// a time.  Liveness callers need to distinguish a missing/invalid row from a
// query failure: a malformed projection row must not make an expired lease
// impossible to recover, but it must never be treated as valid ownership
// evidence either.  The normal/full-state loader above remains strict so a
// diagnostic or migration cannot silently hide corrupt state.
func loadSQLiteRequiredRuntimeStateDetailed(ctx context.Context, q interface {
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (State, map[string]bool, map[string][]byte, error) {
	state := State{SchemaVersion: SchemaVersion, Machines: map[string]MachineRecord{}}
	seen := make(map[string]bool)
	invalid := make(map[string][]byte)
	keys := make([]string, len(sqliteRuntimeRequiredKeys))
	args := make([]any, len(sqliteRuntimeRequiredKeys))
	for i, key := range sqliteRuntimeRequiredKeys {
		keys[i] = "?"
		args[i] = key
	}
	rows, err := q.QueryContext(ctx, `SELECT key, json FROM runtime_state WHERE key IN (`+strings.Join(keys, ",")+`)`, args...)
	if err != nil {
		return State{}, nil, nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var key string
		var raw []byte
		if err := rows.Scan(&key, &raw); err != nil {
			return State{}, nil, nil, err
		}
		valid := true
		switch key {
		case sqliteRuntimeKeyScope:
			if !sqliteRuntimeObjectJSON(raw) {
				valid = false
			} else if err := json.Unmarshal(raw, &state.Scope); err != nil {
				valid = false
			}
		case sqliteRuntimeKeyMachineIdentity:
			if !sqliteRuntimeObjectJSON(raw) {
				valid = false
			} else if err := json.Unmarshal(raw, &state.MachineIdentity); err != nil {
				valid = false
			}
		case sqliteRuntimeKeyMachines:
			if !sqliteRuntimeObjectJSON(raw) {
				valid = false
			} else if err := json.Unmarshal(raw, &state.Machines); err != nil {
				valid = false
			}
			if valid && state.Machines == nil {
				state.Machines = map[string]MachineRecord{}
			}
		case sqliteRuntimeKeyControlLease:
			if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
				valid = false
			} else if err := json.Unmarshal(raw, &state.ControlLease); err != nil {
				valid = false
			}
			if valid {
				if err := validateControlLeaseShape(state.ControlLease); err != nil {
					valid = false
				}
			}
		case sqliteRuntimeKeyServiceOwner:
			var owner *OwnerMetadata
			if err := json.Unmarshal(raw, &owner); err != nil {
				valid = false
			}
			if valid {
				state.ServiceOwner = owner
			}
		case sqliteRuntimeKeyLockOwner:
			var owner *OwnerMetadata
			if err := json.Unmarshal(raw, &owner); err != nil {
				valid = false
			}
			if valid {
				state.LockOwner = owner
			}
		default:
			continue
		}
		if valid {
			seen[key] = true
		} else {
			invalid[key] = append([]byte(nil), raw...)
		}
	}
	if err := rows.Err(); err != nil {
		return State{}, nil, nil, err
	}
	state.ensure(time.Time{})
	return state, seen, invalid, nil
}

func saveSQLiteRequiredRuntimeStateTx(ctx context.Context, tx *sql.Tx, state State) error {
	values := map[string]any{
		sqliteRuntimeKeyScope:           state.Scope,
		sqliteRuntimeKeyMachineIdentity: state.MachineIdentity,
		sqliteRuntimeKeyMachines:        state.Machines,
		sqliteRuntimeKeyControlLease:    state.ControlLease,
		sqliteRuntimeKeyServiceOwner:    state.ServiceOwner,
		sqliteRuntimeKeyLockOwner:       state.LockOwner,
	}
	for _, key := range sqliteRuntimeRequiredKeys {
		raw, err := json.Marshal(values[key])
		if err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `INSERT INTO runtime_state(key, json) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET json = excluded.json`, key, raw); err != nil {
			return err
		}
	}
	_, err := tx.ExecContext(ctx, `INSERT INTO state_meta(key, value) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET value = excluded.value`, sqliteRuntimeProjectionMaterializedKey, sqliteRuntimeProjectionMaterializedValue)
	return err
}

// saveSQLiteRequiredRuntimeStatePreservingInvalidTx updates the rows that can
// be decoded while leaving an opaque required row byte-for-byte intact. This
// is used by low-risk owner cleanup/release operations: a malformed scope or
// machine projection must not strand a valid lease, but the cleanup must not
// replace evidence that still requires explicit repair. The invalid raw bytes
// are copied to state_meta by the caller before commit.
func saveSQLiteRequiredRuntimeStatePreservingInvalidTx(ctx context.Context, tx *sql.Tx, state State, invalid map[string][]byte) error {
	values := map[string]any{
		sqliteRuntimeKeyScope:           state.Scope,
		sqliteRuntimeKeyMachineIdentity: state.MachineIdentity,
		sqliteRuntimeKeyMachines:        state.Machines,
		sqliteRuntimeKeyControlLease:    state.ControlLease,
		sqliteRuntimeKeyServiceOwner:    state.ServiceOwner,
		sqliteRuntimeKeyLockOwner:       state.LockOwner,
	}
	for _, key := range sqliteRuntimeRequiredKeys {
		if _, opaque := invalid[key]; opaque {
			continue
		}
		raw, err := json.Marshal(values[key])
		if err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `INSERT INTO runtime_state(key, json) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET json = excluded.json`, key, raw); err != nil {
			return err
		}
	}
	return markSQLiteRuntimeProjectionMaterializedTx(ctx, tx)
}

func invalidSQLiteRequiredRuntimeError(invalid map[string][]byte) error {
	if raw, ok := invalid[sqliteRuntimeKeyControlLease]; ok {
		var lease ControlLease
		if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
			return fmt.Errorf("%w: invalid sqlite control lease row: null", ErrControlLeaseStateUntrusted)
		}
		if err := json.Unmarshal(raw, &lease); err != nil {
			return fmt.Errorf("%w: invalid sqlite control lease row: %v", ErrControlLeaseStateUntrusted, err)
		}
		if err := validateControlLeaseShape(lease); err != nil {
			return err
		}
		return fmt.Errorf("%w: invalid sqlite control lease row", ErrControlLeaseStateUntrusted)
	}
	keys := make([]string, 0, len(invalid))
	for key := range invalid {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	if len(keys) == 0 {
		return nil
	}
	return fmt.Errorf("invalid sqlite required runtime row %q", keys[0])
}

// loadSQLiteLivenessState is the compatibility fallback for an incomplete
// runtime projection. It starts from the cold state document but overlays only
// the ownership/lease rows that are required for a liveness decision. Optional
// lifecycle rows must not be decoded here: a damaged upgrade or auto-update
// row must not prevent a replacement owner from claiming the service.
func loadSQLiteLivenessState(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (State, error) {
	var raw []byte
	if err := q.QueryRowContext(ctx, `SELECT value FROM state_meta WHERE key = 'state_json'`).Scan(&raw); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return State{}, errors.New("sqlite teams store is missing state metadata")
		}
		return State{}, err
	}
	if len(raw) == 0 {
		return State{}, errors.New("sqlite teams store has empty state metadata")
	}
	state, err := loadStateData(raw)
	if err != nil {
		return State{}, err
	}
	state.ensure(time.Time{})
	runtimeState, seen, invalid, err := loadSQLiteRequiredRuntimeStateDetailed(ctx, q)
	if err != nil {
		return State{}, err
	}
	if !seen[sqliteRuntimeKeyControlLease] && sqliteRuntimeProjectionStarted(seen, invalid) {
		return State{}, fmt.Errorf("%w: sqlite control lease projection is missing", ErrControlLeaseStateUntrusted)
	}
	// Overlay each required row independently. A partially materialized
	// projection is expected during older migrations or narrow repairs; rows
	// that are present (including an explicit NULL owner) are still stronger
	// evidence than the cold document. Missing rows continue to use the cold
	// compatibility value. Optional runtime rows are intentionally never read.
	if seen[sqliteRuntimeKeyScope] {
		state.Scope = runtimeState.Scope
	}
	if seen[sqliteRuntimeKeyMachineIdentity] {
		state.MachineIdentity = runtimeState.MachineIdentity
	}
	if seen[sqliteRuntimeKeyMachines] {
		state.Machines = runtimeState.Machines
	}
	if seen[sqliteRuntimeKeyControlLease] {
		state.ControlLease = runtimeState.ControlLease
	}
	if seen[sqliteRuntimeKeyServiceOwner] {
		state.ServiceOwner = runtimeState.ServiceOwner
	}
	if seen[sqliteRuntimeKeyLockOwner] {
		state.LockOwner = runtimeState.LockOwner
	}
	// Invalid required rows are deliberately treated as absent here.  This
	// fallback is used only to make a liveness decision; the claimant path keeps
	// their raw bytes in an opaque audit record after independently proving that
	// the old lease is expired.  Do not let a malformed row become a replacement
	// owner's evidence.
	_ = invalid
	state.ensure(time.Time{})
	if err := validateControlLeaseShape(state.ControlLease); err != nil {
		return State{}, err
	}
	return state, nil
}

// rejectIncompleteMaterializedRuntimeProjection prevents the small liveness
// cleanup APIs from falling back to state_json after the SQLite runtime
// projection has become authoritative. A missing runtime row is not the same
// as a legacy store with no projection at all: the cold document may describe
// an older process and using it to release/clear ownership could either erase
// a newer owner or recreate stale ownership evidence. An invalid row is kept
// as opaque evidence by the caller, so it counts as present here; the specific
// liveness operation below still rejects an invalid row when it is part of its
// own proof (for example control_lease for release or owner rows for clear).
// Schema preparation is the explicit repair boundary for a genuinely missing
// row.
func rejectIncompleteMaterializedRuntimeProjection(materialized bool, seen map[string]bool, invalid map[string][]byte) error {
	if !materialized {
		return nil
	}
	for _, key := range sqliteRuntimeRequiredKeys {
		if !seen[key] && invalid[key] == nil {
			return sqliteRuntimeProjectionIncompleteError("required runtime rows are missing")
		}
	}
	return nil
}

// loadSQLiteControlLease reads only the owner capability needed by an
// attempt-scoped outbox CAS. Keeping this narrower than loadSQLiteLivenessState
// avoids decoding the cold state document on every normal send transition,
// while retaining the legacy fallback for stores created before the runtime
// projection was materialized.
func loadSQLiteControlLease(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (ControlLease, error) {
	var raw []byte
	err := q.QueryRowContext(ctx, `SELECT json FROM runtime_state WHERE key = ?`, sqliteRuntimeKeyControlLease).Scan(&raw)
	if errors.Is(err, sql.ErrNoRows) {
		// A completely empty runtime table is the pre-migration legacy shape and
		// may safely fall back to state_json. Once any required projection row
		// exists, however, a missing lease row is an incomplete ownership record;
		// using the cold copy could claim over a writer whose lease update was
		// torn. Hold until the projection is explicitly repaired.
		materialized, materializedErr := sqliteRuntimeProjectionMaterialized(ctx, q)
		if materializedErr != nil {
			return ControlLease{}, materializedErr
		}
		if materialized {
			return ControlLease{}, sqliteRuntimeProjectionIncompleteError("control lease row is missing")
		}
		var runtimeKey string
		projectionErr := q.QueryRowContext(ctx, `SELECT key FROM runtime_state WHERE key IN (?, ?, ?, ?, ?, ?) LIMIT 1`,
			sqliteRuntimeRequiredKeys[0], sqliteRuntimeRequiredKeys[1], sqliteRuntimeRequiredKeys[2],
			sqliteRuntimeRequiredKeys[3], sqliteRuntimeRequiredKeys[4], sqliteRuntimeRequiredKeys[5]).Scan(&runtimeKey)
		if projectionErr == nil {
			return ControlLease{}, fmt.Errorf("%w: sqlite control lease projection is missing", ErrControlLeaseStateUntrusted)
		}
		if !errors.Is(projectionErr, sql.ErrNoRows) {
			return ControlLease{}, projectionErr
		}
		state, loadErr := loadSQLiteLivenessState(ctx, q)
		if loadErr != nil {
			return ControlLease{}, loadErr
		}
		if err := validateControlLeaseShape(state.ControlLease); err != nil {
			return ControlLease{}, err
		}
		return state.ControlLease, nil
	}
	if err != nil {
		return ControlLease{}, err
	}
	var lease ControlLease
	if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return ControlLease{}, fmt.Errorf("%w: invalid sqlite control lease row: null", ErrControlLeaseStateUntrusted)
	}
	if err := json.Unmarshal(raw, &lease); err != nil {
		return ControlLease{}, fmt.Errorf("%w: invalid sqlite control lease row: %v", ErrControlLeaseStateUntrusted, err)
	}
	if err := validateControlLeaseShape(lease); err != nil {
		return ControlLease{}, err
	}
	return lease, nil
}

// loadSQLiteControlLeaseForSchemaPreparation is intentionally more
// conservative than the normal liveness reader.  A schema repair may need to
// recreate runtime_state, so an empty/incompatible runtime table cannot be
// allowed to make preparation impossible.  Falling back to the cold lease is
// safe only when the runtime projection is absent or completely empty; if any
// runtime rows exist while the lease row is missing, the caller must remain
// fail-closed because those rows could be evidence of a live owner.
func loadSQLiteControlLeaseForSchemaPreparation(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}) (ControlLease, error) {
	lease, err := loadSQLiteControlLease(ctx, q)
	if err == nil {
		return lease, nil
	}
	if !errors.Is(err, ErrSQLiteRuntimeProjectionIncomplete) &&
		!strings.Contains(strings.ToLower(err.Error()), "no such table") {
		return ControlLease{}, err
	}
	if !strings.Contains(strings.ToLower(err.Error()), "no such table") {
		var rows int64
		if countErr := q.QueryRowContext(ctx, `SELECT COUNT(*) FROM runtime_state`).Scan(&rows); countErr != nil {
			return ControlLease{}, countErr
		}
		if rows != 0 {
			return ControlLease{}, err
		}
	}
	return loadSQLiteColdControlLease(ctx, q)
}

func loadSQLiteColdControlLease(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}) (ControlLease, error) {
	var raw []byte
	if err := q.QueryRowContext(ctx, `SELECT value FROM state_meta WHERE key = 'state_json'`).Scan(&raw); err != nil {
		return ControlLease{}, err
	}
	state, err := loadStateData(raw)
	if err != nil {
		return ControlLease{}, err
	}
	if err := validateControlLeaseShape(state.ControlLease); err != nil {
		return ControlLease{}, err
	}
	return state.ControlLease, nil
}

func sqliteStoreOwnerCapabilityMatchesTx(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, machineID string, leaseGeneration int64) (bool, error) {
	if leaseGeneration <= 0 {
		return true, nil
	}
	lease, err := loadSQLiteControlLease(ctx, q)
	if err != nil {
		return false, err
	}
	state := State{ControlLease: lease}
	return storeOwnerCapabilityMatchesState(&state, machineID, leaseGeneration), nil
}

func sqliteStoreActiveOwnerCapabilityMatchesTx(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
	QueryContext(context.Context, string, ...any) (*sql.Rows, error)
}, machineID string, leaseGeneration int64) (bool, error) {
	if leaseGeneration <= 0 {
		return true, nil
	}
	lease, err := loadSQLiteControlLease(ctx, q)
	if err != nil {
		return false, err
	}
	state := State{ControlLease: lease}
	return storeOwnerCapabilityMatchesActiveLease(&state, machineID, leaseGeneration), nil
}

func (s *Store) validateControlLeaseSQLite(ctx context.Context, machineID string, generation int64, now time.Time) (ControlLease, bool, error) {
	var out ControlLease
	handled, err := s.withSQLiteRuntimeDB(ctx, func(db *sql.DB) error {
		var raw []byte
		err := db.QueryRowContext(ctx, `SELECT json FROM runtime_state WHERE key = ?`, sqliteRuntimeKeyControlLease).Scan(&raw)
		if errors.Is(err, sql.ErrNoRows) {
			// Once the runtime projection has been published, a missing lease row
			// is ownership-unknown. Do not resurrect an older cold lease from
			// state_json merely because every other runtime row was also deleted.
			// ClaimControlLease/loadSQLiteControlLease use the same fail-closed
			// boundary; ValidateControlLease must not be a weaker alternate path.
			materialized, markerErr := sqliteRuntimeProjectionMaterialized(ctx, db)
			if markerErr != nil {
				return markerErr
			}
			if materialized {
				return sqliteRuntimeProjectionIncompleteError("control lease row is missing")
			}
			state, loadErr := loadSQLiteLivenessState(ctx, db)
			if loadErr != nil {
				return loadErr
			}
			out = state.ControlLease
		} else if err != nil {
			return err
		} else if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
			return fmt.Errorf("%w: invalid sqlite control lease row: null", ErrControlLeaseStateUntrusted)
		} else if err := json.Unmarshal(raw, &out); err != nil {
			return fmt.Errorf("%w: invalid sqlite control lease row: %v", ErrControlLeaseStateUntrusted, err)
		}
		if err := validateControlLeaseShape(out); err != nil {
			return err
		}
		if out.HolderMachineID != machineID || out.Generation != generation || !out.LeaseUntil.After(now) {
			return ErrControlLeaseNotHeld
		}
		return nil
	})
	return out, handled, err
}

func (s *Store) releaseControlLeaseSQLite(ctx context.Context, machineID string, generation int64) (bool, bool, error) {
	released := false
	handled, err := s.withSQLiteRuntimeDB(ctx, func(db *sql.DB) error {
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		state, seen, invalid, err := loadSQLiteRequiredRuntimeStateDetailed(ctx, tx)
		if err != nil {
			return err
		}
		materialized, err := sqliteRuntimeProjectionMaterialized(ctx, tx)
		if err != nil {
			return err
		}
		if err := rejectIncompleteMaterializedRuntimeProjection(materialized, seen, invalid); err != nil {
			return err
		}
		if _, opaque := invalid[sqliteRuntimeKeyControlLease]; opaque {
			return invalidSQLiteRequiredRuntimeError(invalid)
		}
		if !materialized && !sqliteRuntimeStateUsable(seen) {
			state, err = loadSQLiteLivenessState(ctx, tx)
			if err != nil {
				return err
			}
		}
		lease := state.ControlLease
		if err := validateKnownControlLeaseStatus(lease); err != nil {
			return err
		}
		if lease.HolderMachineID != machineID || lease.Generation != generation {
			return tx.Commit()
		}
		if strings.TrimSpace(lease.ScopeID) == "" {
			lease.ScopeID = state.Scope.ID
		}
		lease.HolderMachineID = ""
		lease.HolderKind = ""
		lease.Priority = 0
		lease.Status = ""
		lease.LeaseUntil = time.Time{}
		lease.LastHeartbeat = time.Time{}
		lease.UpdatedAt = time.Now()
		state.ControlLease = lease
		if machine := state.Machines[machineID]; machine.ID != "" {
			machine.Status = MachineStatusStandby
			machine.UpdatedAt = time.Now()
			state.Machines[machineID] = machine
		}
		if err := quarantineSQLiteRuntimeRowsTx(ctx, tx, invalid); err != nil {
			return err
		}
		if err := saveSQLiteRequiredRuntimeStatePreservingInvalidTx(ctx, tx, state, invalid); err != nil {
			return err
		}
		released = true
		return tx.Commit()
	})
	return released, handled, err
}

func (s *Store) recordOwnerHeartbeatSQLite(ctx context.Context, owner OwnerMetadata, staleAfter time.Duration, now time.Time) (OwnerMetadata, bool, error) {
	var out OwnerMetadata
	handled, err := s.withSQLiteRuntimeDB(ctx, func(db *sql.DB) error {
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		if blocked, blockErr := sqliteSchemaPreparationClaimBlocksHeartbeat(ctx, tx); blockErr != nil {
			return blockErr
		} else if blocked {
			return ErrSQLiteSchemaPreparationInProgress
		}
		state, _, invalid, present, err := loadSQLiteOwnerRuntimeDetailed(ctx, tx)
		if err != nil {
			return err
		}
		if len(invalid) != 0 {
			// An untrusted owner row may conceal a live process. The unscoped
			// compatibility heartbeat has no capability with which to repair an
			// entirely opaque owner projection, so require at least one valid
			// owner witness and let the normal conflict check decide whether the
			// caller is that owner.
			if _, ok := state.readOwner(); !ok {
				return invalidSQLiteOwnerRuntimeError(invalid)
			}
		}
		if !present {
			state, err = loadSQLiteLivenessState(ctx, tx)
			if err != nil {
				return err
			}
		}
		// The owner-only projection intentionally avoids optional runtime rows,
		// but the control lease is part of the safety boundary even for the
		// legacy heartbeat API. Load it explicitly so an unknown lease status
		// cannot be overwritten by an unscoped owner heartbeat just because the
		// owner rows themselves are valid.
		state.ControlLease, err = loadSQLiteControlLease(ctx, tx)
		if err != nil {
			return err
		}
		next, err := recordOwnerHeartbeatInState(&state, owner, staleAfter, now)
		if err != nil {
			return err
		}
		out = next
		if err := saveSQLiteOwnerRuntimeTx(ctx, tx, next); err != nil {
			return err
		}
		if err := quarantineSQLiteRuntimeRowsTx(ctx, tx, invalid); err != nil {
			return err
		}
		return tx.Commit()
	})
	return out, handled, err
}

// recordOwnerHeartbeatForLeaseSQLite is deliberately narrower than a full
// state write. It reads the owner rows and the control-lease row in one
// transaction, validates the captured generation, then persists both before
// commit. A delayed callback from a retired listener therefore cannot renew
// or replace the current owner.
func (s *Store) recordOwnerHeartbeatForLeaseSQLite(ctx context.Context, owner OwnerMetadata, staleAfter time.Duration, leaseDuration time.Duration, now time.Time) (OwnerMetadata, bool, error) {
	var out OwnerMetadata
	handled, err := s.withSQLiteRuntimeDB(ctx, func(db *sql.DB) error {
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		if blocked, blockErr := sqliteSchemaPreparationClaimBlocksHeartbeat(ctx, tx); blockErr != nil {
			return blockErr
		} else if blocked {
			return ErrSQLiteSchemaPreparationInProgress
		}
		state, _, invalid, present, err := loadSQLiteOwnerRuntimeDetailed(ctx, tx)
		if err != nil {
			return err
		}
		// A capability-bound heartbeat can repair an opaque owner projection,
		// but only after the control-lease row independently proves that this
		// callback owns the current generation. If a valid peer owner exists,
		// retain it as an additional conflict witness; otherwise use the cold
		// state only as compatibility evidence and let the capability check run
		// before any write.
		if len(invalid) != 0 {
			if _, ok := state.readOwner(); !ok {
				state, err = loadSQLiteLivenessState(ctx, tx)
				if err != nil {
					return err
				}
			}
		} else if !present {
			state, err = loadSQLiteLivenessState(ctx, tx)
			if err != nil {
				return err
			}
		}
		state.ControlLease, err = loadSQLiteControlLease(ctx, tx)
		if err != nil {
			return err
		}
		next, err := recordOwnerHeartbeatForLeaseInState(&state, owner, staleAfter, leaseDuration, now)
		if err != nil {
			return err
		}
		out = next
		if err := saveSQLiteOwnerRuntimeTx(ctx, tx, next); err != nil {
			return err
		}
		if err := saveSQLiteControlLeaseTx(ctx, tx, state.ControlLease); err != nil {
			return err
		}
		if err := quarantineSQLiteRuntimeRowsTx(ctx, tx, invalid); err != nil {
			return err
		}
		return tx.Commit()
	})
	return out, handled, err
}

func saveSQLiteControlLeaseTx(ctx context.Context, tx *sql.Tx, lease ControlLease) error {
	raw, err := json.Marshal(lease)
	if err != nil {
		return err
	}
	if _, err = tx.ExecContext(ctx, `INSERT INTO runtime_state(key, json) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET json = excluded.json`, sqliteRuntimeKeyControlLease, raw); err != nil {
		return err
	}
	return markSQLiteRuntimeProjectionMaterializedTx(ctx, tx)
}

// loadSQLiteOwnerRuntime intentionally reads only the two owner rows. An
// unrelated optional runtime row (upgrade/service-control/auto-update) is not
// part of liveness proof and must not be able to stop a heartbeat or owner
// diagnostic.
func loadSQLiteOwnerRuntime(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}) (State, bool, bool, error) {
	state, _, invalid, present, err := loadSQLiteOwnerRuntimeDetailed(ctx, q)
	if err != nil {
		return State{}, false, false, err
	}
	if len(invalid) != 0 {
		return State{}, false, false, invalidSQLiteOwnerRuntimeError(invalid)
	}
	return state, state.ServiceOwner != nil || state.LockOwner != nil, present, nil
}

func invalidSQLiteOwnerRuntimeError(invalid map[string][]byte) error {
	keys := make([]string, 0, len(invalid))
	for key := range invalid {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	if len(keys) == 0 {
		return nil
	}
	return fmt.Errorf("invalid sqlite owner runtime row %q", keys[0])
}

// loadSQLiteOwnerRuntimeDetailed reads the two owner rows independently. A
// targeted heartbeat only needs a valid owner witness and an independently
// validated control lease; an unrelated malformed compatibility copy should
// not force a healthy listener into a restart loop. The strict wrapper above
// remains available to callers that require a complete owner projection.
func loadSQLiteOwnerRuntimeDetailed(ctx context.Context, q interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}) (State, map[string]bool, map[string][]byte, bool, error) {
	state := State{}
	seen := make(map[string]bool)
	invalid := make(map[string][]byte)
	present := false
	for _, key := range []string{sqliteRuntimeKeyServiceOwner, sqliteRuntimeKeyLockOwner} {
		var raw []byte
		err := q.QueryRowContext(ctx, `SELECT json FROM runtime_state WHERE key = ?`, key).Scan(&raw)
		if errors.Is(err, sql.ErrNoRows) {
			continue
		}
		if err != nil {
			return State{}, nil, nil, false, err
		}
		present = true
		var owner *OwnerMetadata
		if err := json.Unmarshal(raw, &owner); err != nil {
			invalid[key] = append([]byte(nil), raw...)
			continue
		}
		seen[key] = true
		if owner == nil {
			continue
		}
		if key == sqliteRuntimeKeyServiceOwner {
			state.ServiceOwner = owner
		} else {
			state.LockOwner = owner
		}
	}
	return state, seen, invalid, present, nil
}

func saveSQLiteOwnerRuntimeTx(ctx context.Context, tx *sql.Tx, owner OwnerMetadata) error {
	raw, err := json.Marshal(owner)
	if err != nil {
		return err
	}
	for _, key := range []string{sqliteRuntimeKeyServiceOwner, sqliteRuntimeKeyLockOwner} {
		if _, err := tx.ExecContext(ctx, `INSERT INTO runtime_state(key, json) VALUES (?, ?)
ON CONFLICT(key) DO UPDATE SET json = excluded.json`, key, raw); err != nil {
			return err
		}
	}
	return markSQLiteRuntimeProjectionMaterializedTx(ctx, tx)
}

func (s *Store) readOwnerSQLite(ctx context.Context) (OwnerMetadata, bool, bool, error) {
	var out OwnerMetadata
	found := false
	handled, err := s.withSQLiteRuntimeReadDB(ctx, func(db *sql.DB) error {
		materialized, err := sqliteRuntimeProjectionMaterialized(ctx, db)
		if err != nil {
			return err
		}
		if materialized {
			state, seen, invalid, err := loadSQLiteRequiredRuntimeStateDetailed(ctx, db)
			if err != nil {
				return err
			}
			if err := rejectIncompleteMaterializedRuntimeProjection(materialized, seen, invalid); err != nil {
				return err
			}
			for _, key := range []string{sqliteRuntimeKeyServiceOwner, sqliteRuntimeKeyLockOwner} {
				if _, opaque := invalid[key]; opaque {
					return invalidSQLiteRequiredRuntimeError(invalid)
				}
			}
			out, found = state.readOwner()
			return nil
		}
		state, _, present, err := loadSQLiteOwnerRuntime(ctx, db)
		if err != nil {
			return err
		}
		if present {
			// Owner rows are compatibility copies.  Load the lease alongside
			// them so State.readOwner can prefer a valid lock-owner witness when
			// the service-owner copy is stale or semantically incomplete.
			state.ControlLease, err = loadSQLiteControlLease(ctx, db)
			if err != nil {
				return err
			}
		} else {
			state, err = loadSQLiteLivenessState(ctx, db)
			if err != nil {
				return err
			}
		}
		out, found = state.readOwner()
		return nil
	})
	return out, found, handled, err
}

func (s *Store) clearOwnerIfSameSQLite(ctx context.Context, owner OwnerMetadata) (bool, bool, error) {
	cleared := false
	handled, err := s.withSQLiteRuntimeDB(ctx, func(db *sql.DB) error {
		tx, err := db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		defer tx.Rollback()
		state, seen, invalid, err := loadSQLiteRequiredRuntimeStateDetailed(ctx, tx)
		if err != nil {
			return err
		}
		materialized, err := sqliteRuntimeProjectionMaterialized(ctx, tx)
		if err != nil {
			return err
		}
		if err := rejectIncompleteMaterializedRuntimeProjection(materialized, seen, invalid); err != nil {
			return err
		}
		if _, opaque := invalid[sqliteRuntimeKeyControlLease]; opaque {
			return invalidSQLiteRequiredRuntimeError(invalid)
		}
		for _, key := range []string{sqliteRuntimeKeyServiceOwner, sqliteRuntimeKeyLockOwner} {
			if _, opaque := invalid[key]; opaque {
				return invalidSQLiteRequiredRuntimeError(invalid)
			}
		}
		if !materialized && !sqliteRuntimeStateUsable(seen) {
			state, err = loadSQLiteLivenessState(ctx, tx)
			if err != nil {
				return err
			}
		}
		existing, ok := state.readOwner()
		if !ok || !sameOwnerForLeaseCleanup(existing, owner) {
			return tx.Commit()
		}
		state.ServiceOwner = nil
		state.LockOwner = nil
		if err := quarantineSQLiteRuntimeRowsTx(ctx, tx, invalid); err != nil {
			return err
		}
		if err := saveSQLiteRequiredRuntimeStatePreservingInvalidTx(ctx, tx, state, invalid); err != nil {
			return err
		}
		cleared = true
		return tx.Commit()
	})
	return cleared, handled, err
}

// recoverIfOwnerSameSQLite performs the CLI recovery read, owner fence, and
// full restart disposition under one Store/file-lock critical section. The
// SQLite write itself is one transaction, so a process crash cannot expose
// recovered turns/outbox rows while retaining the stale owner clear half-way.
func (s *Store) recoverIfOwnerSameSQLite(ctx context.Context, expected OwnerMetadata, expectOwner bool) (RecoveryReport, bool, bool, error) {
	var report RecoveryReport
	applied := false
	handled := false
	err := s.withStateLock(ctx, func() error {
		pointer, ok, err := s.currentSQLitePointerUnlocked()
		if err != nil || !ok {
			return err
		}
		db, err := s.sqliteDBUnlocked(pointer)
		if err != nil {
			return err
		}
		handled = true
		state, err := loadSQLiteState(ctx, db)
		if err != nil {
			return err
		}
		existing, ownerPresent := state.readOwner()
		if expectOwner {
			if !ownerPresent || !sameOwnerForLeaseCleanup(existing, expected) {
				return nil
			}
		} else if ownerPresent {
			return nil
		}
		changed := recoverStateLocked(&state, &report, time.Now())
		if !changed && !expectOwner {
			applied = true
			return nil
		}
		if err := writeSQLiteStateWithOptions(ctx, db, state, expectOwner); err != nil {
			return err
		}
		if s.messageLookup.Valid {
			s.replaceMessageLookupCacheFromStateLocked(state)
		}
		applied = true
		return nil
	})
	return report, applied, handled, err
}

